INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deanmoses/tacocat-gallery-hosting-aws/commit', 'commit', 'deanmoses', 'tacocat-gallery-hosting-aws', 'community', 'commit deanmoses tacocat-gallery-hosting-aws community The commit skill enables developers to manage code changes using the Conventional Commits format, supporting features like feat, fix, and docs. It benefits developers working on static SPA website hosting projects. Commit 是一个使用 Conventional Commits 格式的静态 SPA 网站托管工具，支持 Tacocat Gallery。 Commit は Conventional Commits 形式を使用する静的 SPA サイト ホスティング ツールで、Tacocat Gallery をサポートしています。 Commit은 Conventional Commits 형식을 사용하는 정적 SPA 웹사이트 호스팅 도구로 Tacocat 갤러리를 지원합니다. Esta habilidad implementa el formato Conventional Commits para mensajes de commit, definiendo tipos como `feat`, `fix` y `docs`. Proporciona una estructura clara para mejorar la legibilidad del historial y facilitar el versionado semántico. Cette compétence implémente le format Conventional Commits pour les messages de commit, en définissant des types comme `feat`, `fix` et `docs`. Elle offre une structure claire pour améliorer la lisibilité de l''historique et faciliter le versioning sémantique. Dieses Skill implementiert das Conventional Commits-Format für Commit-Nachrichten und definiert Typen wie `feat`, `fix` und `docs`. Es bietet eine klare Struktur zur Verbesserung der Historiengenauigkeit und erleichtert semantische Versionierung. Este skill padroniza mensagens de commit usando o formato Conventional Commits, definindo tipos como `feat` para funcionalidades e `fix` para correções. É essencial para manter um histórico de projeto claro e automatizar changelogs. Этот навык стандартизирует сообщения коммитов с использованием формата Conventional Commits, определяя типы, такие как `feat` для функций и `fix` для исправлений. Важно для поддержания ясной истории проекта и автоматизации changelogs. تحدد هذه المهارة رسائل الـ Commit باستخدام تنسيق Conventional Commits، مع تعريف أنواع مثل `feat` للميزات و`fix` للإصلاحات. إنه ضروري للحفاظ على سجل مشروع واضح وأتمتة سجلات التغيير (changelogs). how to use commit Conventional Commits tutorial commit alternative commit vs semantic release commit install guide commit setup for static SPA what is commit commit best practices commit for AI agents Commit Conventional Commits Tacocat Gallery 静态 SPA 网站托管 Commit 消息格式 feat Commit fix Commit docs Commit Supports Conventional Commits format for consistent commit messages Includes feat type for user-facing features and behavior changes Enables fix type for efficient bug fixes and production code updates Provides docs type for documentation-only changes Allows style type for code style and formatting adjustments Includes refactor type for code restructuring without behavior changes commit is a skill that utilizes Conventional Commits format for standardized commit messages, enhancing code readability and collaboration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('basehub-ai/forums/remote-bash', 'community', 'basehub-ai', 'forums', 'basehub-ai/forums', 'remote-bash', 0, 0, 51, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:01.838Z', '06b570a3c8886b7145ff480546db28f852e71090c362e2d5ac28d8bde9676aca', '{"id":"basehub-ai/forums/remote-bash","name":"remote-bash","description":{"en":"remote-bash allows developers to execute bash commands against public GitHub repositories without cloning them, supporting targets like owner/repo and package-name formats.","zh":"remote-bash 是一种执行 bash 命令的工具，支持对 GitHub 公共仓库的命令行执行","ja":"remote-bash は GitHub リポジトリに対して bash コマンドを実行するツールです","ko":"remote-bash는 GitHub 공개 리포지토리에 bash 명령어를 실행하는 도구입니다","es":"remote-bash es una herramienta que permite ejecutar comandos de bash en repositorios de GitHub sin clonarlos. Se utiliza mediante la línea de comandos con npx","fr":"remote-bash est un outil qui permet d''exécuter des commandes bash sur des dépôts GitHub sans les cloner. Il est utilisé via la ligne de commande avec npx","de":"remote-bash ist ein Tool, das die Ausführung von Bash-Befehlen in GitHub-Repositorys ohne Klonen ermöglicht. Es wird über die Kommandozeile mit npx verwendet","pt":"O remote-bash é uma ferramenta de linha de comando que permite executar comandos Bash em repositórios GitHub públicos sem clonar. Ele suporta vários formatos de alvo, incluindo owner/repo e package-name","ru":"Remote-bash — это инструмент командной строки, который позволяет выполнять команды Bash в публичных репозиториях GitHub без клонирования. Он поддерживает несколько форматов цели, включая owner/repo и package-name, и использует ИИ Агенты","ar":"remote-bash هو أداة سطر الأوامر التي تسمح بتنفيذ أوامر Bash في مستودعات GitHub العامة بدون استنساخ. يدعم عدة صيغ هدف، بما في ذلك owner/repo و package-name، وتستخدم أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"remote-bash: Execute Bash Commands on GitHub Repos | AI A...","zh":"remote-bash Setup Guide: GitHub仓库命令行执行","ja":"remote-bash を使った GitHub リポジトリへのコマンド実行","ko":"remote-bash 설정 가이드: GitHub 리포지토리 명령어 실행","es":"Guía de configuración de remote-bash para ejecutar comand...","fr":"Guide de configuration de remote-bash pour exécuter des c...","de":"Einrichtungsleitfaden für remote-bash zum Ausführen von B...","pt":"Guia de Configuração do remote-bash: Execução de Comandos...","ru":"Настройка remote-bash: Выполнение команд Bash в публичных...","ar":"دليل إعداد remote-bash: تنفيذ أوامر Bash في مستودعات GitH..."},"description":{"en":"Discover how to run bash commands on any public GitHub repository without cloning, and learn how to get started with remote-bash today!","zh":"了解 remote-bash 的用途和优势，实现对 GitHub 公共仓库的命令行执行，无需克隆","ja":"remote-bash を使用して GitHub リポジトリにコマンドを実行する方法を学ぶ","ko":"remote-bash를 사용하여 GitHub 공개 리포지토리에 명령어를 실행하는 방법을 알아보세요","es":"Aprende a utilizar remote-bash para ejecutar comandos de bash en repositorios de GitHub sin clonarlos","fr":"Découvrez comment utiliser remote-bash pour exécuter des commandes bash sur des dépôts GitHub sans les cloner","de":"Erfahren Sie, wie Sie remote-bash verwenden, um Bash-Befehle in GitHub-Repositorys auszuführen, ohne sie zu klonen","pt":"Aprenda a usar o remote-bash para executar comandos Bash em repositórios GitHub públicos sem clonar. Descubra como usar a ferramenta de linha de comando para...","ru":"Узнайте, как использовать remote-bash для выполнения команд Bash в публичных репозиториях GitHub без клонирования. Откройте для себя, как использовать инстру...","ar":"تعرف على كيفية استخدام remote-bash لتنفيذ أوامر Bash في مستودعات GitHub العامة بدون استنساخ. اكتشف كيفية استخدام أداة سطر الأوامر للآليّة والتطوير مع أدوات ا..."},"definition":{"en":"remote-bash is a command-line tool that enables execution of bash commands on public GitHub repositories without local cloning.","zh":"remote-bash 是一种命令行工具，用于执行 GitHub 公共仓库的 bash 命令","ja":"remote-bash は、GitHub リポジトリに対して bash コマンドを実行するためのコマンドラインツールです","ko":"remote-bash는 GitHub 공개 리포지토리의 bash 명령어를 실행하는 명령줄 도구입니다","es":"remote-bash es una herramienta de línea de comandos que ejecuta comandos de bash en repositorios de GitHub","fr":"remote-bash est un outil de ligne de commande qui exécute des commandes bash sur des dépôts GitHub","de":"remote-bash ist ein Kommandozeilen-Tool, das Bash-Befehle in GitHub-Repositorys ausführt","pt":"O que é remote-bash? É uma ferramenta que permite executar comandos Bash em repositórios GitHub públicos sem clonar","ru":"Что такое remote-bash? Это инструмент, который позволяет выполнять команды Bash в публичных репозиториях GitHub без клонирования с помощью ИИ Агентов","ar":"ما هو remote-bash؟ هو أداة تسمح بتنفيذ أوامر Bash في مستودعات GitHub العامة بدون استنساخ مع أدوات الذكاء الاصطناعي"},"features":{"en":["Executes bash commands on public GitHub repositories using npx remote-bash","Supports target formats like owner/repo and package-name","Resolves package-name targets to repository and exact SHA using local lockfiles","Allows specification of branch or commit reference using -ref option","Enables execution of custom bash commands against targeted repositories"],"zh":["支持对 GitHub 公共仓库的命令行执行","不需要克隆仓库即可执行命令","支持多种目标格式，包括 owner/repo 和 package-name","可指定分支或 Commit SHA","使用 npx 运行，方便快捷"],"ja":["GitHub リポジトリに対して bash コマンドを実行","リポジトリをクローンしなくてもコマンドを実行","複数のターゲット形式をサポート、owner/repo と package-name","ブランチまたは Commit SHA を指定","npx を使用して実行、簡単に実行"],"ko":["GitHub 공개 리포지토리에 bash 명령어를 실행","리포지토리를 복제하지 않고 명령어를 실행","여러 가지 대상 형식을 지원, owner/repo 및 package-name","분기 또는 Commit SHA를 지정","npx를 사용하여 실행, 쉽고 빠르게"],"es":["Ejecuta comandos de bash en repositorios de GitHub sin clonarlos","Soporta formatos de destino como owner/repo y package-name","Permite especificar una rama o commit con la opción -ref","Utiliza npx para ejecutar comandos de bash de manera remota","Lee la versión desde un archivo de bloqueo local y resuelve el SHA exacto para paquetes"],"fr":["Exécute des commandes bash sur des dépôts GitHub sans les cloner","Prend en charge des formats de cible tels que owner/repo et package-name","Permet de spécifier une branche ou un commit avec l''option -ref","Utilise npx pour exécuter des commandes bash de manière distante","Lit la version à partir d''un fichier de verrouillage local et résout le SHA exact pour les packages"],"de":["Führt Bash-Befehle in GitHub-Repositorys aus, ohne sie zu klonen","Unterstützt Ziel-Formate wie owner/repo und package-name","Ermöglicht die Angabe eines Branch oder Commit mit der Option -ref","Verwendet npx, um Bash-Befehle remote auszuführen","Liest die Version aus einer lokalen Lock-Datei und löst den exakten SHA für Pakete"],"pt":["Execução de comandos Bash em repositórios GitHub públicos sem clonar","Suporte a vários formatos de alvo, incluindo owner/repo e package-name","Leitura de versão a partir de arquivo de bloqueio local","Resolução de repositório e SHA exato","Opções de linha de comando para personalização"],"ru":["Выполнение команд Bash в публичных репозиториях GitHub без клонирования","Поддержка нескольких форматов цели, включая owner/repo и package-name","Чтение версии из локального файла блокировки","Разрешение репозитория и точного SHA","Опции командной строки для настройки с помощью ИИ Агентов"],"ar":["تنفيذ أوامر Bash في مستودعات GitHub العامة بدون استنساخ","دعم عدة صيغ هدف، بما في ذلك owner/repo و package-name","قراءة الإصدار من ملف القفل المحلي","حل المستودع وال SHA الدقيق","خيارات سطر الأوامر للتعديل مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use remote-bash","remote-bash alternative","remote-bash install","what is remote-bash","remote-bash setup guide","remote-bash vs git","execute bash on github","github repository bash commands","remote-bash command-line tool"],"zh":["remote-bash","GitHub","bash 命令","命令行工具","npx","AI エージェント","GitHub仓库命令行执行","bash命令执行"],"ja":["remote-bash","GitHub","bash コマンド","コマンドラインツール","npx","AIエージェント","GitHub リポジトリ コマンド実行","bash コマンド実行"],"ko":["remote-bash","GitHub","bash 명령어","명령줄 도구","npx","AI 에이전트","GitHub 공개 리포지토리 명령어 실행","bash 명령어 실행"],"es":["remote-bash","ejecutar comandos de bash","repositorios de GitHub","npx","herramientas de línea de comandos","desarrollo de software","automatización de tareas","gestión de repositorios"],"fr":["remote-bash","exécuter des commandes bash","dépôts GitHub","npx","outils de ligne de commande","développement de logiciels","automatisation de tâches","gestion de dépôts"],"de":["remote-bash","Bash-Befehle ausführen","GitHub-Repositorys","npx","Kommandozeilen-Tools","Software-Entwicklung","Automatisierung von Aufgaben","Repository-Verwaltung"],"pt":["remote-bash","comandos Bash","repositórios GitHub","ferramenta de linha de comando","automação","desenvolvimento","owner/repo","package-name","CLI"],"ru":["remote-bash","команды Bash","репозитории GitHub","инструмент командной строки","автоматизация","разработка","owner/repo","package-name","CLI","ИИ Агенты"],"ar":["remote-bash","أوامر Bash","مستودعات GitHub","أداة سطر الأوامر","آليّة","تطوير","owner/repo","package-name","CLI","أدوات الذكاء الاصطناعي"]}},"owner":"basehub-ai","repo":"forums","repoPath":"basehub-ai/forums","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.326Z","topics":[],"category":"community","skillMd":{"name":"remote-bash","description":"Execute bash commands against any public GitHub repository without cloning it locally. Use when the user needs to explore, search, or analyze external repos, check dependency source code, or investigate implementation details in third-party code.","bodyPreview":"# remote-bash\n\nExecute bash commands against any public GitHub repository without cloning it to the local machine.\n\n```bash\nnpx remote-bash <target> [options] -- <command>\n```\n\n## Target formats\n\n| Format | Example | Behavior |\n|--------|---------|----------|\n| `owner/repo` | `vercel/next.js` | Target the default branch |\n| `package-name` | `zod` | Reads version from local lockfile, resolves to repo + exact SHA |\n\n## Options\n\n| Option | Description |\n|--------|-------------|\n| `-ref <branch\\|com","body":"# remote-bash\n\nExecute bash commands against any public GitHub repository without cloning it to the local machine.\n\n```bash\nnpx remote-bash <target> [options] -- <command>\n```\n\n## Target formats\n\n| Format | Example | Behavior |\n|--------|---------|----------|\n| `owner/repo` | `vercel/next.js` | Target the default branch |\n| `package-name` | `zod` | Reads version from local lockfile, resolves to repo + exact SHA |\n\n## Options\n\n| Option | Description |\n|--------|-------------|\n| `-ref <branch\\|commit>` | Target a specific branch or commit SHA |\n| `-v <version>` | Target a specific version/tag |\n\n## Examples\n\n```bash\n# check how next.js exports its cache APIs\nnpx remote-bash vercel/next.js -- cat packages/next/cache.d.ts\n\n# find all ZodIssueCode types in zod (uses your lockfile version)\nnpx remote-bash zod -- grep \"ZodIssueCode\" packages/zod/src/v3/ZodError.ts\n\n# explore three.js module structure\nnpx remote-bash mrdoob/three.js -- ls src/\n\n# search for cacheLife usage across next.js canary branch\nnpx remote-bash vercel/next.js -ref canary -- grep -rn \"cacheLife\" --include=\"*.ts\"\n\n# check a specific three.js release\nnpx remote-bash mrdoob/three.js -v r150 -- cat src/Three.js\n```\n\n## Key Benefits\n\n- **No local clone**: Runs in the cloud, nothing downloaded to your machine\n- **Lockfile-aware**: Package names resolve to the exact version you have installed\n- **Version pinning**: Explore different branches, commits, or tags with `-ref` and `-v`\n"},"lastSynced":"2026-03-08T02:03:01.838Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing to execute bash commands against public GitHub repositories without cloning them.","zh":"非常适合需要在不克隆公有 GitHub 仓库的情况下执行 bash 命令的 DevOps Agent。","ja":"GitHub リポジトリをクローンせずに bash コマンドを実行する必要がある DevOps エージェントに最適です。","ko":"공개 GitHub 리포지토리를 클론하지 않고 bash 명령을 실행해야 하는 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan ejecutar comandos bash contra repositorios de GitHub públicos sin clonarlos.","fr":"Parfait pour les agents DevOps qui ont besoin d''exécuter des commandes bash contre des dépôts GitHub publics sans les cloner.","de":"Perfekt für DevOps-Agents, die Befehle in der Bash-Eingabeaufforderung gegen öffentliche GitHub-Repositorys ausführen müssen, ohne sie zu klonen.","pt":"Perfeito para Agentes DevOps que precisam executar comandos bash em repositórios GitHub públicos sem cloná-los.","ru":"Идеально для агентов DevOps, которым необходимо выполнять команды bash в отношении публичных репозиториев GitHub без их клонирования.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى تشغيل أوامر bash على مستودعات GitHub العامة بدون استنساخها."},"recommendation":{"en":"Empowers agents to execute bash commands against GitHub repositories using owner/repo and package-name formats, supporting targets like default branches and exact SHAs, while utilizing options like -ref for branch or commit references.","zh":"赋予代理执行 bash 命令的能力，使用所有者/仓库和包名格式来访问 GitHub 仓库，支持默认分支和确切的 SHA 等目标，同时利用 -ref 等选项来引用分支或提交。","ja":"エージェントが所有者/リポジトリおよびパッケージ名の形式を使用して GitHub リポジトリに対して bash コマンドを実行できるようにし、デフォルト ブランチや正確な SHA などのターゲットをサポートし、-ref などのオプションを使用してブランチまたはコミットを参照します。","ko":"에이전트가 소유자/리포지토리 및 패키지 이름 형식을 사용하여 GitHub 리포지토리에 대한 bash 명령을 실행할 수 있도록 하며, 기본 브랜치 및 정확한 SHA와 같은 대상에 대한 지원을 제공하고, -ref와 같은 옵션을 사용하여 브랜치 또는 커밋을 참조합니다.","es":"Permite a los agentes ejecutar comandos bash contra repositorios de GitHub utilizando formatos como propietario/repo y nombre de paquete, que admiten objetivos como ramas predeterminadas y SHAs exactos, mientras utiliza opciones como -ref para referencias de rama o confirmación.","fr":"Permet aux agents d''exécuter des commandes bash contre des dépôts GitHub en utilisant des formats tels que propriétaire/dépôt et nom de package, qui prennent en charge des cibles comme les branches par défaut et les SHAs exacts, tout en utilisant des options comme -ref pour les références de branche ou de commit.","de":"Ermöglicht es Agents, Befehle in der Bash-Eingabeaufforderung gegen GitHub-Repositorys auszuführen, indem sie Formate wie Besitzer/Repository und Paketname verwenden, die Ziele wie Standardbranches und exakte SHAs unterstützen, während Optionen wie -ref für Branch- oder Commit-Verweise verwendet werden.","pt":"Habilita os agentes a executar comandos bash em repositórios GitHub usando formatos como owner/repo e package-name, suportando alvos como branches padrão e SHAs exatos, ao mesmo tempo em que utiliza opções como -ref para referências de branch ou commit.","ru":"Наделяет агентов возможностью выполнять команды bash в отношении репозиториев GitHub, используя форматы owner/repo и package-name, поддерживая целевые объекты, такие как ветки по умолчанию и точные SHA, а также используя опции, такие как -ref для ссылок на ветку или коммит.","ar":"يمنح الوكلاء القدرة على تشغيل أوامر bash على مستودعات GitHub باستخدام صيغ مثل owner/repo و package-name، مع دعم أهداف مثل الفروع الافتراضية والشفرات الدلالية الصحيحة، وفي الوقت نفسه استخدام خيارات مثل -ref للREFERENCES إلى فرع أو.commit"},"useCases":{"en":["Automating testing and validation of public GitHub repositories","Executing bash commands against specific commits or branches","Debugging public repositories without cloning them locally"],"zh":["自动化测试和验证公有 GitHub 仓库","对特定提交或分支执行 bash 命令","在不克隆的情况下调试公有仓库"],"ja":["公開 GitHub リポジトリの自動テストと検証","特定のコミットやブランチに対して bash コマンドを実行する","クローンせずに公開リポジトリをデバッグする"],"ko":["공개 GitHub 리포지토리의 자동 테스트 및驗證","특정 커밋 또는 브랜치에 대한 bash 명령을 실행","클론하지 않고 공개 리포지토리를 디버깅"],"es":["Automatizar las pruebas y la validación de repositorios de GitHub públicos","Ejecutar comandos bash contra commits o ramas específicos","Depurar repositorios públicos sin clonarlos localmente"],"fr":["Automatiser les tests et la validation des dépôts GitHub publics","Exécuter des commandes bash contre des commits ou des branches spécifiques","Déboguer des dépôts publics sans les cloner localement"],"de":["Automatisieren von Tests und Validierung öffentlicher GitHub-Repositorys","Ausführen von Befehlen in der Bash-Eingabeaufforderung gegen bestimmte Commits oder Branches","Fehlerbehebung in öffentlichen Repositorys ohne lokales Klonen"],"pt":["Automatizar testes e validação de repositórios GitHub públicos","Executar comandos bash contra commits ou branches específicos","Depurar repositórios públicos sem cloná-los localmente"],"ru":["Автоматизировать тестирование и проверку публичных репозиториев GitHub","Выполнять команды bash против конкретных коммитов или веток","Отлаживать публичные репозитории без их локального клонирования"],"ar":["أتمتة اختبار وتأكيد مستودعات GitHub العامة","تشغيل أوامر bash ضد التزامات أو الفروع المحددة","تصحيح أخطاء المستودعات العامة بدون استنساخها محليًا"]},"limitations":{"en":["Limited to public GitHub repositories","Requires npx and GitHub repository access","Supports specific target formats like owner/repo and package-name"],"zh":["仅限公有 GitHub 仓库","需要 npx 和 GitHub 仓库访问权限","仅支持所有者/仓库和包名等特定目标格式"],"ja":["公開 GitHub リポジトリのみに制限される","npx と GitHub リポジトリへのアクセスが必要","所有者/リポジトリおよびパッケージ名などの特定のターゲット形式のみをサポート"],"ko":["공개 GitHub 리포지토리만으로 제한","npx 및 GitHub 리포지토리 액세스가 필요","소유자/리포지토리 및 패키지 이름과 같은 특정 대상 형식만 지원"],"es":["Limitado a repositorios de GitHub públicos","Requiere npx y acceso al repositorio de GitHub","Admite formatos de destino específicos como propietario/repo y nombre de paquete"],"fr":["Limité aux dépôts GitHub publics","Nécessite npx et l''accès au dépôt GitHub","Prend en charge des formats de cible spécifiques tels que propriétaire/dépôt et nom de package"],"de":["Begrenzt auf öffentliche GitHub-Repositorys","Benötigt npx und Zugriff auf das GitHub-Repository","Unterstützt bestimmte Zieldateiformate wie Besitzer/Repository und Paketname"],"pt":["Limitado a repositórios GitHub públicos","Requer npx e acesso ao repositório GitHub","Suporta formatos de destino específicos como owner/repo e package-name"],"ru":["Ограничен публичными репозиториями GitHub","Требует npx и доступа к репозиторию GitHub","Поддерживает конкретные форматы целей, такие как owner/repo и package-name"],"ar":["محدود بمستودعات GitHub العامة","يتطلب npx ووصول إلى مستودع GitHub","يدعم صيغ مستهدفة محددة مثل owner/repo و package-name"]},"version":4},"contentHash":"06b570a3c8886b7145ff480546db28f852e71090c362e2d5ac28d8bde9676aca","qualityScore":51}');
