INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('basehub-ai/forums/remote-bash', 'remote-bash', 'basehub-ai', 'forums', 'community', 'remote-bash basehub-ai forums community remote-bash allows developers to execute bash commands against public GitHub repositories without cloning them, supporting targets like owner/repo and package-name formats. remote-bash 是一种执行 bash 命令的工具，支持对 GitHub 公共仓库的命令行执行 remote-bash は GitHub リポジトリに対して bash コマンドを実行するツールです remote-bash는 GitHub 공개 리포지토리에 bash 명령어를 실행하는 도구입니다 remote-bash es una herramienta que permite ejecutar comandos de bash en repositorios de GitHub sin clonarlos. Se utiliza mediante la línea de comandos con npx remote-bash est un outil qui permet d''exécuter des commandes bash sur des dépôts GitHub sans les cloner. Il est utilisé via la ligne de commande avec npx remote-bash ist ein Tool, das die Ausführung von Bash-Befehlen in GitHub-Repositorys ohne Klonen ermöglicht. Es wird über die Kommandozeile mit npx verwendet O remote-bash é uma ferramenta de linha de comando que permite executar comandos Bash em repositórios GitHub públicos sem clonar. Ele suporta vários formatos de alvo, incluindo owner/repo e package-name Remote-bash — это инструмент командной строки, который позволяет выполнять команды Bash в публичных репозиториях GitHub без клонирования. Он поддерживает несколько форматов цели, включая owner/repo и package-name, и использует ИИ Агенты remote-bash هو أداة سطر الأوامر التي تسمح بتنفيذ أوامر Bash في مستودعات GitHub العامة بدون استنساخ. يدعم عدة صيغ هدف، بما في ذلك owner/repo و package-name، وتستخدم أدوات الذكاء الاصطناعي how to use remote-bash remote-bash alternative remote-bash install what is remote-bash remote-bash setup guide remote-bash vs git execute bash on github github repository bash commands remote-bash command-line tool remote-bash GitHub bash 命令 命令行工具 npx AI エージェント GitHub仓库命令行执行 bash命令执行 Executes bash commands on public GitHub repositories using npx remote-bash Supports target formats like owner/repo and package-name Resolves package-name targets to repository and exact SHA using local lockfiles Allows specification of branch or commit reference using -ref option Enables execution of custom bash commands against targeted repositories remote-bash is a command-line tool that enables execution of bash commands on public GitHub repositories without local cloning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RomainGRAS42/Procedio-AI/ai-avatar-video', 'community', 'RomainGRAS42', 'Procedio-AI', 'RomainGRAS42/Procedio-AI', 'ai-avatar-video', 0, 0, 51, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:10.701Z', '8dbc6f06d29205e04698747543887482133ceedd4d1ce87b88b91833cef4d588', '{"id":"RomainGRAS42/Procedio-AI/ai-avatar-video","name":"ai-avatar-video","description":{"en":"The ai-avatar-video skill creates AI avatars and talking head videos using inference.sh CLI. It benefits developers who need to generate realistic avatar videos from images and audio.","zh":"Procedio AI允许您创建AI头像视频，通过inference.sh CLI实现自动化","ja":"Procedio AIはAIアバター動画の作成を可能にし、inference.sh CLIで自動化を実現します","ko":"Procedio AI로 AI 아바타 비디오를 생성하고 자동화할 수 있습니다","es":"ai-avatar-video permite a los desarrolladores crear avatares y videos de cabeza parlante mediante la CLI de inference.sh. Esta herramienta utiliza la aplicación bytedance/omnihuman-1-5 para generar videos personalizados.","fr":"ai-avatar-video permet aux développeurs de créer des avatars et des vidéos de tête parlante via la CLI d''inference.sh. Cet outil utilise l''application bytedance/omnihuman-1-5 pour générer des vidéos personnalisées.","de":"ai-avatar-video ermöglicht es Entwicklern, Avatare und sprechende Kopf-Videos über die inference.sh-CLI zu erstellen. Dieses Tool verwendet die Anwendung bytedance/omnihuman-1-5, um benutzerdefinierte Videos zu generieren.","pt":"O ai-avatar-video permite criar vídeos de avatar inteligente via CLI inference.sh, utilizando o modelo bytedance/omnihuman-1-5 para combinar imagens e áudio.","ru":"ИИ Агент ai-avatar-video позволяет создавать видео-аватары через CLI inference.sh, используя модель bytedance/omnihuman-1-5 для объединения изображений и аудио.","ar":"يسمح ai-avatar-video بإنشاء مقاطع فيديو لآفاتار الذكية عبر واجهة سطر الأوامر inference.sh، باستخدام نموذج bytedance/omnihuman-1-5 لدمج الصور والصوت."},"seo":{"title":{"en":"ai-avatar-video: Create AI Avatars via Inference.sh CLI |...","zh":"AI头像视频创建指南 - Procedio AI","ja":"AIアバター動画の作成方法 - Procedio AIエージェント","ko":"AI 아바타 비디오 생성 가이드 - Procedio AI","es":"Guía de configuración de ai-avatar-video para desarrollad...","fr":"Configurer des vidéos d''avatar et de tête parlante avec a...","de":"Einrichten von AI-Avatar-Videos mit ai-avatar-video: Eine...","pt":"Guia de Configuração do ai-avatar-video: Crie Vídeos de A...","ru":"Настройка ИИ Агентов: ai-avatar-video для Создания Видео-...","ar":"دليل إعداد ai-avatar-video: إنشاء مقاطع فيديو لآفاتار الذكية"},"description":{"en":"Discover how to generate AI avatars and talking head videos with ai-avatar-video. Learn to use inference.sh CLI and get started with your first project today!","zh":"使用Procedio AI创建AI头像视频，通过inference.sh CLI实现自动化","ja":"Procedio AIを使用してAIアバター動画を作成し、inference.sh CLIで自動化を実現","ko":"Procedio AI로 AI 아바타 비디오를 생성하고 inference.sh CLI로 자동화 하세요","es":"Crea avatares y videos de cabeza parlante con Procedio AI y la CLI de inference.sh. Obtén más información sobre la configuración y el uso de ai-avatar-video.","fr":"Découvrez comment créer des avatars et des vidéos de tête parlante avec Procedio AI et la CLI d''inference.sh. Obtenez plus d''informations sur la configuratio...","de":"Erstellen Sie Avatare und sprechende Kopf-Videos mit Procedio AI und der inference.sh-CLI. Erfahren Sie mehr über die Einrichtung und Verwendung von ai-avata...","pt":"Aprenda a criar vídeos de avatar inteligente com o ai-avatar-video, utilizando a CLI inference.sh e o modelo bytedance/omnihuman-1-5","ru":"Узнайте, как создать видео-аватары с помощью ai-avatar-video, используя CLI inference.sh и модель bytedance/omnihuman-1-5","ar":"تعلم كيفية إنشاء مقاطع فيديو لآفاتار الذكية باستخدام ai-avatar-video، مع واجهة سطر الأوامر inference.sh ونموذج bytedance/omnihuman-1-5"},"definition":{"en":"ai-avatar-video is a skill that generates AI-powered avatars and talking head videos using the inference.sh command-line interface.","zh":"AI头像视频是使用Procedio AI和inference.sh CLI创建的数字化头像","ja":"AIアバター動画はProcedio AIとinference.sh CLIを使用して作成されたデジタルアバター","ko":"AI 아바타 비디오는 Procedio AI와 inference.sh CLI로 생성된 디지털 아바타입니다","es":"ai-avatar-video es una herramienta de Procedio AI que permite crear avatares y videos de cabeza parlante mediante la CLI de inference.sh.","fr":"ai-avatar-video est un outil de Procedio AI qui permet de créer des avatars et des vidéos de tête parlante via la CLI d''inference.sh.","de":"ai-avatar-video ist ein Tool von Procedio AI, das die Erstellung von Avataren und sprechenden Kopf-Videos über die inference.sh-CLI ermöglicht.","pt":"O ai-avatar-video é uma ferramenta que cria vídeos de avatar inteligente, combinando imagens e áudio através da CLI inference.sh.","ru":"ИИ Агент ai-avatar-video - это инструмент, создающий видео-аватары, объединяя изображения и аудио через CLI inference.sh.","ar":" ai-avatar-video هو أداة لإنشاء مقاطع فيديو لآفاتار الذكية، من خلال دمج الصور والصوت عبر واجهة سطر الأوامر inference.sh."},"features":{"en":["Creates AI avatars and talking head videos via inference.sh CLI","Supports input from image and audio URLs","Utilizes the bytedance/omnihuman-1-5 app for avatar generation","Runs on the inference.sh platform","Uses the infsh app run command for execution","Accepts JSON input for customization"],"zh":["使用inference.sh CLI创建AI头像视频","支持图像和音频输入","自动化AI头像视频的创建","使用Bytedance的Omnihuman-1-5模型","支持批量创建AI头像视频"],"ja":["inference.sh CLIを使用してAIアバター動画を作成","画像と音声入力のサポート","AIアバター動画の自動化された作成","BytedanceのOmnihuman-1-5モデルを使用","バッチ処理でAIアバター動画を作成"],"ko":["inference.sh CLI를 사용하여 AI 아바타 비디오 생성","이미지와 오디오 입력 지원","AI 아바타 비디오 자동 생성","Bytedance의 Omnihuamn-1-5 모델 사용","배치 처리로 AI 아바타 비디오 생성"],"es":["Creación de avatares y videos de cabeza parlante mediante la CLI de inference.sh","Uso de la aplicación bytedance/omnihuman-1-5 para generar videos personalizados","Compatibilidad con imágenes y audio como entrada","Generación de videos en diferentes formatos","Integración con la plataforma Procedio AI"],"fr":["Création d''avatars et de vidéos de tête parlante via la CLI d''inference.sh","Utilisation de l''application bytedance/omnihuman-1-5 pour générer des vidéos personnalisées","Compatibilité avec les images et les fichiers audio comme entrée","Génération de vidéos dans différents formats","Intégration avec la plateforme Procedio AI"],"de":["Erstellung von Avataren und sprechenden Kopf-Videos über die inference.sh-CLI","Verwendung der Anwendung bytedance/omnihuman-1-5 zur Generierung benutzerdefinierter Videos","Kompatibilität mit Bildern und Audio als Eingabe","Generierung von Videos in verschiedenen Formaten","Integration mit der Procedio AI-Plattform"],"pt":["Criação de vídeos de avatar inteligente via CLI inference.sh","Utilização do modelo bytedance/omnihuman-1-5 para combinar imagens e áudio","Integração com a plataforma inference.sh para processamento de mídia","Suporte a entrada de imagens e áudio via URL","Saída de vídeos em formato padrão"],"ru":["Создание видео-аватаров через CLI inference.sh","Использование модели bytedance/omnihuman-1-5 для объединения изображений и аудио","Интеграция с платформой inference.sh для обработки мультимедиа","Поддержка ввода изображений и аудио через URL","Выход видео в стандартном формате"],"ar":["إنشاء مقاطع فيديو لآفاتار الذكية عبر واجهة سطر الأوامر inference.sh","استخدام نموذج bytedance/omnihuman-1-5 لدمج الصور والصوت","التكامل مع منصة inference.sh لمعالجة الوسائط","دعم إدخال الصور والصوت عبر الرابط","إخراج مقاطع فيديو بالتنسيق القياسي"]},"keywords":{"en":["how to use ai-avatar-video","ai-avatar-video setup guide","inference.sh CLI tutorial","ai avatar generation","talking head video creation","ai-avatar-video alternative","ai-avatar-video vs deepfake","ai-avatar-video install","ai-avatar-video documentation"],"zh":["AI头像视频","Procedio AI","inference.sh CLI","AI头像视频创建","数字化头像","自动化AI头像视频","Bytedance Omnihuamn-1-5"],"ja":["AIアバター動画","Procedio AIエージェント","inference.sh CLI","AIアバター動画の作成","デジタルアバター","自動化AIアバター動画","Bytedance Omnihuamn-1-5"],"ko":["AI 아바타 비디오","Procedio AI","inference.sh CLI","AI 아바타 비디오 생성","디지털 아바타","자동화 AI 아바타 비디오","Bytedance Omnihuamn-1-5"],"es":["ai-avatar-video","procedio ai","inference.sh","avatares","videos de cabeza parlante","desarrollo de ai","herramientas de ai","aplicaciones de ai"],"fr":["ai-avatar-video","procedio ai","inference.sh","avatars","vidéos de tête parlante","développement d''ia","outils d''ia","applications d''ia"],"de":["ai-avatar-video","procedio ai","inference.sh","avatare","sprechende kopf-videos","ai-entwicklung","ai-tools","ai-anwendungen"],"pt":["ai-avatar-video","inference.sh","bytedance/omnihuman-1-5","vídeos de avatar inteligente","criação de vídeos","processamento de mídia","CLI","ferramentas de IA","desenvolvimento de aplicativos"],"ru":["ИИ Агент ai-avatar-video","inference.sh","bytedance/omnihuman-1-5","видео-аватары","создание видео","обработка мультимедиа","CLI","инструменты ИИ","разработка приложений"],"ar":["أداة ai-avatar-video","inference.sh","bytedance/omnihuman-1-5","مقاطع فيديو لآفاتار الذكية","إنشاء مقاطع فيديو","معالجة الوسائط","واجهة سطر الأوامر","أدوات الذكاء الاصطناعي","تطوير التطبيقات"]}},"owner":"RomainGRAS42","repo":"Procedio-AI","repoPath":"RomainGRAS42/Procedio-AI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"ai-avatar-video","description":"Create AI avatar and talking head videos with OmniHuman, Fabric, PixVerse via inference.sh CLI. Models: OmniHuman 1.5, OmniHuman 1.0, Fabric 1.0, PixVerse Lipsync. Capabilities: audio-driven avatars, lipsync videos, talking head generation, virtual presenters. Use for: AI presenters, explainer videos, virtual influencers, dubbing, marketing videos. Triggers: ai avatar, talking head, lipsync, avatar video, virtual presenter, ai spokesperson, audio driven video, heygen alternative, synthesia alternative, talking avatar, lip sync, video avatar, ai presenter, digital human","bodyPreview":"# AI Avatar & Talking Head Videos\n\nCreate AI avatars and talking head videos via [inference.sh](https://inference.sh) CLI.\n\n![AI Avatar & Talking Head Videos](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kg0tszs96s0n8z5gy8y5mbg7.jpeg)\n\n## Quick Start\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh && infsh login\n\n# Create avatar video from image + audio\ninfsh app run bytedance/omnihuman-1-5 --input ''{\n  \"image_url\": \"https://portrait.jpg\",\n  \"audio_url\": \"https://speech.","body":"# AI Avatar & Talking Head Videos\n\nCreate AI avatars and talking head videos via [inference.sh](https://inference.sh) CLI.\n\n![AI Avatar & Talking Head Videos](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kg0tszs96s0n8z5gy8y5mbg7.jpeg)\n\n## Quick Start\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh && infsh login\n\n# Create avatar video from image + audio\ninfsh app run bytedance/omnihuman-1-5 --input ''{\n  \"image_url\": \"https://portrait.jpg\",\n  \"audio_url\": \"https://speech.mp3\"\n}''\n```\n\n## Available Models\n\n| Model | App ID | Best For |\n|-------|--------|----------|\n| OmniHuman 1.5 | `bytedance/omnihuman-1-5` | Multi-character, best quality |\n| OmniHuman 1.0 | `bytedance/omnihuman-1-0` | Single character |\n| Fabric 1.0 | `falai/fabric-1-0` | Image talks with lipsync |\n| PixVerse Lipsync | `falai/pixverse-lipsync` | Highly realistic |\n\n## Search Avatar Apps\n\n```bash\ninfsh app list --search \"omnihuman\"\ninfsh app list --search \"lipsync\"\ninfsh app list --search \"fabric\"\n```\n\n## Examples\n\n### OmniHuman 1.5 (Multi-Character)\n\n```bash\ninfsh app run bytedance/omnihuman-1-5 --input ''{\n  \"image_url\": \"https://portrait.jpg\",\n  \"audio_url\": \"https://speech.mp3\"\n}''\n```\n\nSupports specifying which character to drive in multi-person images.\n\n### Fabric 1.0 (Image Talks)\n\n```bash\ninfsh app run falai/fabric-1-0 --input ''{\n  \"image_url\": \"https://face.jpg\",\n  \"audio_url\": \"https://audio.mp3\"\n}''\n```\n\n### PixVerse Lipsync\n\n```bash\ninfsh app run falai/pixverse-lipsync --input ''{\n  \"image_url\": \"https://portrait.jpg\",\n  \"audio_url\": \"https://speech.mp3\"\n}''\n```\n\nGenerates highly realistic lipsync from any audio.\n\n## Full Workflow: TTS + Avatar\n\n```bash\n# 1. Generate speech from text\ninfsh app run infsh/kokoro-tts --input ''{\n  \"text\": \"Welcome to our product demo. Today I will show you...\"\n}'' > speech.json\n\n# 2. Create avatar video with the speech\ninfsh app run bytedance/omnihuman-1-5 --input ''{\n  \"image_url\": \"https://presenter-photo.jpg\",\n  \"audio_url\": \"<audio-url-from-step-1>\"\n}''\n```\n\n## Full Workflow: Dub Video in Another Language\n\n```bash\n# 1. Transcribe original video\ninfsh app run infsh/fast-whisper-large-v3 --input ''{\"audio_url\": \"https://video.mp4\"}'' > transcript.json\n\n# 2. Translate text (manually or with an LLM)\n\n# 3. Generate speech in new language\ninfsh app run infsh/kokoro-tts --input ''{\"text\": \"<translated-text>\"}'' > new_speech.json\n\n# 4. Lipsync the original video with new audio\ninfsh app run infsh/latentsync-1-6 --input ''{\n  \"video_url\": \"https://original-video.mp4\",\n  \"audio_url\": \"<new-audio-url>\"\n}''\n```\n\n## Use Cases\n\n- **Marketing**: Product demos with AI presenter\n- **Education**: Course videos, explainers\n- **Localization**: Dub content in multiple languages\n- **Social Media**: Consistent virtual influencer\n- **Corporate**: Training videos, announcements\n\n## Tips\n\n- Use high-quality portrait photos (front-facing, good lighting)\n- Audio should be clear with minimal background noise\n- OmniHuman 1.5 supports multiple people in one image\n- LatentSync is best for syncing existing videos to new audio\n\n## Related Skills\n\n```bash\n# Full platform skill (all 150+ apps)\nnpx skills add inferencesh/skills@inference-sh\n\n# Text-to-speech (generate audio for avatars)\nnpx skills add inferencesh/skills@text-to-speech\n\n# Speech-to-text (transcribe for dubbing)\nnpx skills add inferencesh/skills@speech-to-text\n\n# Video generation\nnpx skills add inferencesh/skills@ai-video-generation\n\n# Image generation (create avatar images)\nnpx skills add inferencesh/skills@ai-image-generation\n```\n\nBrowse all video apps: `infsh app list --category video`\n\n## Documentation\n\n- [Running Apps](https://inference.sh/docs/apps/running) - How to run apps via CLI\n- [Content Pipeline Example](https://inference.sh/docs/examples/content-pipeline) - Building media workflows\n- [Streaming Results](https://inference.sh/docs/api/sdk/streaming) - Real-time progress updates\n"},"lastSynced":"2026-03-08T02:03:10.701Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Agents needing advanced AI avatar and talking head video generation capabilities using inference.sh CLI.","zh":"非常适合需要使用inference.sh CLI进行高级AI头像和谈话头视频生成的媒体代理。","ja":"inference.sh CLIを使用して高度なAIアバターとトーキングヘッドビデオ生成機能を必要とするメディアエージェントに最適です。","ko":"inference.sh CLI를 사용하여 고급 AI 아바타 및 대화형 비디오 생성 기능이 필요한 미디어 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de Medios que necesitan capacidades avanzadas de generación de avatar de IA y video de cabeza parlante utilizando inference.sh CLI.","fr":"Parfait pour les agents des médias ayant besoin de capacités avancées de génération d''avatar IA et de vidéo de tête parlante en utilisant inference.sh CLI.","de":"Perfekt für Media-Agenten, die erweiterte AI-Avatar- und Talking-Head-Video-Generierungsfunktionen mit inference.sh CLI benötigen.","pt":"Perfeito para Agentes de Mídia que precisam de capacidades avançadas de geração de avatar e vídeo de cabeça falante de IA usando o CLI inference.sh.","ru":"Идеально для медиа-агентов, которым необходимы продвинутые возможности генерации аватаров и видео с говорящими головами ИИ с использованием CLI inference.sh.","ar":"مثالي للوكلاء الإعلاميين الذين يحتاجون إلى قدرات متقدمة لإنشاء صور متحركة لوجوه متكلمه وافتراضية باستخدام واجهة سطر الأوامر inference.sh"},"recommendation":{"en":"Empowers agents to create realistic avatar videos from images and audio using inference.sh, leveraging AI models like bytedance/omnihuman-1-5 for high-quality video generation, and supports various input formats such as image URLs and audio URLs.","zh":"使代理能够使用inference.sh、利用像bytedance/omnihuman-1-5这样的AI模型从图像和音频中创建逼真的头像视频，并支持各种输入格式，例如图像URL和音频URL。","ja":"エージェントがinference.sh、bytedance/omnihuman-1-5のようなAIモデルを利用して、画像とオーディオからリアルなアバター動画を生成し、画像URLやオーディオURLのような様々な入力形式をサポートすることを可能にします。","ko":"에이전트가 inference.sh를 사용하여 bytedance/omnihuman-1-5와 같은 AI 모델을 활용하여 이미지와 오디오에서 실제적인 아바타 비디오를 생성하고 이미지 URL 및 오디오 URL과 같은 다양한 입력 형식을 지원할 수 있도록 합니다.","es":"Habilita a los agentes a crear vídeos de avatares realistas a partir de imágenes y audio utilizando inference.sh, aprovechando modelos de IA como bytedance/omnihuman-1-5 para una generación de vídeo de alta calidad, y admite varios formatos de entrada como URLs de imagen y URLs de audio.","fr":"Permet aux agents de créer des vidéos d''avatar réaliste à partir d''images et d''audio en utilisant inference.sh, en exploitant des modèles d''IA tels que bytedance/omnihuman-1-5 pour une génération de vidéo de haute qualité, et prend en charge divers formats d''entrée tels que les URLs d''image et les URLs d''audio.","de":"Ermächtigt Agenten, realistische Avatar-Videos aus Bildern und Audio mit inference.sh zu erstellen, indem es auf AI-Modelle wie bytedance/omnihuman-1-5 für die Erstellung von hochwertigen Videos zurückgreift und verschiedene Eingabeformate wie Bild-URLs und Audio-URLs unterstützt.","pt":"Permite que os agentes criem vídeos de avatar realistas a partir de imagens e áudio usando o inference.sh, aproveitando modelos de IA como o bytedance/omnihuman-1-5 para geração de vídeo de alta qualidade, e suporta vários formatos de entrada, como URLs de imagem e URLs de áudio.","ru":"Наделяет агентов возможностью создавать реалистичные видео-аватары из изображений и аудио с помощью inference.sh, используя модели ИИ, такие как bytedance/omnihuman-1-5, для генерации видео высокого качества, и поддерживает различные форматы ввода, такие как URL-адреса изображений и URL-адреса аудио.","ar":"يمكن للوكلاء من إنشاء مقاطع فيديو متحركة واقعية من الصور والصوت باستخدام inference.sh، وتستفيد من نماذج الذكاء الاصطناعي مثل bytedance/omnihuman-1-5 لإنشاء مقاطع فيديو عالية الجودة، ودعم تنسيقات إدخال مختلفة مثل عناوين URL للصور وملفات الصوت."},"useCases":{"en":["Generating AI avatars for virtual events","Creating talking head videos for educational content","Automating video production for social media platforms"],"zh":["为虚拟活动生成AI头像","为教育内容创建谈话头视频","为社交媒体平台自动化视频制作"],"ja":["バーチャルイベントのためのAIアバターの生成","教育コンテンツのためのトーキングヘッドビデオの作成","ソーシャルメディアプラットフォームのための動画制作の自動化"],"ko":["가상 행사용 AI 아바타 생성","교육 콘텐츠를 위한 대화형 비디오 생성","소셜 미디어 플랫폼을 위한 자동 비디오 제작"],"es":["Generación de avatares de IA para eventos virtuales","Creación de vídeos de cabeza parlante para contenido educativo","Automatización de la producción de vídeo para plataformas de redes sociales"],"fr":["Génération d''avatar IA pour les événements virtuels","Création de vidéos de tête parlante pour le contenu éducatif","Automatisation de la production de vidéos pour les plateformes de réseaux sociaux"],"de":["Erstellung von AI-Avataren für virtuelle Events","Erstellung von Talking-Head-Videos für Bildungsinhalte","Automatisierung der Videoproduktion für soziale Medien-Plattformen"],"pt":["Geração de avatares de IA para eventos virtuais","Criação de vídeos de cabeça falante para conteúdo educacional","Automatização da produção de vídeo para plataformas de mídia social"],"ru":["Генерация аватаров ИИ для виртуальных мероприятий","Создание видео с говорящими головами для образовательного контента","Автоматизация видеопроизводства для социальных медиа-платформ"],"ar":["إنشاء صور متحركة لوجوه افتراضية باستخدام الذكاء الاصطناعي للاستخدام في الفعاليات الافتراضية","إنشاء مقاطع فيديو لوجوه متكلمه للاستخدام في المحتوى التعليمي","توفير إنتاج الفيديو آلياً لمواقع التواصل الاجتماعي"]},"limitations":{"en":["Requires inference.sh CLI installation and login","Dependent on inference.sh app availability and bytedance/omnihuman-1-5 model support"],"zh":["需要inference.sh CLI的安装和登录","依赖inference.sh应用的可用性和bytedance/omnihuman-1-5模型的支持"],"ja":["inference.sh CLIのインストールとログインが必要","inference.shアプリの可用性とbytedance/omnihuman-1-5モデルのサポートに依存"],"ko":["inference.sh CLI 설치 및 로그인이 필요","inference.sh 앱의 가용성 및 bytedance/omnihuman-1-5 모델 지원에 의존"],"es":["Requiere la instalación y el inicio de sesión de inference.sh CLI","Depende de la disponibilidad de la aplicación inference.sh y del soporte del modelo bytedance/omnihuman-1-5"],"fr":["Nécessite l''installation et la connexion à inference.sh CLI","Dépend de la disponibilité de l''application inference.sh et du support du modèle bytedance/omnihuman-1-5"],"de":["Benötigt die Installation und Anmeldung von inference.sh CLI","Hängt von der Verfügbarkeit der inference.sh-App und der Unterstützung des bytedance/omnihuman-1-5-Modells ab"],"pt":["Requer instalação e login do CLI inference.sh","Dependente da disponibilidade do aplicativo inference.sh e do suporte ao modelo bytedance/omnihuman-1-5"],"ru":["Требует установки и входа в CLI inference.sh","Зависит от наличия приложения inference.sh и поддержки модели bytedance/omnihuman-1-5"],"ar":["يتطلب تثبيت واجهة سطر الأوامر inference.sh وتسجيل الدخول","يعتمد على توافر تطبيق inference.sh ودعم نموذج bytedance/omnihuman-1-5"]},"version":4},"contentHash":"8dbc6f06d29205e04698747543887482133ceedd4d1ce87b88b91833cef4d588","qualityScore":51}');
