INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RomainGRAS42/Procedio-AI/ai-avatar-video', 'ai-avatar-video', 'RomainGRAS42', 'Procedio-AI', 'community', 'ai-avatar-video RomainGRAS42 Procedio-AI community The ai-avatar-video skill creates AI avatars and talking head videos using inference.sh CLI. It benefits developers who need to generate realistic avatar videos from images and audio. Procedio AI允许您创建AI头像视频，通过inference.sh CLI实现自动化 Procedio AIはAIアバター動画の作成を可能にし、inference.sh CLIで自動化を実現します Procedio AI로 AI 아바타 비디오를 생성하고 자동화할 수 있습니다 ai-avatar-video permite a los desarrolladores crear avatares y videos de cabeza parlante mediante la CLI de inference.sh. Esta herramienta utiliza la aplicación bytedance/omnihuman-1-5 para generar videos personalizados. ai-avatar-video permet aux développeurs de créer des avatars et des vidéos de tête parlante via la CLI d''inference.sh. Cet outil utilise l''application bytedance/omnihuman-1-5 pour générer des vidéos personnalisées. ai-avatar-video ermöglicht es Entwicklern, Avatare und sprechende Kopf-Videos über die inference.sh-CLI zu erstellen. Dieses Tool verwendet die Anwendung bytedance/omnihuman-1-5, um benutzerdefinierte Videos zu generieren. O ai-avatar-video permite criar vídeos de avatar inteligente via CLI inference.sh, utilizando o modelo bytedance/omnihuman-1-5 para combinar imagens e áudio. ИИ Агент ai-avatar-video позволяет создавать видео-аватары через CLI inference.sh, используя модель bytedance/omnihuman-1-5 для объединения изображений и аудио. يسمح ai-avatar-video بإنشاء مقاطع فيديو لآفاتار الذكية عبر واجهة سطر الأوامر inference.sh، باستخدام نموذج bytedance/omnihuman-1-5 لدمج الصور والصوت. how to use ai-avatar-video ai-avatar-video setup guide inference.sh CLI tutorial ai avatar generation talking head video creation ai-avatar-video alternative ai-avatar-video vs deepfake ai-avatar-video install ai-avatar-video documentation AI头像视频 Procedio AI inference.sh CLI AI头像视频创建 数字化头像 自动化AI头像视频 Bytedance Omnihuamn-1-5 Creates AI avatars and talking head videos via inference.sh CLI Supports input from image and audio URLs Utilizes the bytedance/omnihuman-1-5 app for avatar generation Runs on the inference.sh platform Uses the infsh app run command for execution Accepts JSON input for customization ai-avatar-video is a skill that generates AI-powered avatars and talking head videos using the inference.sh command-line interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('notum-cz/strapi-next-monorepo-starter/add-locale', 'community', 'notum-cz', 'strapi-next-monorepo-starter', 'notum-cz/strapi-next-monorepo-starter', 'add-locale', 0, 0, 51, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.372Z', '798b53275d6d90dfa0f150e0572e52cbd02e3e1c26aae3d8279c4b152bb58870', '{"id":"notum-cz/strapi-next-monorepo-starter/add-locale","name":"add-locale","description":{"en":"The add-locale skill helps developers add a new language/locale to their Strapi projects, combining Strapi admin config, Next.js i18n routing, and translation files. It benefits developers working with Strapi and NextJS.","zh":"add-locale技能提供了添加新语言和本地化设置到Strapi项目的解决方案，包括Strapi admin配置、Next.js i18n路由和翻译文件","ja":"add-localeスキルは、Strapiプロジェクトに新しい言語とローカライズ設定を追加するための解決策を提供します。Strapi admin設定、Next.js i18nルーティング、翻訳ファイルが含まれます","ko":"add-locale 스킬은 스트라피 프로젝트에 새로운 언어와 로컬라이제이션 설정을 추가하는 솔루션을 제공합니다. 스트라피 관리자 설정, Next.js i18n 라우팅, 번역 파일이 포함됩니다","es":"Add-locale es una herramienta para agregar un nuevo idioma a tu aplicación, compatible con Strapi y Next.js","fr":"Add-locale est un outil pour ajouter une nouvelle langue à votre application, compatible avec Strapi et Next.js","de":"Add-locale ist ein Tool, um eine neue Sprache zu Ihrer Anwendung hinzuzufügen, kompatibel mit Strapi und Next.js","pt":"O add-locale é uma ferramenta para adicionar novos idiomas ao seu projeto, utilizando Strapi e Next.js.","ru":"add-locale - это инструмент для добавления новых языков в ваш проект, использующий Strapi и Next.js.","ar":"add-locale هو أداة لإضافة لغات جديدة إلى مشروعك، باستخدام Strapi و Next.js."},"seo":{"title":{"en":"add-locale: Setup Guide for Strapi Projects | AI Agent Skill","zh":"添加本地化设置指南 - add-locale","ja":"ローカライズ設定のベストプラクティス - add-locale AIエージェント","ko":"로컬라이제이션 설정 가이드 - add-locale","es":"Configuración de add-locale: Guía de inicio","fr":"Configurer add-locale: Meilleures pratiques","de":"Add-locale Einrichtung: Leitfaden für Entwickler","pt":"Adicionar Idioma com add-locale: Guia de Configuração","ru":"Настройка Мультиязычности с add-locale: Лучшие Практики","ar":"إضافة اللغة مع add-locale: دليل الإعداد"},"description":{"en":"Discover how to add a new language/locale to your Strapi project with the add-locale skill. Get started with Next.js i18n routing and translation files today!","zh":"了解如何使用add-locale技能添加新语言和本地化设置到您的Strapi项目中","ja":"add-localeスキルを使用してStrapiプロジェクトに新しい言語とローカライズ設定を追加する方法について学習します","ko":"add-locale 스킬을 사용하여 스트라피 프로젝트에 새로운 언어와 로컬라이제이션 설정을 추가하는 방법에 대해 알아보세요","es":"Aprende a agregar un nuevo idioma a tu aplicación con add-locale, incluyendo configuración de Strapi y enrutamiento de Next.js","fr":"Découvrez comment ajouter une nouvelle langue à votre application avec add-locale, y compris la configuration de Strapi et le routage de Next.js","de":"Erfahren Sie, wie Sie eine neue Sprache zu Ihrer Anwendung mit add-locale hinzufügen, einschließlich Strapi-Konfiguration und Next.js-Routing","pt":"Aprenda a adicionar um novo idioma ao seu projeto com add-locale, incluindo configuração do Strapi e Next.js","ru":"Узнайте, как добавить новый язык в ваш проект с помощью add-locale, включая настройку Strapi и Next.js","ar":"تعلم كيفية إضافة لغة جديدة إلى مشروعك مع add-locale، بما في ذلك إعداد Strapi و Next.js"},"definition":{"en":"add-locale is a skill that enables developers to add a new language/locale to their Strapi projects, involving Strapi admin config, Next.js i18n routing, and translation files.","zh":"add-locale是用于添加新语言和本地化设置到Strapi项目的技能","ja":"add-localeは、Strapiプロジェクトに新しい言語とローカライズ設定を追加するためのスキルです","ko":"add-locale는 스트라피 프로젝트에 새로운 언어와 로컬라이제이션 설정을 추가하는 스킬입니다","es":"Add-locale es una función que permite agregar un nuevo idioma a una aplicación, validando códigos de idioma ISO 639-1","fr":"Add-locale est une fonction qui permet d''ajouter une nouvelle langue à une application, en validant les codes de langue ISO 639-1","de":"Add-locale ist eine Funktion, die es ermöglicht, eine neue Sprache zu einer Anwendung hinzuzufügen, indem sie ISO-639-1-Sprachcodes validiert","pt":"O add-locale é uma ferramenta de código aberto para adicionar suporte a múltiplos idiomas em projetos Strapi e Next.js","ru":"add-locale - это открытый инструмент для добавления поддержки多язычности в проектах Strapi и Next.js","ar":"add-locale هو أداة مفتوحة المصدر لإضافة دعم اللغات المتعددة في مشاريع Strapi و Next.js"},"features":{"en":["Validates locale code using ISO 639-1 format","Supports Next.js i18n routing for multilingual projects","Generates translation files for added locales","Configures Strapi admin for new language/locale","Rejects invalid locale codes and names","Asks for user input for locale code and name"],"zh":["支持Strapi admin配置","集成Next.js i18n路由","包含翻译文件","输入验证（区域代码和区域名称）"],"ja":["Strapi admin設定のサポート","Next.js i18nルーティングの統合","翻訳ファイルの包含","入力検証（ロケールコードとロケール名）"],"ko":["스트라피 관리자 설정 지원","Next.js i18n 라우팅 통합","번역 파일 포함","입력 검증（로케일 코드와 로케일 이름）"],"es":["Validación de códigos de idioma ISO 639-1","Configuración de Strapi admin","Enrutamiento de Next.js para internacionalización","Compatibilidad con Turborepo","Creación de archivos de traducción"],"fr":["Validation des codes de langue ISO 639-1","Configuration de Strapi admin","Routage de Next.js pour l''internationalisation","Compatibilité avec Turborepo","Création de fichiers de traduction"],"de":["Validierung von ISO-639-1-Sprachcodes","Strapi-Admin-Konfiguration","Next.js-Routing für Internationalisierung","Kompatibilität mit Turborepo","Erstellung von Übersetzungsdateien"],"pt":["Validação de código de idioma ISO 639-1","Configuração do Strapi admin","Suporte a rotas i18n do Next.js","Criação de arquivos de tradução","Integração com Turborepo"],"ru":["Валидация кода языка ISO 639-1","Настройка админ-панели Strapi","Поддержка маршрутов i18n в Next.js","Создание файлов перевода","Интеграция с Turborepo"],"ar":["التحقق من صحة رمز اللغة ISO 639-1","إعداد لوحة تحكم Strapi","دعم مسارات i18n في Next.js","إنشاء ملفات الترجمة","التكامل مع Turborepo"]},"keywords":{"en":["how to use add-locale","add-locale setup guide","Strapi locale setup","Next.js i18n routing","add-locale alternative","add-locale vs locale-plugin","install add-locale","add-locale tutorial","what is add-locale","add-locale documentation"],"zh":["add-locale","Strapi","Next.js","i18n","本地化设置","语言支持","区域代码","区域名称"],"ja":["add-locale","Strapi","Next.js","i18n","ローカライズ設定","言語サポート","ロケールコード","ロケール名","AIエージェント"],"ko":["add-locale","스트라피","Next.js","i18n","로컬라이제이션 설정","언어 지원","로케일 코드","로케일 이름"],"es":["add-locale","Strapi","Next.js","internacionalización","ISO 639-1","Turborepo","traducción","desarrollo de aplicaciones","herramientas de desarrollo"],"fr":["add-locale","Strapi","Next.js","internationalisation","ISO 639-1","Turborepo","traduction","développement d''applications","outils de développement","agents IA"],"de":["add-locale","Strapi","Next.js","Internationalisierung","ISO 639-1","Turborepo","Übersetzung","Anwendungsentwicklung","Entwicklungstools","KI-Agents"],"pt":["add-locale","Strapi","Next.js","i18n","tradução","multilíngue","Turborepo","ferramenta de código aberto","desenvolvimento web"],"ru":["add-locale","Strapi","Next.js","i18n","перевод","многоязычный","Turborepo","открытый инструмент","веб-разработка","ИИ Агенты"],"ar":["add-locale","Strapi","Next.js","i18n","ترجمة","متعددة اللغات","Turborepo","أداة مفتوحة المصدر","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"notum-cz","repo":"strapi-next-monorepo-starter","repoPath":"notum-cz/strapi-next-monorepo-starter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"add-locale","description":"Adds a new language/locale to the application. Involves Strapi admin config, Next.js i18n routing, and translation files. Triggers: add language, add locale, new language, new translation, internationalization.","bodyPreview":"Add a new language/locale to the application. Involves Strapi admin config, Next.js i18n routing, and translation files.\n\n## Input Validation\n\nBefore proceeding, validate inputs:\n\n- **Locale code**: must be valid ISO 639-1 (2 letters, lowercase, e.g. `de`, `fr`, `sk`). Reject uppercase or invalid codes.\n- **Locale name**: capitalized, no special characters (e.g. `German`, `French`, `Slovak`).\n\nIf invalid format provided, ask user to correct before proceeding.\n\n## Inputs\n\nAsk the user for:\n\n- **L","body":"Add a new language/locale to the application. Involves Strapi admin config, Next.js i18n routing, and translation files.\n\n## Input Validation\n\nBefore proceeding, validate inputs:\n\n- **Locale code**: must be valid ISO 639-1 (2 letters, lowercase, e.g. `de`, `fr`, `sk`). Reject uppercase or invalid codes.\n- **Locale name**: capitalized, no special characters (e.g. `German`, `French`, `Slovak`).\n\nIf invalid format provided, ask user to correct before proceeding.\n\n## Inputs\n\nAsk the user for:\n\n- **Locale code**: ISO 639-1 code (e.g. `de`, `fr`, `sk`)\n- **Locale name**: human-readable name (e.g. `German`, `French`, `Slovak`)\n\n## Steps\n\n### 1. Create locale translation file\n\nCopy `apps/ui/locales/en.json` to `apps/ui/locales/{locale}.json`.\n\nThe file structure must match `en.json` exactly — same keys, translated values. Initially copy as-is and mark values for translation.\n\nExisting locales for reference: `en.json`, `cs.json`.\n\n### 2. Update routing config\n\nEdit `apps/ui/src/lib/navigation.ts`.\n\nAdd the new locale code to the `locales` array:\n\n```typescript\nexport const routing = defineRouting({\n  locales: [\"cs\", \"en\", \"{locale}\"],\n  defaultLocale: \"en\",\n  localePrefix: \"as-needed\",\n})\n```\n\nKeep the array sorted alphabetically.\n\n### 3. Update i18n config (if needed)\n\nThe i18n config at `apps/ui/src/lib/i18n.ts` uses dynamic imports and automatically picks up new locale files:\n\n```typescript\nmessages: (\n  await (locale === \"en\"\n    ? import(\"../../locales/en.json\")\n    : import(`../../locales/${locale}.json`))\n).default,\n```\n\nNo changes needed unless you want HMR support for the new locale during development (currently only `en` has HMR via static import).\n\n### 4. Manual steps (inform user)\n\nAfter the automated steps complete, inform the user:\n\n> The translation file and routing config are set up. You need to manually:\n>\n> 1. **Enable locale in Strapi**: Go to Settings > Internationalization > Add new locale > select {locale}\n> 2. **Translate content**: For each content type with i18n enabled, switch to the new locale in Strapi admin and translate\n\n## Notes\n\n- The `[locale]` route segment in `apps/ui/src/app/[locale]/` handles locale routing automatically via `next-intl`\n- `generateStaticParams` in the root layout iterates `routing.locales` — new locale pages are generated automatically\n- The `localePrefix: \"as-needed\"` setting means the default locale (`en`) has no prefix, all others get `/{locale}/` prefix\n"},"lastSynced":"2026-03-08T02:03:21.372Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing seamless internationalization and localization capabilities in Strapi and Next.js projects.","zh":"适合需要在Strapi和Next.js项目中实现无缝国际化和本地化功能的全栈代理。","ja":"StrapiおよびNext.jsプロジェクトでシームレスな国際化とローカライゼーション機能を必要とするフルスタックエージェントに最適です。","ko":"Strapi와 Next.js 프로젝트에서 무중단 국제화 및 지역화 기능을 필요한 풀스택 에이전트에게 적합합니다.","es":"Perfecto para agentes Full Stack que necesitan capacidades de internacionalización y localización perfectas en proyectos Strapi y Next.js.","fr":"Parfait pour les agents Full Stack ayant besoin de capacités d''internationalisation et de localisation parfaites dans les projets Strapi et Next.js.","de":"Perfekt für Full-Stack-Agents, die nahtlose Internationalisierungs- und Lokalisierungsfunktionen in Strapi- und Next.js-Projekten benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de internacionalização e capacidades de localização sem interrupções em projetos Strapi e Next.js.","ru":"Идеально подходит для полнофункциональных агентов, которым необходимы бесшовные возможности интернационализации и локализации в проектах Strapi и Next.js.","ar":"مثالي للوكلاء المتكاملين الذين يحتاجون إلى إمكانيات دولية و محلية متواصلة في مشاريع Strapi و Next.js."},"recommendation":{"en":"Empowers agents to add new languages and locales to Strapi projects, leveraging Strapi admin config, Next.js i18n routing, and translation files, while enforcing valid ISO 639-1 locale codes and capitalized locale names.","zh":"赋予代理添加新的语言和区域设置到Strapi项目的能力，利用Strapi管理配置、Next.js i18n路由和翻译文件，同时强制使用有效的ISO 639-1区域设置代码和大写区域名称。","ja":"Strapiプロジェクトに新しい言語とロケールを追加するエージェントの能力を付与し、Strapi管理設定、Next.js i18nルーティング、および翻訳ファイルを利用しながら、有効なISO 639-1ロケールコードと大文字のロケール名を強制します。","ko":"에이전트가 Strapi 프로젝트에 새로운 언어와 로캘을 추가하는 능력을 부여하고, Strapi 관리 설정, Next.js i18n 라우팅, 번역 파일을 활용하면서 유효한 ISO 639-1 로캘 코드와 대문자 로캘 이름을 강제합니다.","es":"Habilita a los agentes a agregar nuevos idiomas y configuraciones regionales a los proyectos Strapi, aprovechando la configuración de administrador de Strapi, el enrutamiento i18n de Next.js y los archivos de traducción, al mismo tiempo que se aplican códigos de configuración regionales ISO 639-1 válidos y nombres de configuración regionales con mayúsculas.","fr":"Permet aux agents d''ajouter de nouvelles langues et paramètres régionaux aux projets Strapi, en exploitant la configuration d''administration Strapi, le routage i18n de Next.js et les fichiers de traduction, tout en appliquant des codes de paramètres régionaux ISO 639-1 valides et des noms de paramètres régionaux en majuscules.","de":"Ermächtigt Agents, neue Sprachen und Ländereinstellungen zu Strapi-Projekten hinzuzufügen, indem sie die Strapi-Admin-Konfiguration, die Next.js-i18n-Weiterleitung und die Übersetzungsdateien nutzen und gleichzeitig gültige ISO-639-1-Ländereinstellungs-Codes und verschachtelte Ländereinstellungs-Namen durchsetzen.","pt":"Habilita os agentes a adicionarem novos idiomas e locais a projetos Strapi, aproveitando a configuração do administrador do Strapi, roteamento i18n do Next.js e arquivos de tradução, enquanto impõe códigos de localização ISO 639-1 válidos e nomes de localização capitalizados.","ru":"Наделяет агентов возможностью добавлять новые языки и локали в проекты Strapi, используя конфигурацию администратора Strapi, маршрутизацию i18n Next.js и файлы перевода, а также обеспечивает соблюдение действительных кодов локали ISO 639-1 и имен локали с заглавной буквы.","ar":"يمنح الوكلاء إضافة لغات و محليات جديدة إلى مشاريع Strapi، مستفيدين من إعدادات إدارة Strapi و توجيه i18n من Next.js و ملفات الترجمة، مع فرض شفرات местية صالحة من ISO 639-1 و أسماء محلية محرفنة."},"useCases":{"en":["Adding new language support to Strapi applications","Configuring Next.js i18n routing for multilingual sites","Validating locale codes and names for consistency"],"zh":["为Strapi应用程序添加新的语言支持","为多语言网站配置Next.js i18n路由","验证区域设置代码和名称的一致性"],"ja":["Strapiアプリケーションに新しい言語サポートを追加する","マルチリンガルサイト用にNext.js i18nルーティングを設定する","ロケールコードと名前の一貫性を検証する"],"ko":["Strapi 애플리케이션에 새로운 언어 지원을 추가하는 것","다국어 사이트를 위한 Next.js i18n 라우팅을 구성하는 것","로캘 코드와 이름의 일관성을 검증하는 것"],"es":["Agregar compatibilidad con nuevos idiomas a aplicaciones Strapi","Configurar el enrutamiento i18n de Next.js para sitios multilingües","Validar códigos y nombres de configuración regional para la coherencia"],"fr":["Ajouter une prise en charge de nouvelles langues aux applications Strapi","Configurer le routage i18n de Next.js pour les sites multilingues","Valider les codes et les noms de paramètres régionaux pour la cohérence"],"de":["Hinzufügen von Unterstützung für neue Sprachen zu Strapi-Anwendungen","Konfigurieren der Next.js-i18n-Weiterleitung für mehrsprachige Websites","Überprüfen von Ländereinstellungs-Codes und -Namen auf Konsistenz"],"pt":["Adicionar suporte a novo idioma a aplicações Strapi","Configurar roteamento i18n do Next.js para sites multilíngues","Validar códigos e nomes de localização para consistência"],"ru":["Добавление поддержки нового языка в приложения Strapi","Настройка маршрутизации i18n Next.js для многоязычных сайтов","Проверка кодов и имен локали на соответствие"],"ar":["إضافة دعم لغة جديدة إلى تطبيقات Strapi","تكوين توجيه i18n من Next.js لمواقع متعددة اللغات","تحقق من شفرات و أسماء المحليات للتسلسل"]},"limitations":{"en":["Requires valid ISO 639-1 locale codes","Strapi and Next.js project setup necessary","Locale name must be capitalized and free of special characters"],"zh":["需要有效的ISO 639-1区域设置代码","需要Strapi和Next.js项目设置","区域名称必须大写并且不包含特殊字符"],"ja":["有効なISO 639-1ロケールコードが必要","StrapiおよびNext.jsプロジェクト設定が必要","ロケール名は大文字で特殊文字を含めずに"],"ko":["유효한 ISO 639-1 로캘 코드가 필요","Strapi 및 Next.js 프로젝트 설정이 필요","로캘 이름은 대문자로하고 특수 문자를 포함하지 않아야 함"],"es":["Requiere códigos de configuración regional ISO 639-1 válidos","Es necesaria la configuración del proyecto Strapi y Next.js","El nombre de la configuración regional debe estar en mayúsculas y no contener caracteres especiales"],"fr":["Nécessite des codes de paramètres régionaux ISO 639-1 valides","La configuration du projet Strapi et Next.js est nécessaire","Le nom du paramètre régional doit être en majuscules et ne pas contenir de caractères spéciaux"],"de":["Erfordert gültige ISO-639-1-Ländereinstellungs-Codes","Strapi- und Next.js-Projektkonfiguration erforderlich","Der Ländereinstellungs-Name muss in Großbuchstaben und frei von Sonderzeichen sein"],"pt":["Requer códigos de localização ISO 639-1 válidos","Configuração de projeto Strapi e Next.js necessária","Nome de localização deve ser capitalizado e livre de caracteres especiais"],"ru":["Требует действительных кодов локали ISO 639-1","Необходима настройка проекта Strapi и Next.js","Имя локали должно быть с заглавной буквы и без специальных символов"],"ar":["يتطلب شفرات محلية صالحة من ISO 639-1","إعداد مشروع Strapi و Next.js ضروري","يجب أن يكون اسم المحلية محرفنًا و خاليًا من الحروف الخاصة"]},"version":4},"contentHash":"798b53275d6d90dfa0f150e0572e52cbd02e3e1c26aae3d8279c4b152bb58870","qualityScore":51}');
