INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matixlol/monitoreo-panama/deploy', 'deploy', 'matixlol', 'monitoreo-panama', 'community', 'deploy matixlol monitoreo-panama community The deploy skill enables users to deploy code from their current directory to Railway using `railway up`. This skill benefits developers who need to deploy local code changes. 使用 Railway Up 部署代码并修复问题，包括提交消息和 CI 模式 Railway Up を使用してコードをデプロイし、問題を修正します。コミットメッセージと CI モードを含みます Railway Up을 사용하여 코드를 배포하고 문제를 수정합니다. 커밋 메시지와 CI 모드를 포함합니다 Deploya código en Railway con railway up y sigue las mejores prácticas para commit messages descriptivos Déployez votre code sur Railway avec railway up et suivez les meilleures pratiques pour les messages de commit descriptifs Deployen Sie Code in Railway mit railway up und folgen Sie den besten Praktiken für beschreibende Commit-Mitteilungen O deploy é um processo que utiliza o comando railway up para implantar código em Railway. Deploy - это процесс, который использует команду railway up для развертывания кода в Railway. ال deploy هو عملية تستخدم الأمر railway up لنشر الكود في Railway. how to use deploy what is deploy deploy to Railway railway up command deploy alternative deploy vs Git deploy install deploy setup guide CI mode deployment Railway Up 部署代码 提交消息 CI 模式 代码部署 Railway 部署 AI エージェント 部署设置 Deploys code to Railway using `railway up` command Supports descriptive commit messages with the `-m` flag Enables deployment in CI mode with `--ci` flag Allows detachment with `--detach` flag Supports deployment of local code changes Deploy is a skill that automates code deployment from a local directory to Railway using the `railway up` command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MuhammadUsmanGM/Skills_Assignment/git-workflow-automation', 'community', 'MuhammadUsmanGM', 'Skills_Assignment', 'MuhammadUsmanGM/Skills_Assignment', 'git-workflow-automation', 0, 0, 51, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:31.075Z', '441266b27b683603db6761ef9becf2a94a6d614d583c7466d315274a7000cc91', '{"id":"MuhammadUsmanGM/Skills_Assignment/git-workflow-automation","name":"git-workflow-automation","description":{"en":"The git-workflow-automation skill automates common Git workflows, providing expert guidance on version control best practices for developers. It helps with tasks such as creating feature branches and managing merge conflicts.","zh":"Git 工作流自动化技能提供 Git 工作流的自动化和最佳实践指导","ja":"Git ワークフロー自動化スキルは Git ワークフローの自動化とベストプラクティスのガイダンスを提供","ko":"Git 작업 흐름 자동화 기능은 Git 작업 흐름의 자동화 및 최고의 관행 가이드를 제공","es":"Automatiza tus flujos de trabajo Git con esta habilidad, que proporciona orientación experta sobre las mejores prácticas para el control de versiones.","fr":"Automatisez vos flux de travail Git avec cette compétence, qui fournit des conseils d''experts sur les meilleures pratiques pour le contrôle de version.","de":"Automatisieren Sie Ihre Git-Workflows mit dieser Fähigkeit, die Expertenratgeber zu den besten Praktiken für die Versionskontrolle bietet.","pt":"Automação de fluxo de trabalho Git para controle de versão eficaz","ru":"Автоматизация рабочего процесса Git для эффективного контроля версий с помощью ИИ Агентов","ar":"تشغيل آلي لتدفق العمل Git للتحكم الفعال في الإصدار"},"seo":{"title":{"en":"git-workflow-automation: Automate Git Tasks | AI Agent Skill","zh":"Git 工作流自动化 Setup Guide - AIエージェント","ja":"Git ワークフロー自動化ベストプラクティス - AIエージェント","ko":"Git 작업 흐름 자동화 가이드 - AI 에이전트","es":"Guía de Automatización de Flujo de Trabajo Git con Herram...","fr":"Guide de l''Automatisation du Flux de Travail Git avec des...","de":"Anleitung zur Automatisierung von Git-Workflows mit KI-Tools","pt":"Guia de Automação de Fluxo de Trabalho Git","ru":"Настройка автоматизации рабочего процесса Git с помощью И...","ar":"دليل تشغيل آلي لتدفق العمل Git"},"description":{"en":"Streamline your Git workflow with expert guidance on best practices and automation of repetitive tasks - learn how to get started now!","zh":"自动化 Git 工作流，提高开发效率。了解 Git Flow 和 GitHub Flow 方法ology，并掌握分支策略、合并冲突解决等","ja":"Git ワークフローを自動化して開発効率を向上させる。Git Flow と GitHub Flow のベストプラクティスを学び、ブランチ戦略やマージコンフリクト解決などをマスター","ko":"Git 작업 흐름을 자동화하여 개발 효율성을 높입니다. Git Flow와 GitHub Flow 방법론 및 분기 전략, 병합 충돌 해결 등을 학습","es":"Aprende a automatizar tus flujos de trabajo Git con esta guía completa. Mejora tu productividad con las mejores prácticas y herramientas de AI.","fr":"Découvrez comment automatiser vos flux de travail Git avec ce guide complet. Améliorez votre productivité avec les meilleures pratiques et les outils d''IA.","de":"Erfahren Sie, wie Sie Ihre Git-Workflows automatisieren können, mit diesem umfassenden Leitfaden. Verbessern Sie Ihre Produktivität mit den besten Praktiken ...","pt":"Aprenda a automatizar fluxos de trabalho Git comuns com este guia de melhores práticas para controle de versão","ru":"Автоматизируйте общие рабочие процессы Git с помощью этого руководства по лучшим практикам для контроля версий и ИИ Агентов","ar":"تعلم تشغيل آلي لتدفقات العمل Git الشائعة مع هذا الدليل لأفضل الممارسات للتحكم في الإصدار"},"definition":{"en":"git-workflow-automation is a skill that automates Git workflows, following methodologies like Git Flow or GitHub Flow, to simplify version control and collaboration for developers.","zh":"Git 工作流自动化是指使用 Git 工作流的自动化工具和技术来提高开发效率","ja":"Git ワークフロー自動化とは、Git ワークフローの自動化ツールとテクノロジーを使用して開発効率を向上させること","ko":"Git 작업 흐름 자동화란 Git 작업 흐름의 자동화 도구 및 기술을 사용하여 개발 효율성을 높이는 것을 의미","es":"La automatización del flujo de trabajo Git es una habilidad que permite automatizar tareas comunes de Git y proporciona orientación experta sobre las mejores prácticas.","fr":"L''automatisation du flux de travail Git est une compétence qui permet d''automatiser les tâches courantes de Git et fournit des conseils d''experts sur les meilleures pratiques.","de":"Die Automatisierung von Git-Workflows ist eine Fähigkeit, die es ermöglicht, gemeinsame Git-Aufgaben zu automatisieren und bietet Expertenratgeber zu den besten Praktiken.","pt":"Automação de fluxo de trabalho Git é uma técnica para automatizar tarefas de controle de versão","ru":"Автоматизация рабочего процесса Git - это техника для автоматизации задач контроля версий","ar":"تشغيل آلي لتدفق العمل Git هو تقنية لتشغيل آلي لمهام التحكم في الإصدار"},"features":{"en":["Creates feature branches with proper naming conventions","Manages merge conflicts and resolution strategies","Follows Git Flow or GitHub Flow methodologies for version control","Automates creation and review of pull requests","Performs release and hotfix operations","Automates repetitive Git tasks for efficient workflow"],"zh":["自动创建特性分支","管理合并冲突和解决策略","支持 Git Flow 和 GitHub Flow 方法ology","创建和审查拉取请求","执行发布和热修复操作","自动化重复的 Git 任务"],"ja":["特性ブランチの自動作成","マージコンフリクトと解決戦略の管理","Git Flow と GitHub Flow のサポート","プルリクエストの作成とレビュー","リリースとホットフィックス操作の実行","繰り返しの Git タスクの自動化"],"ko":["특성 분기 자동 생성","병합 충돌 및 해결 전략 관리","Git Flow 및 GitHub Flow 지원","풀 요청 생성 및 검토","릴리스 및 핫픽스 작업 수행","반복적인 Git 작업 자동화"],"es":["Creación de ramas de características con convenciones de nomenclatura adecuadas","Gestión de conflictos de fusión y estrategias de resolución","Seguimiento de las metodologías Git Flow o GitHub Flow","Creación y revisión de solicitudes de extracción","Realización de operaciones de lanzamiento y corrección de errores","Automatización de tareas repetitivas de Git"],"fr":["Création de branches de fonctionnalités avec des conventions de nommage appropriées","Gestion des conflits de fusion et des stratégies de résolution","Suivi des méthodologies Git Flow ou GitHub Flow","Création et revue de demandes d''extraction","Réalisations d''opérations de lancement et de correction de bogues","Automatisation de tâches répétitives de Git"],"de":["Erstellung von Feature-Branches mit geeigneten Namenskonventionen","Verwaltung von Merge-Konflikten und Lösungsstrategien","Verfolgung der Git-Flow- oder GitHub-Flow-Methoden","Erstellung und Überprüfung von Pull-Requests","Durchführung von Release- und Hotfix-Operationen","Automatisierung von wiederkehrenden Git-Aufgaben"],"pt":["Criação de branches de recursos com convenções de nomenclatura adequadas","Gerenciamento de conflitos de mesclagem e estratégias de resolução","Seguimento das metodologias Git Flow ou GitHub Flow","Criação e revisão de pull requests","Execução de operações de lançamento e hotfix"],"ru":["Создание фич-branches с правильными соглашениями об именовании","Управление конфликтами слияния и стратегии решения","Следование методологиям Git Flow или GitHub Flow с помощью ИИ Агентов","Создание и проверка пул-реквестов","Выполнение операций по выпуску и хотфиксу"],"ar":["إنشاء فروع الميزات مع اتفاقيات التسمية المناسبة","إدارة صراعات الدمج واستراتيجيات الحل","متابعة منهجيات Git Flow أو GitHub Flow","إنشاء ومراجعة طلبات السحب","تنفيذ عمليات الإصدار والإصلاح السريع"]},"keywords":{"en":["git-workflow-automation setup guide","how to use git-workflow-automation","git-workflow-automation vs GitHub Flow","what is git-workflow-automation","git-workflow-automation install","automating git tasks with git-workflow-automation"],"zh":["Git 工作流自动化","Git Flow","GitHub Flow","分支策略","合并冲突解决","拉取请求","发布和热修复","AIエージェント","开发效率"],"ja":["Git ワークフロー自動化","Git Flow","GitHub Flow","ブランチ戦略","マージコンフリクト解決","プルリクエスト","リリースとホットフィックス","AIエージェント","開発効率"],"ko":["Git 작업 흐름 자동화","Git Flow","GitHub Flow","분기 전략","병합 충돌 해결","풀 요청","릴리스 및 핫픽스","AI 에이전트","개발 효율성"],"es":["automatización de flujo de trabajo Git","herramientas de AI para Git","mejores prácticas de control de versiones","Git Flow","GitHub Flow","automatización de tareas de Git","resolución de conflictos de fusión","creación de ramas de características","solicitudes de extracción"],"fr":["automatisation du flux de travail Git","outils d''IA pour Git","meilleures pratiques de contrôle de version","Git Flow","GitHub Flow","automatisation de tâches Git","résolution de conflits de fusion","création de branches de fonctionnalités","demandes d''extraction"],"de":["Automatisierung von Git-Workflows","KI-Tools für Git","beste Praktiken für die Versionskontrolle","Git-Flow","GitHub-Flow","Automatisierung von Git-Aufgaben","Lösung von Merge-Konflikten","Erstellung von Feature-Branches","Pull-Requests"],"pt":["automação de fluxo de trabalho Git","controle de versão","Git Flow","GitHub Flow","branches de recursos","conflitos de mesclagem","pull requests","lançamento e hotfix"],"ru":["автоматизация рабочего процесса Git","контроль версий","Git Flow","GitHub Flow","фич-branches","конфликты слияния","пул-реквесты","выпуск и хотфикс","ИИ Агенты"],"ar":["تشغيل آلي لتدفق العمل Git","التحكم في الإصدار","Git Flow","GitHub Flow","فروع الميزات","صراعات الدمج","طلبات السحب","الإصدار والإصلاح السريع"]}},"owner":"MuhammadUsmanGM","repo":"Skills_Assignment","repoPath":"MuhammadUsmanGM/Skills_Assignment","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"git-workflow-automation","description":"Comprehensive Git workflow automation including branching strategies, pull request creation, code reviews, merge strategies, and release management. Use when Claude needs to help with Git operations, branching models (Git Flow, GitHub Flow), pull request creation, code reviews, merge conflicts, or release processes.","bodyPreview":"# Git Workflow Automation\n\n## Overview\nThis skill automates common Git workflows and provides expert guidance on best practices for version control.\n\n## When to Use This Skill\n- Creating feature branches with proper naming conventions\n- Managing merge conflicts and resolution strategies\n- Following Git Flow or GitHub Flow methodologies\n- Creating and reviewing pull requests\n- Performing release and hotfix operations\n- Automating repetitive Git tasks\n\n## Branching Strategies\n\n### Git Flow\n```\nmai","body":"# Git Workflow Automation\n\n## Overview\nThis skill automates common Git workflows and provides expert guidance on best practices for version control.\n\n## When to Use This Skill\n- Creating feature branches with proper naming conventions\n- Managing merge conflicts and resolution strategies\n- Following Git Flow or GitHub Flow methodologies\n- Creating and reviewing pull requests\n- Performing release and hotfix operations\n- Automating repetitive Git tasks\n\n## Branching Strategies\n\n### Git Flow\n```\nmain (production-ready code)\n├── develop (integration branch)\n│   ├── feature/* (feature branches)\n│   └── release/* (release preparation)\n└── hotfix/* (urgent fixes)\n```\n\n### GitHub Flow\n```\nmain (always deployable)\n└── feature/* (short-lived branches)\n```\n\n## Common Operations\n\n### Creating a Feature Branch\n```bash\ngit checkout -b feature/user-authentication\n```\n\n### Syncing with Upstream\n```bash\ngit checkout main\ngit pull origin main\ngit checkout feature/user-authentication\ngit rebase main\n```\n\n### Resolving Merge Conflicts\n1. Identify conflicted files: `git status`\n2. Open files and look for conflict markers: `<<<<<<<`, `=======`, `>>>>>>>`\n3. Manually resolve conflicts by keeping desired changes\n4. Stage resolved files: `git add .`\n5. Complete the merge: `git rebase --continue` or `git merge --continue`\n\n## Pull Request Best Practices\n- Write clear, descriptive titles and descriptions\n- Link to related issues\n- Include testing instructions\n- Specify reviewers\n- Follow conventional commit messages\n\n## Release Management\n- Tag releases with semantic versioning (v1.2.3)\n- Create release notes highlighting changes\n- Verify CI/CD pipelines pass before merging\n- Coordinate with stakeholders for deployment timing\n\n## Scripts Available\n- `scripts/create-feature-branch.sh` - Automated feature branch creation\n- `scripts/sync-with-main.sh` - Sync current branch with main\n- `scripts/prepare-release.sh` - Prepare a new release branch\n\n## References\n- `references/naming-conventions.md` - Git branch naming conventions and best practices\n- `references/workflow-patterns.md` - Detailed workflow patterns and commands for different Git strategies"},"lastSynced":"2026-03-08T02:03:31.075Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Workflow Agents needing automated version control and conflict resolution capabilities.","zh":"非常适合需要自动化版本控制和冲突解决功能的开发工作流程Agent。","ja":"自動化されたバージョン管理とコンフリクト解決機能を必要とする開発ワークフローAgentに最適です。","ko":"자동화된 버전 관리 및 충돌 해결 기능이 필요한 개발 워크플로우 에이전트에 완벽합니다.","es":"Perfecto para agentes de flujo de trabajo de desarrollo que necesitan capacidades automatizadas de control de versiones y resolución de conflictos.","fr":"Parfait pour les agents de flux de travail de développement nécessitant des capacités automatisées de contrôle de version et de résolution de conflits.","de":"Perfekt für Development Workflow Agents, die automatisierte Versionskontroll- und Konfliktlösungsfunktionen benötigen.","pt":"Perfeito para agentes de fluxo de desenvolvimento que necessitam de controle de versão automatizado e capacidades de resolução de conflitos.","ru":"Идеально подходит для агентов рабочего процесса разработки, которые требуют автоматизированного контроля версий и возможностей разрешения конфликтов.","ar":"مثالي لعمليات وكيل تدفق التطوير التي تحتاج إلى التحكم التلقائي في الإصدار وقدرات حل النزاعات."},"recommendation":{"en":"Enables AI agents to automate complex Git operations including feature branch creation with proper naming conventions, merge conflict resolution strategies, and implementation of Git Flow or GitHub Flow methodologies. Provides expert guidance on pull request management and release/hotfix operations.","zh":"使AI agent能够自动化复杂的Git操作，包括采用正确命名规范的功能分支创建、合并冲突解决策略，以及Git Flow或GitHub Flow方法的实施。提供有关pull request管理和release/hotfix操作的专业指导。","ja":"適切な命名規則に基づく機能ブランチの作成、マージコンフリクト解決戦略、Git FlowまたはGitHub Flow手法の実装を含む、複雑なGit操作の自動化をAI agentに可能にします。pull request管理およびrelease/hotfix操作に関する専門的なガイダンスを提供します。","ko":"적절한 명명 규칙을 따른 기능 브랜치 생성, 병합 충돌 해결 전략, Git Flow 또는 GitHub Flow 방법론 구현을 포함한 복잡한 Git 작업을 AI agent가 자동화할 수 있도록 합니다. pull request 관리 및 release/hotfix 작업에 대한 전문적인 지도를 제공합니다.","es":"Permite a los agentes de IA automatizar operaciones complejas de Git, incluyendo la creación de ramas de características con convenciones de nomenclatura adecuadas, estrategias de resolución de conflictos de fusión e implementación de metodologías Git Flow o GitHub Flow. Proporciona orientación experta sobre la gestión de pull requests y operaciones de release/hotfix.","fr":"Permet aux agents IA d''automatiser les opérations Git complexes, y compris la création de branches de fonctionnalités avec des conventions de dénomination appropriées, les stratégies de résolution de conflits de fusion et la mise en œuvre des méthodologies Git Flow ou GitHub Flow. Fournit des conseils d''expert sur la gestion des pull requests et les opérations de release/hotfix.","de":"Ermöglicht es KI-Agenten, komplexe Git-Operationen zu automatisieren, einschließlich der Erstellung von Feature-Branches mit richtigen Namenskonventionen, Strategien zur Lösung von Merge-Konflikten und der Implementierung von Git Flow- oder GitHub Flow-Methodiken. Bietet Expertenanleitung für das Management von Pull Requests und Release/Hotfix-Operationen.","pt":"Habilita agentes de IA a automatizar operações Git complexas, incluindo a criação de branches de recursos com convenções de nomenclatura apropriadas, estratégias de resolução de conflitos de mesclagem e implementação de metodologias Git Flow ou GitHub Flow. Fornece orientação especializada em gerenciamento de solicitações de pull e operações de lançamento e hotfix.","ru":"Позволяет агентам ИИ автоматизировать сложные операции Git, включая создание веток функций с правильными соглашениями об именовании, стратегии разрешения конфликтов слияния и реализацию методологий Git Flow или GitHub Flow. Предоставляет экспертные рекомендации по управлению запросами на вытягивание и операциям выпуска и исправления.","ar":"يمكن للوكلاء الذكاء الاصطناعي من تلقين عمليات جيت المعقدة، بما في ذلك إنشاء فروع الميزة مع الاتفاقيات المناسبة للتسمية، و استراتيجيات حل الصراعات الارتباطية، وتنفيذ منهجيات جيت فلوف أو جيت هب فلوف. يوفر إرشادات الخبراء لإدارة طلبات السحب وعمليات الإصدار والتصحيح السريع."},"useCases":{"en":["Automating feature branch creation with naming conventions","Managing merge conflicts and resolution strategies","Implementing Git Flow methodology workflows","Creating and reviewing pull requests","Performing release and hotfix operations"],"zh":["使用命名规范自动化功能分支创建","管理合并冲突和解决策略","实施Git Flow方法的工作流程","创建和审查pull request","执行release和hotfix操作"],"ja":["命名規則を使用した機能ブランチ作成の自動化","マージコンフリクトと解決戦略の管理","Git Flow手法のワークフローの実装","pull requestの作成とレビュー","releaseおよびhotfix操作の実行"],"ko":["명명 규칙을 사용한 기능 브랜치 생성 자동화","병합 충돌 및 해결 전략 관리","Git Flow 방법론 워크플로우 구현","pull request 생성 및 검토","release 및 hotfix 작업 수행"],"es":["Automatización de la creación de ramas de características con convenciones de nomenclatura","Gestión de conflictos de fusión y estrategias de resolución","Implementación de flujos de trabajo de metodología Git Flow","Creación y revisión de pull requests","Realización de operaciones de release y hotfix"],"fr":["Automatisation de la création de branches de fonctionnalités avec des conventions de dénomination","Gestion des conflits de fusion et des stratégies de résolution","Mise en œuvre des workflows de méthodologie Git Flow","Création et examen des pull requests","Exécution des opérations de release et hotfix"],"de":["Automatisierung der Erstellung von Feature-Branches mit Namenskonventionen","Verwaltung von Merge-Konflikten und Lösungsstrategien","Implementierung von Git Flow-Methodik-Workflows","Erstellung und Überprüfung von Pull Requests","Durchführung von Release- und Hotfix-Operationen"],"pt":["Automatizar a criação de branches de recursos com convenções de nomenclatura","Gerenciar conflitos de mesclagem e estratégias de resolução","Implementar fluxos de trabalho de metodologia Git Flow","Criar e revisar solicitações de pull","Realizar operações de lançamento e hotfix"],"ru":["Автоматизировать создание веток функций с соглашениями об именовании","Управлять конфликтами слияния и стратегиями разрешения","Реализовать рабочие процессы методологии Git Flow","Создавать и просматривать запросы на вытягивание","Выполнять операции выпуска и исправления"],"ar":["تلقين إنشاء فروع الميزة مع الاتفاقيات المناسبة للتسمية","إدارة الصراعات الارتباطية و استراتيجيات الحل","تنفيذ منهجيات جيت فلوف","إنشاء ومراجعة طلبات السحب","تنفيذ عمليات الإصدار والتصحيح السريع"]},"limitations":{"en":["Requires Git installation and repository access","Limited to Git-based version control systems","Depends on proper repository permissions"],"zh":["需要安装Git并具有仓库访问权限","仅限于基于Git的版本控制系统","依赖正确的仓库权限"],"ja":["Gitのインストールとリポジトリへのアクセスが必要","Gitベースのバージョン管理システムに限定される","適切なリポジトリ権限に依存する"],"ko":["Git 설치 및 저장소 액세스 권한 필요","Git 기반 버전 관리 시스템으로 제한됨","적절한 저장소 권한에 의존"],"es":["Requiere instalación de Git y acceso al repositorio","Limitado a sistemas de control de versiones basados en Git","Depende de los permisos adecuados del repositorio"],"fr":["Nécessite l''installation de Git et l''accès au dépôt","Limité aux systèmes de contrôle de version basés sur Git","Dépend des permissions appropriées du dépôt"],"de":["Erfordert Git-Installation und Repository-Zugriff","Beschränkt auf Git-basierte Versionskontrollsysteme","Hängt von angemessenen Repository-Berechtigungen ab"],"pt":["Requer instalação do Git e acesso ao repositório","Limitado a sistemas de controle de versão baseados em Git","Depende das permissões de repositório apropriadas"],"ru":["Требует установки Git и доступа к репозиторию","Ограничен системами контроля версий на основе Git","Зависит от правильных разрешений репозитория"],"ar":["يتطلب تثبيت جيت ووصول إلى المستودع","محدود بنظم التحكم في الإصدارات المستندة إلى جيت","يعتمد على صلاحيات المستودع المناسبة"]},"version":4},"contentHash":"441266b27b683603db6761ef9becf2a94a6d614d583c7466d315274a7000cc91","qualityScore":51}');
