Git Flow or GitHub Flow, to simplify version control and collaboration for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('POBIM/Claude-Skill-Teach/boq', 'community', 'POBIM', 'Claude-Skill-Teach', 'POBIM/Claude-Skill-Teach', 'boq', 0, 0, 51, '2026-03-08T01:57:15.346Z', '2026-03-08T02:03:36.999Z', '91bd4239e38bc74f5eb2d2954d0d62ad7b8ca906965ec7e3b96ff8122b0621d5', '{"id":"POBIM/Claude-Skill-Teach/boq","name":"boq","description":{"en":"The BOQ skill helps developers automate bill of quantities management for construction projects, utilizing Excel for efficient cost estimation and project planning.","zh":"BOQ 技能用于创建和管理建筑成本估算，支持 5 个主要工作类别，包括准备、结构、建筑、安装和装修","ja":"BOQ スキルは、建設費用見積もりを作成および管理するために使用され、5 つの主な作業カテゴリ（準備、構造、建築、インストール、フィニッシュ）をサポートします","ko":"BOQ 스킬은 건설 비용估算을 생성하고 관리하는 데 사용되며 5개의 주요 작업 카테고리(준비, 구조, 건축, 설치, 마감)를 지원합니다","es":"El skill BOQ permite la creación y gestión de bill of quantities para la construcción, utilizando Excel para organizar y calcular costos","fr":"Le skill BOQ permet la création et la gestion de bill of quantities pour la construction, en utilisant Excel pour organiser et calculer les coûts","de":"Das BOQ-Skill ermöglicht die Erstellung und Verwaltung von Baubillen für die Bauwirtschaft, unter Verwendung von Excel zur Organisation und Kalkulation von Kosten","pt":"A ferramenta BOQ é uma solução para criar orçamentos de construção precisos com o Excel. Ela oferece 5 categorias de trabalho principais para ajudar a gerenciar seus projetos de construção.","ru":"ИИ Агент BOQ - это решение для создания точных смет строительных расходов с помощью Excel. Он предлагает 5 основных категорий работ для помощи в управлении вашими строительными проектами.","ar":"أداة BOQ هي حل لإنشاء تقديرات دقيقة للتكاليف الإنشائية باستخدام Excel. توفر 5 فئات عمل رئيسية لمساعدتك في إدارة مشاريع البناء الخاصة بك."},"seo":{"title":{"en":"BOQ: Bill of Quantities Setup Guide for AI Agents","zh":"BOQ Setup Guide: 使用 Excel 创建和管理建筑成本估算","ja":"BOQ セットアップガイド: Excel を使用した建設費用見積もりを作成および管理する","ko":"BOQ 설정 가이드: Excel을 사용하여 건설 비용估算を作成하고 관리한다","es":"Guía de configuración de BOQ para gestión de costos de co...","fr":"Guide de mise en place de BOQ pour la gestion des coûts d...","de":"BOQ-Setup-Anleitung für Baukostenmanagement","pt":"Guia de Configuração do BOQ: Ferramenta de Criação de Orç...","ru":"Настройка ИИ Агента BOQ: Создание Сметы Строительных Расх...","ar":"دليل إعداد BOQ: أداة إنشاء تقديرات التكاليف الإنشائية"},"description":{"en":"Discover how to automate bill of quantities management with BOQ skill. Learn to generate and manage construction cost estimates using Excel.","zh":"了解如何使用 BOQ 技能创建和管理建筑成本估算，包括 5 个主要工作类别：准备、结构、建筑、安装和装修","ja":"BOQ スキルを使用して建設費用見積もりを作成および管理する方法を学びます。主な 5 つの作業カテゴリ：準備、構造、建築、インストール、フィニッシュ","ko":"BOQ 스킬을 사용하여 건설 비용估算を作成하고 관리하는 방법을 알아보세요. 주요 5개 작업 카테고리: 준비, 구조, 건축, 설치, 마감","es":"Aprende a configurar y gestionar tus BOQ con nuestra guía detallada, incluyendo mejores prácticas y ejemplos de implementación en Excel","fr":"Découvrez comment configurer et gérer vos BOQ avec notre guide détaillé, y compris les meilleures pratiques et exemples de mise en œuvre dans Excel","de":"Erfahren Sie, wie Sie Ihre BOQ konfigurieren und verwalten können, mit unserer detaillierten Anleitung, einschließlich Best Practices und Beispielen für die ...","pt":"Aprenda a configurar a ferramenta BOQ para criar orçamentos de construção precisos com o Excel. Descubra as melhores práticas e dicas para otimizar seu proce...","ru":"Узнайте, как настроить ИИ Агент BOQ для создания точных смет строительных расходов с помощью Excel. Откройте для себя лучшие практики и советы для оптимизаци...","ar":"تعلم كيفية إعداد أداة BOQ لإنشاء تقديرات دقيقة للتكاليف الإنشائية باستخدام Excel. اكتشف أفضل الممارسات والنصائح لتحسين عملية التقييم الخاص بك."},"definition":{"en":"boq is a bill of quantities management skill that enables automated generation and management of construction cost estimates using Excel.","zh":"BOQ 是一种用于创建和管理建筑成本估算的技能，支持 Excel 输出","ja":"BOQ は、Excel 出力対応の建設費用見積もりを作成および管理するスキルです","ko":"BOQ는 Excel 출력을 지원하는 건설 비용估算을 생성하고 관리하는 스킬입니다","es":"BOQ significa Bill of Quantities, una lista detallada de materiales y servicios necesarios para un proyecto de construcción","fr":"BOQ signifie Bill of Quantities, une liste détaillée de matériaux et de services nécessaires pour un projet de construction","de":"BOQ bedeutet Bill of Quantities, eine detaillierte Liste von Materialien und Dienstleistungen, die für ein Bauprojekt erforderlich sind","pt":"O que é BOQ? É uma ferramenta de criação de orçamentos de construção que ajuda a gerenciar projetos de construção com precisão.","ru":"Что такое BOQ? Это инструмент для создания смет строительных расходов, который помогает управлять строительными проектами с точностью.","ar":"ما هو BOQ؟ هو أداة لإنشاء تقديرات التكاليف الإنشائية التي تساعد في إدارة مشاريع البناء بدقة."},"features":{"en":["Generates BOQ files in Excel format","Organizes output files in a dedicated workspace folder","Follows best practices outlined in BEST_PRACTICES.md","Categorizes construction work into 5 standard categories","Supports detailed cost estimation for construction projects"],"zh":["支持 5 个主要工作类别：准备、结构、建筑、安装和装修","使用 Excel 输出 BOQ 文件","文件保存在(workspace/boq_examples/)目录中","提供最佳实践指南(BEST_PRACTICES.md)"],"ja":["5 つの主な作業カテゴリ（準備、構造、建築、インストール、フィニッシュ）をサポート","Excel で BOQ ファイルを出力","ファイルを(workspace/boq_examples/)ディレクトリに保存","ベストプラクティスガイド(BEST_PRACTICES.md)を提供"],"ko":["5개의 주요 작업 카테고리(준비, 구조, 건축, 설치, 마감)를 지원","Excel에서 BOQ 파일을 출력","파일을(workspace/boq_examples/)디렉토리에 저장","베스트 프랙티스 가이드(BEST_PRACTICES.md)를 제공"],"es":["Creación de BOQ personalizados utilizando Excel","Organización de costos en 5 categorías principales: preparación, estructura, arquitectura, etc.","Implementación de mejores prácticas para la gestión de BOQ","Generación de archivos BOQ en el directorio workspace/boq_examples/","Integración con herramientas de cálculo de costos para la construcción"],"fr":["Création de BOQ personnalisés à l''aide d''Excel","Organisation des coûts en 5 catégories principales : préparation, structure, architecture, etc.","Mise en œuvre de meilleures pratiques pour la gestion de BOQ","Génération de fichiers BOQ dans le répertoire workspace/boq_examples/","Intégration avec des outils de calcul de coûts pour la construction"],"de":["Erstellung von benutzerdefinierten BOQ mithilfe von Excel","Organisation von Kosten in 5 Hauptkategorien: Vorbereitung, Struktur, Architektur usw.","Umsetzung von Best Practices für die Verwaltung von BOQ","Generierung von BOQ-Dateien im Verzeichnis workspace/boq_examples/","Integration mit Kostenberechnungstools für die Bauwirtschaft"],"pt":["Criação de orçamentos de construção com o Excel","5 categorias de trabalho principais para gerenciar projetos de construção","Armazenamento de arquivos BOQ em pasta separada para organização","Melhores práticas para criação de orçamentos de construção disponíveis em BEST_PRACTICES.md"],"ru":["Создание смет строительных расходов с помощью Excel","5 основных категорий работ для управления строительными проектами","Хранение файлов BOQ в отдельной папке для организации","Лучшие практики для создания смет строительных расходов доступны в BEST_PRACTICES.md"],"ar":["إنشاء تقديرات التكاليف الإنشائية باستخدام Excel","5 فئات عمل رئيسية لإدارة مشاريع البناء","تخزين ملفات BOQ في مجلد منفصل للتنظيم","أفضل الممارسات لإنشاء تقديرات التكاليف الإنشائية متاحة في BEST_PRACTICES.md"]},"keywords":{"en":["how to use boq","boq setup guide","bill of quantities management","boq alternative","boq vs excel","construction cost estimation","boq install","what is boq"],"zh":["BOQ 技能","建筑成本估算","Excel 输出","建设费用见估","BOQ 创建","BOQ 管理","AI エージェント","AI 工具"],"ja":["BOQ スキル","建設費用見積もり","Excel 出力","BOQ 作成","BOQ 管理","AI エージェント","AI ツール","Python","CLI"],"ko":["BOQ 스킬","건설 비용估算","Excel 출력","BOQ 생성","BOQ 관리","AI 에이전트","AI 툴","React","Python"],"es":["BOQ","gestión de costos de construcción","bill of quantities","Excel para construcción","mejores prácticas para BOQ","creación de BOQ personalizados","organización de costos de construcción"],"fr":["BOQ","gestion des coûts de construction","bill of quantities","Excel pour la construction","meilleures pratiques pour BOQ","création de BOQ personnalisés","organisation des coûts de construction"],"de":["BOQ","Baukostenmanagement","bill of quantities","Excel für die Bauwirtschaft","Best Practices für BOQ","Erstellung von benutzerdefinierten BOQ","Organisation von Baukosten"],"pt":["BOQ","orçamento de construção","Excel","gerenciamento de projetos de construção","criação de orçamentos de construção","ferramenta de orçamento de construção"],"ru":["BOQ","смета строительных расходов","Excel","управление строительными проектами","создание смет строительных расходов","инструмент для создания смет строительных расходов"],"ar":["BOQ","تقييم التكاليف الإنشائية","Excel","إدارة مشاريع البناء","إنشاء تقديرات التكاليف الإنشائية","أداة لإنشاء تقديرات التكاليف الإنشائية"]}},"owner":"POBIM","repo":"Claude-Skill-Teach","repoPath":"POBIM/Claude-Skill-Teach","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.346Z","topics":[],"category":"community","skillMd":{"name":"boq","description":"Comprehensive BOQ (Bill of Quantities) creation and management for construction projects. This skill should be used when Claude needs to: (1) Create new BOQ files with standard work categories, (2) Add items to existing BOQ, (3) Manage construction cost estimates with material and labor breakdowns, (4) Generate Thai construction project cost sheets with proper formatting","bodyPreview":"# BOQ (Bill of Quantities) Skill\n\nทักษะสำหรับจัดทำและจัดการใบประมาณราคาค่าก่อสร้าง (BOQ) ด้วย Excel\n\n**📁 Output Location:** ไฟล์ BOQ ที่สร้างจะถูกบันทึกไปที่ `workspace/boq_examples/` เพื่อแยกออกจาก skill folder\n\n**📚 Best Practices:** อ่านแนวทางการจัดทำ BOQ ที่ถูกต้องได้ที่ `BEST_PRACTICES.md`\n\n## หมวดงานมาตรฐาน\n\nBOQ ทุกไฟล์จะมี 5 หมวดงานหลัก:\n1. **งานเตรียมการ** - งานรื้อถอน, ปรับพื้นที่, ขนขยะ\n2. **งานโครงสร้าง** - งานเทคอนกรีต, เหล็กเสริม, โครงสร้างหลัก\n3. **งานสถาปัตยกรรม** - งานผนัง, งานฝ","body":"# BOQ (Bill of Quantities) Skill\n\nทักษะสำหรับจัดทำและจัดการใบประมาณราคาค่าก่อสร้าง (BOQ) ด้วย Excel\n\n**📁 Output Location:** ไฟล์ BOQ ที่สร้างจะถูกบันทึกไปที่ `workspace/boq_examples/` เพื่อแยกออกจาก skill folder\n\n**📚 Best Practices:** อ่านแนวทางการจัดทำ BOQ ที่ถูกต้องได้ที่ `BEST_PRACTICES.md`\n\n## หมวดงานมาตรฐาน\n\nBOQ ทุกไฟล์จะมี 5 หมวดงานหลัก:\n1. **งานเตรียมการ** - งานรื้อถอน, ปรับพื้นที่, ขนขยะ\n2. **งานโครงสร้าง** - งานเทคอนกรีต, เหล็กเสริม, โครงสร้างหลัก\n3. **งานสถาปัตยกรรม** - งานผนัง, งานฝ้า, งานสี, งานพื้น\n4. **งานระบบไฟฟ้า** - ระบบไฟฟ้า, ระบบแสงสว่าง, เต้ารับ\n5. **งานระบบสุขาภิบาล** - งานประปา, งานท่อ, สุขภัณฑ์\n\n## โครงสร้างตาราง BOQ\n\nแต่ละ BOQ จะมีคอลัมน์:\n- **ลำดับ** - เลขที่รายการ\n- **รายการ** - รายละเอียดงาน\n- **ปริมาณ** - จำนวน\n- **หน่วย** - หน่วยนับ (ตร.ม., ตร.วา, จุด, ชุด, etc.)\n- **ค่าวัสดุต่อหน่วย** - ราคาวัสดุต่อหน่วย\n- **ราคารวมวัสดุ** - คำนวณอัตโนมัติ: ปริมาณ × ค่าวัสดุต่อหน่วย\n- **ค่าแรงต่อหน่วย** - ค่าแรงต่อหน่วย\n- **ค่าแรงรวม** - คำนวณอัตโนมัติ: ปริมาณ × ค่าแรงต่อหน่วย\n- **รวมราคา** - คำนวณอัตโนมัติ: ราคารวมวัสดุ + ค่าแรงรวม\n- **หมายเหตุ** - หมายเหตุเพิ่มเติม\n\n## การใช้งาน\n\n### 1. สร้าง BOQ ใหม่\n\nUse the `boq_helper.py` script to create a new BOQ:\n\n```bash\npython boq_helper.py create <filename> [project_name] [location] [customer]\n```\n\n**Examples:**\n\n```bash\n# สร้าง BOQ พื้นฐาน\npython boq_helper.py create project_boq.xlsx\n\n# สร้าง BOQ พร้อมข้อมูลโครงการ\npython boq_helper.py create office_renovation.xlsx \"โครงการปรับปรุงสำนักงาน\" \"กรุงเทพมหานคร\" \"บริษัท ABC จำกัด\"\n```\n\nThe script creates a formatted Excel file with:\n- Project information header (ข้อมูลโครงการ, สถานที่, ลูกค้า)\n- All 5 standard work categories with space for 3 items each\n- Automatic calculation formulas for costs\n- Summary rows for each category\n- Grand total at the bottom\n- Professional formatting with colors and borders\n\n### 2. เพิ่มรายการใน BOQ\n\nAdd items to specific categories:\n\n```bash\npython boq_helper.py add <filename> <category> <item_no> <description> <quantity> <unit> [material_cost] [labor_cost] [note]\n```\n\n**Parameters:**\n- `filename`: BOQ file path\n- `category`: One of the 5 standard categories (exact match required)\n- `item_no`: Item number (e.g., \"1.1\", \"2.1\")\n- `description`: Item description\n- `quantity`: Quantity (number)\n- `unit`: Unit (e.g., \"ตร.ม.\", \"ตร.วา\", \"จุด\", \"ชุด\")\n- `material_cost`: Material cost per unit (optional, default: 0)\n- `labor_cost`: Labor cost per unit (optional, default: 0)\n- `note`: Additional notes (optional)\n\n**Example:**\n\n```bash\npython boq_helper.py add office_renovation.xlsx \"งานเตรียมการ\" \"1.1\" \"รื้อถอนผนังเก่า\" 25.5 \"ตร.ม.\" 50 150 \"รวมขนย้ายเศษวัสดุ\"\n```\n\n### 3. คำนวณ Formula ใหม่\n\nAfter adding items, recalculate all formulas:\n\n```bash\npython recalc.py <filename>\n```\n\n**Example:**\n```bash\npython recalc.py office_renovation.xlsx\n```\n\nThe recalc script:\n- Recalculates all formulas (ราคารวมวัสดุ, ค่าแรงรวม, รวมราคา, etc.)\n- Updates summary rows for each category\n- Updates grand total\n- Checks for Excel errors (#REF!, #DIV/0!, etc.)\n- Returns JSON with status and any errors found\n\n## Workflow Example\n\nComplete workflow for creating a BOQ:\n\n```python\nimport subprocess\nimport json\n\n# 1. Create new BOQ\nresult = subprocess.run([\n    ''python'', ''boq_helper.py'', ''create'',\n    ''renovation.xlsx'',\n    ''โครงการปรับปรุงอาคาร'',\n    ''กรุงเทพฯ'',\n    ''บริษัท XYZ''\n], capture_output=True, text=True)\nprint(json.loads(result.stdout))\n\n# 2. Add items to different categories\nitems = [\n    (''งานเตรียมการ'', ''1.1'', ''รื้อถอนผนัง'', 30, ''ตร.ม.'', 50, 150),\n    (''งานโครงสร้าง'', ''2.1'', ''เทพื้นคอนกรีต'', 50, ''ตร.ม.'', 800, 400),\n    (''งานสถาปัตยกรรม'', ''3.1'', ''ทาสีภายใน'', 100, ''ตร.ม.'', 80, 120),\n]\n\nfor category, no, desc, qty, unit, mat, lab in items:\n    subprocess.run([\n        ''python'', ''boq_helper.py'', ''add'',\n        ''renovation.xlsx'', category, no, desc,\n        str(qty), unit, str(mat), str(lab)\n    ], capture_output=True, text=True)\n\n# 3. Recalculate formulas\nresult = subprocess.run([\n    ''python'', ''recalc.py'', ''renovation.xlsx''\n], capture_output=True, text=True)\nprint(json.loads(result.stdout))\n```\n\n## Using Python Directly (Alternative Method)\n\nFor more flexibility, directly use openpyxl with the xlsx skill patterns:\n\n```python\nfrom openpyxl import load_workbook\n\nwb = load_workbook(''renovation.xlsx'')\nws = wb.active\n\n# Add custom item to specific row\nrow = 8  # Example row number\nws[f''A{row}''] = ''1.2''\nws[f''B{row}''] = ''งานขุดดิน''\nws[f''C{row}''] = 15.5\nws[f''D{row}''] = ''ลบ.ม.''\nws[f''E{row}''] = 200\nws[f''F{row}''] = f''=C{row}*E{row}''  # Auto-calculate\nws[f''G{row}''] = 300\nws[f''H{row}''] = f''=C{row}*G{row}''  # Auto-calculate\nws[f''I{row}''] = f''=F{row}+H{row}''  # Total\nws[f''J{row}''] = ''รวมค่าขนย้ายดิน''\n\nwb.save(''renovation.xlsx'')\n```\n\nThen recalculate:\n```bash\npython recalc.py renovation.xlsx\n```\n\n## Important Notes\n\n### Formula Usage\n- **ALWAYS use Excel formulas** instead of calculating in Python\n- Formulas ensure the BOQ remains dynamic and updateable\n- Let Excel calculate: ราคารวมวัสดุ, ค่าแรงรวม, รวมราคา\n\n### Category Limits\n- Each category can hold up to 3 items by default\n- To add more items, modify the BOQ structure or use Python directly\n\n### Recalculation\n- **MANDATORY**: Always run `recalc.py` after creating or modifying BOQ\n- This ensures all formulas are calculated correctly\n- Check the JSON output for any errors\n\n### Thai Language Support\n- All output uses Thai language\n- File names can be in Thai or English\n- Category names must match exactly (including Thai characters)\n\n### Error Handling\n- Scripts return JSON output for easy parsing\n- Check `status` field: \"success\" or \"error\"\n- Error messages are in Thai for clarity\n\n## Bundled Scripts\n\n- `boq_helper.py` - Main BOQ creation and management script\n- `recalc.py` - Formula recalculation script\n- `validate_boq.py` - Validation script for checking budget proportions\n- `BEST_PRACTICES.md` - Guidelines for creating proper BOQ\n\n## Best Practices\n\nสัดส่วนงบประมาณมาตรฐาน (สำหรับบ้านพักอาศัย):\n- **งานเตรียมการ:** ≤ 5%\n- **งานโครงสร้าง:** 28-32% (เป้าหมาย 30%)\n- **งานสถาปัตยกรรม:** 38-42% (เป้าหมาย 40%)\n- **งานระบบไฟฟ้า:** 10-14% (เป้าหมาย 12%)\n- **งานระบบสุขาภิบาล:** 12-16% (เป้าหมาย 13%)\n\nอ่านรายละเอียดเพิ่มเติมใน `BEST_PRACTICES.md`\n\n## Examples\n\nตัวอย่างการใช้งานอยู่ที่ `examples/` folder:\n\n```bash\n# สร้าง BOQ บ้านพักอาศัย 2 ชั้น (ตาม Best Practices)\npython examples/create_house_boq.py\n```\n\nไฟล์ที่สร้างจะอยู่ที่: `workspace/boq_examples/`\n\n## Validation\n\nตรวจสอบสัดส่วนงบประมาณ:\n\n```python\nfrom validate_boq import validate_from_data\n\nboq_totals = {\n    \"งานเตรียมการ\": 186916,\n    \"งานโครงสร้าง\": 1122092,\n    \"งานสถาปัตยกรรม\": 1495327,\n    \"งานระบบไฟฟ้า\": 448598,\n    \"งานระบบสุขาภิบาล\": 485981\n}\n\nvalidate_from_data(boq_totals)\n```\n"},"lastSynced":"2026-03-08T02:03:36.999Z","agentAnalysis":{"suitability":{"en":"Perfect for Construction Planning Agents needing automated bill of quantities management and cost estimation using Excel.","zh":"适合需要自动化施工计量和使用 Excel 进行成本估算的施工规划代理","ja":"Construction Planning Agents が自動化された請求書の管理と Excel を使用したコストの見積もりが必要な場合に適しています","ko":"건설 계획 에이전트가 자동화된 청구서 관리와 Excel을 사용한 비용 추정에 적합합니다","es":"Perfecto para Agentes de Planificación de Construcción que necesitan una gestión automatizada de la lista de cantidades y estimación de costos utilizando Excel.","fr":"Parfait pour les Agents de Planification de Construction ayant besoin d''une gestion automatisée de la liste des quantités et d''estimation de coûts en utilisant Excel.","de":"Perfekt für Construction Planning Agents, die eine automatisierte Verwaltung der Mengenliste und Kostenschätzung mit Excel benötigen.","pt":"Perfeito para Agentes de Planejamento de Construção que precisam de gerenciamento automatizado de lista de quantidades e estimativa de custos usando Excel.","ru":"Идеально подходит для агентов по планированию строительства, которым требуется автоматизированное управление перечнем количеств и оценка затрат с помощью Excel.","ar":"مثالي لعمليات وكالات التخطيط الإنشائي التي تحتاج إلى إدارة قائمة الكميات وتقدير التكاليف أتوماتيكيًا باستخدام برنامج إكسل."},"recommendation":{"en":"Empowers agents to efficiently manage construction project costs by automating bill of quantities generation, utilizing Excel for data analysis and project planning, and organizing output files in a structured workspace folder.","zh":"赋予代理人高效管理施工项目成本的能力，通过自动化请购单的生成，使用 Excel 进行数据分析和项目规划，并将输出文件组织到结构化的工作空间文件夹中","ja":"エージェントが建設プロジェクトのコストを効率的に管理できるようにし、請求書の自動生成、Excel を使用したデータ分析とプロジェクト計画、および構造化されたワークスペース フォルダへの出力ファイルの整理を行う","ko":"에이전트가 건설 프로젝트 비용을 효율적으로 관리할 수 있도록 하며, 청구서의 자동 생성, Excel을 사용한 데이터 분석 및 프로젝트 계획, 및 구조화된 작업 공간 폴더への 출력 파일의 조직화","es":"Habilita a los agentes a gestionar eficientemente los costos de los proyectos de construcción mediante la automatización de la generación de la lista de cantidades, utilizando Excel para el análisis de datos y la planificación de proyectos, y organizando los archivos de salida en una carpeta de espacio de trabajo estructurada.","fr":"Permet aux agents de gérer efficacement les coûts des projets de construction en automatisant la génération de la liste des quantités, en utilisant Excel pour l''analyse de données et la planification de projets, et en organisant les fichiers de sortie dans un dossier de workspace structuré.","de":"Ermächtigt die Agenten, die Kosten von Bauprojekten effizient zu verwalten, indem sie die Erstellung der Mengenliste automatisieren, Excel für Datenanalyse und Projektplanung nutzen und die Ausgabedateien in einem strukturierten Arbeitsbereichsordner organisieren.","pt":"Habilita os agentes a gerenciar eficientemente os custos dos projetos de construção, automatizando a geração da lista de quantidades, utilizando o Excel para análise de dados e planejamento de projetos e organizando os arquivos de saída em uma pasta de espaço de trabalho estruturada.","ru":"Наделяет агентов возможностью эффективно управлять затратами на строительные проекты, автоматизируя генерацию перечня количеств, используя Excel для анализа данных и планирования проектов, а также организуя выходные файлы в структурированной папке рабочего пространства.","ar":"تمكّن الوكالات من إدارة تكاليف مشاريع البناء بفعالية من خلال أتمتة إنشاء قائمة الكميات، واستخدام برنامج إكسل لتحليل البيانات وتخطيط المشاريع، وتنظيم ملفات الإخراج في مجلد مساحات عمل منظم."},"useCases":{"en":["Automating bill of quantities creation for construction projects","Generating detailed cost estimates using Excel","Organizing project files into standardized workspace folders"],"zh":["为建设项目自动创建请购单","使用 Excel 生成详细的成本估算","将项目文件组织到标准化的工作空间文件夹中"],"ja":["建設プロジェクトの請求書の自動作成","Excel を使用した詳細なコスト見積りの生成","プロジェクト ファイルを標準化されたワークスペース フォルダに整理する"],"ko":["건설 프로젝트의 청구서 자동 생성","Excel을 사용한 상세한 비용 추정 생성","프로젝트 파일을 표준화된 작업 공간 폴더로 조직화"],"es":["Automatización de la creación de la lista de cantidades para proyectos de construcción","Generación de estimaciones de costos detalladas utilizando Excel","Organización de archivos de proyectos en carpetas de espacio de trabajo estandarizadas"],"fr":["Automatisation de la création de la liste des quantités pour les projets de construction","Génération d''estimations de coûts détaillées en utilisant Excel","Organisation des fichiers de projets dans des dossiers de workspace standardisés"],"de":["Automatisierung der Erstellung der Mengenliste für Bauprojekte","Erzeugung detaillierter Kostenschätzungen unter Verwendung von Excel","Organisation von Projektdateien in standardisierten Arbeitsbereichsordnern"],"pt":["Automatizar a criação da lista de quantidades para projetos de construção","Gerar estimativas de custos detalhadas usando Excel","Organizar arquivos de projeto em pastas de espaço de trabalho padronizadas"],"ru":["Автоматизировать создание перечня количеств для строительных проектов","Генерировать подробные сметы затрат с помощью Excel","Организовывать файлы проекта в стандартизированных папках рабочего пространства"],"ar":["أتمتة إنشاء قائمة الكميات لمشاريع البناء","توليد تقديرات دقيقة للتكاليف باستخدام برنامج إكسل","تنظيم ملفات المشروع في مجلدات مساحات عمل معيارية"]},"limitations":{"en":["Requires Excel for data analysis and cost estimation","Output files are stored in a specific workspace folder structure","Limited to construction project planning and bill of quantities management"],"zh":["需要 Excel 进行数据分析和成本估算","输出文件存储在特定的工作空间文件夹结构中","仅限于建设项目规划和请购单管理"],"ja":["データ分析とコスト見積りに Excel が必要","出力ファイルは特定のワークスペース フォルダ構造に保存される","建設プロジェクトの計画と請求書の管理に限定される"],"ko":["데이터 분석 및 비용 추정에 Excel이 필요","출력 파일은 특정 작업 공간 폴더 구조에 저장","건설 프로젝트 계획 및 청구서 관리에만 제한"],"es":["Requiere Excel para el análisis de datos y la estimación de costos","Los archivos de salida se almacenan en una estructura de carpeta de espacio de trabajo específica","Limitado a la planificación de proyectos de construcción y gestión de la lista de cantidades"],"fr":["Nécessite Excel pour l''analyse de données et l''estimation de coûts","Les fichiers de sortie sont stockés dans une structure de dossier de workspace spécifique","Limité à la planification de projets de construction et à la gestion de la liste des quantités"],"de":["Benötigt Excel für Datenanalyse und Kostenschätzung","Die Ausgabedateien werden in einer bestimmten Arbeitsbereichsordnerstruktur gespeichert","Begrenzt auf die Planung von Bauprojekten und die Verwaltung der Mengenliste"],"pt":["Requer Excel para análise de dados e estimativa de custos","Arquivos de saída são armazenados em uma estrutura de pasta de espaço de trabalho específica","Limitado ao planejamento de projetos de construção e gerenciamento da lista de quantidades"],"ru":["Требует Excel для анализа данных и оценки затрат","Выходные файлы хранятся в конкретной структуре папки рабочего пространства","Ограничен планированием строительных проектов и управлением перечнем количеств"],"ar":["يتطلب برنامج إكسل لتحليل البيانات وتقدير التكاليف","تخزين ملفات الإخراج في هيكل مجلد مساحات عمل محدد","محدود بتخطيط مشاريع البناء وإدارة قائمة الكميات"]},"version":4},"contentHash":"91bd4239e38bc74f5eb2d2954d0d62ad7b8ca906965ec7e3b96ff8122b0621d5","qualityScore":51}');
