INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('POBIM/Claude-Skill-Teach/boq', 'boq', 'POBIM', 'Claude-Skill-Teach', 'community', 'boq POBIM Claude-Skill-Teach community The BOQ skill helps developers automate bill of quantities management for construction projects, utilizing Excel for efficient cost estimation and project planning. BOQ 技能用于创建和管理建筑成本估算，支持 5 个主要工作类别，包括准备、结构、建筑、安装和装修 BOQ スキルは、建設費用見積もりを作成および管理するために使用され、5 つの主な作業カテゴリ（準備、構造、建築、インストール、フィニッシュ）をサポートします BOQ 스킬은 건설 비용估算을 생성하고 관리하는 데 사용되며 5개의 주요 작업 카테고리(준비, 구조, 건축, 설치, 마감)를 지원합니다 El skill BOQ permite la creación y gestión de bill of quantities para la construcción, utilizando Excel para organizar y calcular costos Le skill BOQ permet la création et la gestion de bill of quantities pour la construction, en utilisant Excel pour organiser et calculer les coûts Das BOQ-Skill ermöglicht die Erstellung und Verwaltung von Baubillen für die Bauwirtschaft, unter Verwendung von Excel zur Organisation und Kalkulation von Kosten A ferramenta BOQ é uma solução para criar orçamentos de construção precisos com o Excel. Ela oferece 5 categorias de trabalho principais para ajudar a gerenciar seus projetos de construção. ИИ Агент BOQ - это решение для создания точных смет строительных расходов с помощью Excel. Он предлагает 5 основных категорий работ для помощи в управлении вашими строительными проектами. أداة BOQ هي حل لإنشاء تقديرات دقيقة للتكاليف الإنشائية باستخدام Excel. توفر 5 فئات عمل رئيسية لمساعدتك في إدارة مشاريع البناء الخاصة بك. how to use boq boq setup guide bill of quantities management boq alternative boq vs excel construction cost estimation boq install what is boq BOQ 技能 建筑成本估算 Excel 输出 建设费用见估 BOQ 创建 BOQ 管理 AI エージェント AI 工具 Generates BOQ files in Excel format Organizes output files in a dedicated workspace folder Follows best practices outlined in BEST_PRACTICES.md Categorizes construction work into 5 standard categories Supports detailed cost estimation for construction projects boq is a bill of quantities management skill that enables automated generation and management of construction cost estimates using Excel.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Xe/site/blogpost-creator', 'community', 'Xe', 'site', 'Xe/site', 'blogpost-creator', 0, 0, 51, '2026-03-08T01:57:15.346Z', '2026-03-08T02:03:38.536Z', '1f8d5e5635d9715c7757a04c01ca192a1a587e8d398ff2220c5503e660b59e1b', '{"id":"Xe/site/blogpost-creator","name":"blogpost-creator","description":{"en":"The blogpost-creator skill generates new blog posts for Xe''s site using the hydrate command, prompting for post type, title, description, and link URL. It benefits developers and content creators looking to automate blog post creation.","zh":"博客文章创建工具是用于生成XEIASO.NET新博客文章的技能，支持多种文章类型，包括博客、链接文章、笔记、演讲和Xecast","ja":"ブログポスト作成ツールは、XEIASO.NETの新しいブログ記事を生成するスキルです。複数の記事タイプをサポートし、ブログ、リンク記事、ノート、トーク、Xecastなどが含まれます","ko":"블로그 게시물 생성 도구는 XEIASO.NET의 새로운 블로그 게시물을 생성하는 스킬로, 여러 가지 게시물 유형을 지원하며 블로그, 링크 게시물, 노트, 토크 및 Xecast 등이 포함됩니다","es":"El creador de publicaciones de blog es una herramienta para generar contenido para https://xeiaso.net utilizando el comando hydrate.","fr":"Le créateur de billets de blog est un outil pour générer du contenu pour https://xeiaso.net en utilisant la commande hydrate.","de":"Der Blog-Beitrag-Ersteller ist ein Tool, um Inhalte für https://xeiaso.net mit dem Befehl hydrate zu generieren.","pt":"O Blog Post Creator é uma ferramenta de código aberto que permite criar novos posts de blog para o site Xe''s usando o comando hydrate.","ru":"Blog Post Creator - это инструмент с открытым исходным кодом, который позволяет создавать новые блог-посты для сайта Xe''s с помощью команды hydrate.","ar":"Blog Post Creator هو أداة مفتوحة المصدر تسمح بإنشاء منشورات مدونة جديدة لsite Xe''s باستخدام أمر hydrate."},"seo":{"title":{"en":"blogpost-creator: Setup Guide for AI Agents | AI Agent Skill","zh":"博客文章创建工具：XEIASO.NET 前端/后端代码设置指南","ja":"ブログポスト作成ツール：XEIASO.NET フロントエンド/バックエンドコード設定ガイド","ko":"블로그 게시물 생성 도구: XEIASO.NET 프