INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Xe/site/blogpost-creator', 'blogpost-creator', 'Xe', 'site', 'community', 'blogpost-creator Xe site community The blogpost-creator skill generates new blog posts for Xe''s site using the hydrate command, prompting for post type, title, description, and link URL. It benefits developers and content creators looking to automate blog post creation. 博客文章创建工具是用于生成XEIASO.NET新博客文章的技能，支持多种文章类型，包括博客、链接文章、笔记、演讲和Xecast ブログポスト作成ツールは、XEIASO.NETの新しいブログ記事を生成するスキルです。複数の記事タイプをサポートし、ブログ、リンク記事、ノート、トーク、Xecastなどが含まれます 블로그 게시물 생성 도구는 XEIASO.NET의 새로운 블로그 게시물을 생성하는 스킬로, 여러 가지 게시물 유형을 지원하며 블로그, 링크 게시물, 노트, 토크 및 Xecast 등이 포함됩니다 El creador de publicaciones de blog es una herramienta para generar contenido para https://xeiaso.net utilizando el comando hydrate. Le créateur de billets de blog est un outil pour générer du contenu pour https://xeiaso.net en utilisant la commande hydrate. Der Blog-Beitrag-Ersteller ist ein Tool, um Inhalte für https://xeiaso.net mit dem Befehl hydrate zu generieren. O Blog Post Creator é uma ferramenta de código aberto que permite criar novos posts de blog para o site Xe''s usando o comando hydrate. Blog Post Creator - это инструмент с открытым исходным кодом, который позволяет создавать новые блог-посты для сайта Xe''s с помощью команды hydrate. Blog Post Creator هو أداة مفتوحة المصدر تسمح بإنشاء منشورات مدونة جديدة لsite Xe''s باستخدام أمر hydrate. how to use blogpost-creator blogpost-creator setup guide blogpost-creator vs other AI agents blogpost-creator install what is blogpost-creator blogpost-creator alternative hydrate command tutorial Xe''s site blog post creation 博客文章创建工具 XEIASO.NET AI工具 hydrate命令 博客文章生成 链接文章创建 笔记生成 演讲创建 Xecast生成 Creates new blog posts using the hydrate command Supports multiple post types, including blog, linkpost, note, talk, and xecast Prompts for title, description, and link URL, with auto-fetch capabilities for linkposts Automates blog post creation for Xe''s site Uses the SKILL.md file for technical content and usage guidelines blogpost-creator is a skill that automates the creation of new blog posts for Xe''s site using the hydrate command, supporting various post types and auto-fetching capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('seedprod/openclaw-prompts-and-skills/weather', 'community', 'seedprod', 'openclaw-prompts-and-skills', 'seedprod/openclaw-prompts-and-skills', 'weather', 0, 0, 51, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.451Z', '849ef79e4e11197c313c985832ab6c9101c7b61318a4e46ac50b3a9461368bff', '{"id":"seedprod/openclaw-prompts-and-skills/weather","name":"weather","description":{"en":"The weather skill provides Telegram bot integration with headless Claude Code, utilizing wttr.in for precise weather forecasts. Developers can leverage this skill for accurate climate data.","zh":"本文介绍如何使用wttr.in和Telegram bot创建天气API，实现获取天气预报和条件的功能","ja":"wttr.inとAIエージェントを使用してWeather APIを作成し、天気予報と条件を取得する方法を解説します","ko":"wttr.in과 Telegram bot을 사용하여 날씨 API를 생성하고 날씨 예보 및 조건을 얻는 방법을 설명합니다","es":"Este bot de Telegram utiliza wttr.in para proporcionar información climática. Se puede configurar para obtener el clima actual o el pronóstico completo.","fr":"Ce bot Telegram utilise wttr.in pour fournir des informations météorologiques. Il peut être configuré pour obtenir les conditions météorologiques actuelles ou la prévision complète.","de":"Dieser Telegram-Bot nutzt wttr.in, um Wetterinformationen bereitzustellen. Er kann konfiguriert werden, um das aktuelle Wetter oder die vollständige Vorhersage zu erhalten.","pt":"O agente de previsão do tempo é um Telegram bot que se comunica com o Claude Code headless, oferecendo previsões meteorológicas gratuitas sem necessidade de chaves de API","ru":"ИИ агент погоды - это Telegram бот, который общается с Claude Code headless, предоставляя бесплатные прогнозы погоды без необходимости API ключей","ar":"عامل الطقس هو بوت تلجرام يتحدث إلى كلود كود بدون رأس، يقدم تنبؤات جوية مجانية بدون مفتاح واجهة برمجة التطبيقات"},"seo":{"title":{"en":"Weather: Setup Guide for AI Agents | AI Agent Skill","zh":"天气API集成指南：使用wttr.in和Telegram bot","ja":"Weather APIのセットアップガイド：wttr.inとAIエージェントの活用","ko":"날씨 API 통합 가이드: wttr.in과 Telegram bot을 사용하여","es":"Guía de configuración del clima con wttr.in y Telegram","fr":"Guide de mise en place de la météo avec wttr.in et Telegram","de":"Wetter-Setup-Anleitung mit wttr.in und Telegram","pt":"Guia de Configuração do Agente de Previsão do Tempo","ru":"ИИ Агент Погоды: Руководство по Настройке","ar":"دليل إعداد عامل الطقس"},"description":{"en":"Discover how to integrate weather forecasts into your AI agent with our step-by-step guide and unlock precise climate data from wttr.in","zh":"了解如何使用wttr.in和Telegram bot创建天气API，获取最新的天气预报和条件","ja":"wttr.inとAIエージェントを使用してWeather APIを作成し、最新の天気予報と条件を取得する方法を学びましょう","ko":"wttr.in과 Telegram bot을 사용하여 날씨 API를 생성하고 최신 날씨 예보 및 조건을 얻는 방법을 알아보세요","es":"Aprende a crear un bot de Telegram que consulta el clima con wttr.in sin necesidad de claves API","fr":"Découvrez comment créer un bot Telegram qui consulte la météo avec wttr.in sans clés API","de":"Erfahren Sie, wie Sie einen Telegram-Bot erstellen, der mit wttr.in das Wetter abruft, ohne API-Schlüssel","pt":"Aprenda a configurar o agente de previsão do tempo com o Telegram bot e o Claude Code headless, sem necessidade de chaves de API","ru":"Узнайте, как настроить ИИ агент погоды с помощью Telegram бота и Claude Code headless, без необходимости API ключей","ar":"تعلم كيفية تعيين عامل الطقس باستخدام بوت تلجرام و كلود كود بدون مفتاح واجهة برمجة التطبيقات"},"definition":{"en":"Weather is a Telegram bot skill that retrieves and displays current weather conditions and forecasts from wttr.in","zh":"天气API是用于获取天气预报和条件的应用程序接口，使用wttr.in和Telegram bot可以实现此功能","ja":"Weather APIは、天気予報と条件を取得するためのアプリケーション・インターフェイスです。wttr.inとAIエージェントを使用して実現できます","ko":"날씨 API는 날씨 예보와 조건을 얻기 위한 응용 프로그램 인터페이스입니다. wttr.in과 Telegram bot을 사용하여 구현할 수 있습니다","es":"Un bot de clima es un agente de inteligencia artificial que proporciona información climática a través de una interfaz de usuario","fr":"Un bot météo est un agent d''intelligence artificielle qui fournit des informations météorologiques via une interface utilisateur","de":"Ein Wetterbot ist ein künstlicher Intelligenzagent, der Wetterinformationen über eine Benutzeroberfläche bereitstellt","pt":"O que é um agente de previsão do tempo? É um sistema que fornece previsões meteorológicas gratuitas por meio de um Telegram bot","ru":"Что такое ИИ агент погоды? Это система, предоставляющая бесплатные прогнозы погоды через Telegram бота","ar":"ما هو عامل الطقس؟ هو نظام يقدم تنبؤات جوية مجانية من خلال بوت تلجرام"},"features":{"en":["Utilizes wttr.in API for primary weather data","Supports compact format for quick weather summaries","Generates full forecast output with temperature, humidity, and wind details","Allows URL-encoded spaces for city names, such as New+York","Accepts airport codes for location-specific weather data"],"zh":["使用wttr.in获取天气预报和条件","支持多种格式，包括简洁和详细格式","可以使用URL编码和机场代码获取特定位置的天气信息","支持多种技术，包括CLI和Telegram bot","无需API密钥即可使用"],"ja":["wttr.inを使用して天気予報と条件を取得","複数の形式をサポート、包括的かつ詳細な形式","URLエンコードと空港コードを使用して特定の場所の天気情報を取得","CLIとAIエージェントを含む複数のテクノロジーをサポート","APIキーなしで使用できます"],"ko":["wttr.in을 사용하여 날씨 예보와 조건을 얻음","다양한 형식을 지원, 간결하고详细한 형식","URL 인코딩과 공항 코드를 사용하여 특정 위치의 날씨 정보를 얻음","CLI와 Telegram bot을 포함한 다양한 기술을 지원","API 키 없이 사용할 수 있음"],"es":["Soporte para wttr.in","Consulta del clima actual","Pronóstico completo del clima","Formatos de salida personalizables","Sin necesidad de claves API"],"fr":["Prise en charge de wttr.in","Consultation des conditions météorologiques actuelles","Prévision météorologique complète","Formats de sortie personnalisables","Pas besoin de clés API"],"de":["Unterstützung für wttr.in","Abruf des aktuellen Wetters","Vollständige Wettervorhersage","Anpassbare Ausgabeformate","Keine API-Schlüssel erforderlich"],"pt":["Uso do serviço wttr.in para previsões meteorológicas","Suporte a formatos compactos e completos de previsão","Opção de uso de códigos de aeroporto para previsões","URL-encode de espaços para nomes de localidades","Suporte a várias opções de formatação de saída"],"ru":["Использование сервиса wttr.in для прогнозов погоды","Поддержка компактных и полных форматов прогноза","Возможность использования кодов аэропортов для прогнозов","URL-кодирование пробелов для названий мест","Поддержка нескольких вариантов форматирования вывода"],"ar":["استخدام خدمة wttr.in للتنبؤات الجوية","دعم صيغ مدمجة و كاملة للتنبؤ","خيار استخدام رموز المطارات للتنبؤات","ترميز URL للفراغات في أسماء المناطق","دعم عدة خيارات لتنسيق الإخراج"]},"keywords":{"en":["how to use wttr.in","weather API alternative","setup weather skill","weather vs darksky","wttr.in API documentation","install weather skill for Telegram"],"zh":["天气API","wttr.in","Telegram bot","天气预报","条件","CLI","API密钥","URL编码","机场代码"],"ja":["Weather API","wttr.in","AIエージェント","天気予報","条件","CLI","APIキー","URLエンコード","空港コード"],"ko":["날씨 API","wttr.in","Telegram bot","날씨 예보","조건","CLI","API 키","URL 인코딩","공항 코드"],"es":["bot de clima","wttr.in","Telegram bot","clima actual","pronóstico del clima","desarrollo de bots","inteligencia artificial","agentes de IA"],"fr":["bot météo","wttr.in","bot Telegram","météo actuelle","prévision météorologique","développement de bots","intelligence artificielle","agents d''IA"],"de":["Wetterbot","wttr.in","Telegram-Bot","aktuelles Wetter","Wettervorhersage","Bot-Entwicklung","künstliche Intelligenz","KI-Agents"],"pt":["agente de previsão do tempo","Telegram bot","Claude Code headless","previsão meteorológica gratuita","wttr.in","formatos de previsão","códigos de aeroporto","URL-encode"],"ru":["ИИ агент погоды","Telegram бот","Claude Code headless","бесплатный прогноз погоды","wttr.in","форматы прогноза","коды аэропортов","URL-кодирование"],"ar":["عامل الطقس","بوت تلجرام","كلود كود بدون رأس","تنبؤ جوية مجاني","wttr.in","صيغ التنبؤ","رموز المطارات","ترميز URL"]}},"owner":"seedprod","repo":"openclaw-prompts-and-skills","repoPath":"seedprod/openclaw-prompts-and-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"weather","description":"Get current weather and forecasts (no API key required).","bodyPreview":"# Weather\n\nTwo free services, no API keys needed.\n\n## wttr.in (primary)\n\nQuick one-liner:\n```bash\ncurl -s \"wttr.in/London?format=3\"\n# Output: London: ⛅️ +8°C\n```\n\nCompact format:\n```bash\ncurl -s \"wttr.in/London?format=%l:+%c+%t+%h+%w\"\n# Output: London: ⛅️ +8°C 71% ↙5km/h\n```\n\nFull forecast:\n```bash\ncurl -s \"wttr.in/London?T\"\n```\n\nFormat codes: `%c` condition · `%t` temp · `%h` humidity · `%w` wind · `%l` location · `%m` moon\n\nTips:\n- URL-encode spaces: `wttr.in/New+York`\n- Airport codes: `wttr.i","body":"# Weather\n\nTwo free services, no API keys needed.\n\n## wttr.in (primary)\n\nQuick one-liner:\n```bash\ncurl -s \"wttr.in/London?format=3\"\n# Output: London: ⛅️ +8°C\n```\n\nCompact format:\n```bash\ncurl -s \"wttr.in/London?format=%l:+%c+%t+%h+%w\"\n# Output: London: ⛅️ +8°C 71% ↙5km/h\n```\n\nFull forecast:\n```bash\ncurl -s \"wttr.in/London?T\"\n```\n\nFormat codes: `%c` condition · `%t` temp · `%h` humidity · `%w` wind · `%l` location · `%m` moon\n\nTips:\n- URL-encode spaces: `wttr.in/New+York`\n- Airport codes: `wttr.in/JFK`\n- Units: `?m` (metric) `?u` (USCS)\n- Today only: `?1` · Current only: `?0`\n- PNG: `curl -s \"wttr.in/Berlin.png\" -o /tmp/weather.png`\n\n## Open-Meteo (fallback, JSON)\n\nFree, no key, good for programmatic use:\n```bash\ncurl -s \"https://api.open-meteo.com/v1/forecast?latitude=51.5&longitude=-0.12&current_weather=true\"\n```\n\nFind coordinates for a city, then query. Returns JSON with temp, windspeed, weathercode.\n\nDocs: https://open-meteo.com/en/docs\n"},"lastSynced":"2026-03-08T02:03:39.451Z","agentAnalysis":{"suitability":{"en":"Ideal for Location-Based Agents requiring precise weather forecasts and climate data integration.","zh":"适用于需要精确天气预报和气候数据集成的基于位置的代理。","ja":"位置ベースのエージェントが正確な天気予報と気候データの統合を必要とする場合に最適です。","ko":"정확한 날씨 예보와 기후 데이터 통합이 필요한 위치 기반 에이전트에 적합합니다.","es":"Ideal para agentes basados en ubicación que requieren previsiones meteorológicas precisas e integración de datos climáticos.","fr":"Idéal pour les agents basés sur l''emplacement nécessitant des prévisions météorologiques précises et une intégration de données climatiques.","de":"Ideal für standortbasierte Agenten, die präzise Wettervorhersagen und Klimadateneinbindung erfordern.","pt":"Ideal para Agentes Baseados em Localização que requerem previsões meteorológicas precisas e integração de dados climáticos.","ru":"Идеально для агентов, основанных на местоположении, требующих точных прогнозов погоды и интеграции климатических данных.","ar":"مثالي لوكلاء الموقع الذين يحتاجون إلى توقعات جوية دقيقة وتكامل البيانات المناخية."},"recommendation":{"en":"Empowers agents to fetch accurate weather conditions using wttr.in, providing compact or full forecasts with details like temperature, humidity, wind, and moon phase, all through simple curl commands and URL-encoded queries.","zh":"使代理能够使用wttr.in获取准确的天气条件，提供紧凑或全面的预报，包括温度、湿度、风和月相等详细信息，所有这些都通过简单的curl命令和URL编码查询。","ja":"wttr.inを使用して、エージェントが正確な天気条件を取得できるようにし、温度、湿度、風、月相などの詳細を含むコンパクトまたはフルの予報を提供します。すべてこれらはシンプルなcurlコマンドとURLエンコードされたクエリを通じて実現されます。","ko":"에이전트가 wttr.in을 사용하여 정확한 날씨 조건을 가져올 수 있도록 하여, 온도, 습도, 바람, 월상 등과 같은 상세 정보를 포함한 컴팩트 또는 전체 예보를 제공합니다. 모든 것은 단순한 curl 명령과 URL 인코딩된 쿼리를 통해 제공됩니다.","es":"Habilita a los agentes a obtener condiciones meteorológicas precisas utilizando wttr.in, proporcionando previsiones compactas o completas con detalles como temperatura, humedad, viento y fase lunar, todo a través de simples comandos curl y consultas con URL codificadas.","fr":"Permet aux agents d''obtenir des conditions météorologiques précises en utilisant wttr.in, en fournissant des prévisions compactes ou complètes avec des détails tels que la température, l''humidité, le vent et la phase lunaire, le tout via de simples commandes curl et des requêtes avec URL codées.","de":"Ermächtigt Agenten, genaue Wetterbedingungen mit wttr.in abzurufen, wobei kompakten oder vollständigen Vorhersagen mit Details wie Temperatur, Feuchtigkeit, Wind und Mondphase bereitgestellt werden, und zwar über einfache curl-Befehle und URL-codierte Abfragen.","pt":"Habilita os agentes a buscar condições meteorológicas precisas usando wttr.in, fornecendo previsões compactas ou completas com detalhes como temperatura, umidade, vento e fase lunar, tudo por meio de comandos curl simples e consultas codificadas em URL.","ru":"Наделяет агентов возможностью получать точные погодные условия с помощью wttr.in, предоставляя компактные или полные прогнозы с деталями, такими как температура, влажность, ветер и фаза луны, все через простые команды curl и URL-запросы.","ar":"يمنح الوكلاء القدرة على استرداد الظروف الجوية الدقيقة باستخدام wttr.in، 提供 توقعات مناخية مضغوطة أو كاملة بالتفاصيل مثل درجة الحرارة والرطوبة والرياح ومرحلة القمر، وكل ذلك من خلال أوامر curl بسيطة واستفسارات مشفرة في URL."},"useCases":{"en":["Fetching current weather conditions for specific locations","Generating full weather forecasts for travel planning","Integrating climate data into location-based services"],"zh":["为特定位置获取当前天气条件","为旅行规划生成全面的天气预报","将气候数据集成到基于位置的服务中"],"ja":["特定の位置の現在の天気条件を取得する","旅行計画のための全面的天気予報を生成する","気候データを位置ベースのサービスに統合する"],"ko":["특정 위치의 현재 날씨 조건을 가져오는 것","여행 계획을 위한 전체 날씨 예보를 생성하는 것","기후 데이터를 위치 기반 서비스에 통합하는 것"],"es":["Obtener las condiciones meteorológicas actuales para ubicaciones específicas","Generar previsiones meteorológicas completas para la planificación de viajes","Integrar datos climáticos en servicios basados en ubicación"],"fr":["Récupérer les conditions météorologiques actuelles pour des emplacements spécifiques","Générer des prévisions météorologiques complètes pour la planification de voyages","Intégrer des données climatiques dans des services basés sur l''emplacement"],"de":["Abrufen der aktuellen Wetterbedingungen für bestimmte Standorte","Erstellen von vollständigen Wettervorhersagen für die Reiseplanung","Einbindung von Klimadaten in standortbasierte Dienste"],"pt":["Obter condições meteorológicas atuais para locais específicos","Gerar previsões meteorológicas completas para planejamento de viagens","Integrar dados climáticos em serviços baseados em localização"],"ru":["Получение текущих погодных условий для конкретных местоположений","Генерация полных погодных прогнозов для планирования путешествий","Интеграция климатических данных в сервисы, основанные на местоположении"],"ar":["استرداد الظروف الجوية الحالية للمواقع المحددة","توليد توقعات جوية كاملة للتخطيط للسفر","دمج البيانات المناخية في الخدمات المعتمدة على الموقع"]},"limitations":{"en":["Dependent on wttr.in service availability","No support for paid API keys or custom services beyond wttr.in"],"zh":["依赖于wttr.in服务的可用性","不支持付费API密钥或wttr.in之外的自定义服务"],"ja":["wttr.inサービスの可用性に依存する","有料APIキーまたはwttr.in以外のカスタムサービスをサポートしない"],"ko":["wttr.in 서비스의 가용성에 의존함","유료 API 키 또는 wttr.in 외의 사용자 지정 서비스를 지원하지 않음"],"es":["Dependiente de la disponibilidad del servicio wttr.in","No hay soporte para claves de API de pago o servicios personalizados más allá de wttr.in"],"fr":["Dépendante de la disponibilité du service wttr.in","Aucun support pour les clés d''API payantes ou les services personnalisés au-delà de wttr.in"],"de":["Abhängig von der Verfügbarkeit des wttr.in-Dienstes","Keine Unterstützung für kostenpflichtige API-Schlüssel oder benutzerdefinierte Dienste jenseits von wttr.in"],"pt":["Dependente da disponibilidade do serviço wttr.in","Sem suporte a chaves de API pagas ou serviços personalizados além do wttr.in"],"ru":["Зависимость от доступности сервиса wttr.in","Отсутствие поддержки платных ключей API или пользовательских сервисов, кроме wttr.in"],"ar":["التعرض لتوافر خدمة wttr.in","لا دعم للأساليب المدفوعة API أو الخدمات المخصصة بخلاف wttr.in"]},"version":4},"contentHash":"849ef79e4e11197c313c985832ab6c9101c7b61318a4e46ac50b3a9461368bff","qualityScore":51}');
