INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('seedprod/openclaw-prompts-and-skills/weather', 'weather', 'seedprod', 'openclaw-prompts-and-skills', 'community', 'weather seedprod openclaw-prompts-and-skills community The weather skill provides Telegram bot integration with headless Claude Code, utilizing wttr.in for precise weather forecasts. Developers can leverage this skill for accurate climate data. 本文介绍如何使用wttr.in和Telegram bot创建天气API，实现获取天气预报和条件的功能 wttr.inとAIエージェントを使用してWeather APIを作成し、天気予報と条件を取得する方法を解説します wttr.in과 Telegram bot을 사용하여 날씨 API를 생성하고 날씨 예보 및 조건을 얻는 방법을 설명합니다 Este bot de Telegram utiliza wttr.in para proporcionar información climática. Se puede configurar para obtener el clima actual o el pronóstico completo. Ce bot Telegram utilise wttr.in pour fournir des informations météorologiques. Il peut être configuré pour obtenir les conditions météorologiques actuelles ou la prévision complète. Dieser Telegram-Bot nutzt wttr.in, um Wetterinformationen bereitzustellen. Er kann konfiguriert werden, um das aktuelle Wetter oder die vollständige Vorhersage zu erhalten. O agente de previsão do tempo é um Telegram bot que se comunica com o Claude Code headless, oferecendo previsões meteorológicas gratuitas sem necessidade de chaves de API ИИ агент погоды - это Telegram бот, который общается с Claude Code headless, предоставляя бесплатные прогнозы погоды без необходимости API ключей عامل الطقس هو بوت تلجرام يتحدث إلى كلود كود بدون رأس، يقدم تنبؤات جوية مجانية بدون مفتاح واجهة برمجة التطبيقات how to use wttr.in weather API alternative setup weather skill weather vs darksky wttr.in API documentation install weather skill for Telegram 天气API wttr.in Telegram bot 天气预报 条件 CLI API密钥 URL编码 机场代码 Utilizes wttr.in API for primary weather data Supports compact format for quick weather summaries Generates full forecast output with temperature, humidity, and wind details Allows URL-encoded spaces for city names, such as New+York Accepts airport codes for location-specific weather data Weather is a Telegram bot skill that retrieves and displays current weather conditions and forecasts from wttr.in');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bdfinst/vsm-workshop/new-component', 'community', 'bdfinst', 'vsm-workshop', 'bdfinst/vsm-workshop', 'new-component', 0, 0, 51, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:41.516Z', '60b9a5e571eda66b98bfd17e2448d000a2660efe692488ebbbb7f1c37e2ebba5', '{"id":"bdfinst/vsm-workshop/new-component","name":"new-component","description":{"en":"The new-component skill creates a new React component following project conventions, benefiting developers who need to implement features with step definitions.","zh":"新组件技能帮助您创建符合项目规范的React组件，包括使用CLI命令和定义Props类型","ja":"新コンポーネントスキルは、プロジェクト規約に従ったReactコンポーネントを作成するのに役立ちます。CLIコマンドとPropsタイプ定義を使用します","ko":"새 컴포넌트 스킬은 프로젝트 규약에 따라 React 컴포넌트를 생성하는 데 도움이 되며 CLI 명령과 Props 유형 정의를 사용합니다","es":"El nuevo componente es una herramienta de línea de comandos que permite a los desarrolladores crear nuevos componentes React siguiendo las convenciones del proyecto","fr":"Le nouveau composant est un outil en ligne de commande qui permet aux développeurs de créer de nouveaux composants React en suivant les conventions du projet","de":"Die neue Komponente ist ein Befehlszeilen-Tool, mit dem Entwickler neue React-Komponenten erstellen können, die den Projektkonventionen entsprechen","pt":"O skill new-component cria um novo componente React seguindo as convenções do projeto. Ele usa componentes funcionais com hooks e define PropTypes","ru":"Навык new-component создает новый компонент React, следуя проектным конвенциям. Он использует функциональные компоненты с хуками и определяет PropTypes","ar":"المهارة المكون الجديد تخلق مكونًا جديدًا من مكونات React متوافقًا مع إرشادات المشروع. إنها تستخدم المكونات الوظيفية مع Hooks وتعرف PropTypes"},"seo":{"title":{"en":"new-component: React Component Setup Guide | AI Agent Skill","zh":"新组件创建指南 - 使用React和CLI","ja":"新コンポーネント作成ガイド - ReactとCLIのベストプラクティス","ko":"새 컴포넌트 생성 설정 가이드 - React와 CLI 활용","es":"Guía de configuración de nuevo componente React","fr":"Guide de démarrage pour les nouveaux composants React","de":"Einrichtungsleitfaden für neue React-Komponenten","pt":"Guia de Configuração do New-Component: Criando Componente...","ru":"Настройка нового компонента: Руководство по созданию комп...","ar":"دليل إعداد المكون الجديد: إنشاء مكونات React باستخدام أدو..."},"description":{"en":"Learn how to create a new React component with the new-component skill. Get started with our step-by-step guide and optimize your development workflow.","zh":"使用新组件技能，创建符合项目规范的React组件，了解CLI命令和Props类型定义","ja":"新コンポーネントスキルを使用して、プロジェクト規約に従ったReactコンポーネントを作成します。CLIコマンドとPropsタイプ定義について学習します","ko":"새 컴포넌트 스킬을 사용하여 프로젝트 규약에 따라 React 컴포넌트를 생성하고 CLI 명령 및 Props 유형 정의를 익히세요","es":"Cree nuevos componentes React con facilidad siguiendo nuestras prácticas recomendadas y convenciones de proyecto","fr":"Créez de nouveaux composants React avec facilité en suivant nos meilleures pratiques et conventions de projet","de":"Erstellen Sie neue React-Komponenten mühelos, indem Sie unseren bewährten Praktiken und Projektkonventionen folgen","pt":"Aprenda a criar componentes React seguindo as convenções do projeto com o skill new-component. Veja como usar hooks e definir PropTypes","ru":"Узнайте, как создать компонент React, следуя проектным конвенциям, с помощью навыка new-component. Подробности о использовании хуков и определении PropTypes","ar":"تعلم كيفية إنشاء مكونات React متوافقة مع إرشادات المشروع باستخدام مهارة المكون الجديد. شاهد كيفية استخدام Hooks وتعريف PropTypes"},"definition":{"en":"new-component is a skill that generates a new React component file with functional components and hooks, following a specific directory structure.","zh":"新组件是AIエージェント的一项技能，用于创建符合项目规范的React组件","ja":"新コンポーネントは、AIエージェントのスキルの一つで、プロジェクト規約に従ったReactコンポーネントを作成するために使用されます","ko":"새 컴포넌트는 AI 에이전트의 하나의 스킬로 프로젝트 규약에 따라 React 컴포넌트를 생성하는 데 사용됩니다","es":"Un nuevo componente es una herramienta de AI que permite crear componentes React personalizados","fr":"Un nouveau composant est un outil d''IA qui permet de créer des composants React personnalisés","de":"Eine neue Komponente ist ein AI-Tool, mit dem benutzerdefinierte React-Komponenten erstellt werden können","pt":"O que é new-component? É um skill que cria componentes React novos, seguindo as convenções do projeto","ru":"Что такое new-component? Это навык, создающий новые компоненты React, следуя проектным конвенциям","ar":"ما هو المكون الجديد? إنه مهارة تخلق مكونات React جديدة متوافقة مع إرشادات المشروع"},"features":{"en":["Creates a new React component file at src/components/{directory}/{ComponentName}.jsx","Uses functional components with hooks","Defines PropTypes for component properties","Follows project conventions for directory structure","Requires a feature file and step definitions for component behavior","Supports command-line usage with /new-component <ComponentName> [directory]"],"zh":["使用CLI命令创建新组件","定义Props类型","创建符合项目规范的React组件","支持使用函数组件和钩子","生成组件文件到src/components目录"],"ja":["CLIコマンドを使用して新コンポーネントを作成","Propsタイプを定義","プロジェクト規約に従ったReactコンポーネントを作成","関数コンポーネントとフックの使用をサポート","コンポーネントファイルをsrc/componentsディレクトリに生成"],"ko":["CLI 명령을 사용하여 새 컴포넌트 생성","Props 유형 정의","프로젝트 규약에 따라 React 컴포넌트 생성","함수 컴포넌트와 훅 사용 지원","컴포넌트 파일을 src/components 디렉토리에 생성"],"es":["Crea componentes React con funciones y hooks","Define los tipos de propiedades con PropTyp","Coloca los archivos de componentes en el directorio src/components","Utiliza la línea de comandos para crear componentes","Sigue las convenciones del proyecto para la creación de componentes"],"fr":["Crée des composants React avec des fonctions et des hooks","Définit les types de propriétés avec PropTyp","Place les fichiers de composants dans le répertoire src/components","Utilise la ligne de commande pour créer des composants","Suive les conventions du projet pour la création de composants"],"de":["Erstellt React-Komponenten mit Funktionen und Hooks","Definiert die Eigenschaftstypen mit PropTyp","Platziert die Komponenten-Dateien im src/components-Verzeichnis","Verwendet die Befehlszeile, um Komponenten zu erstellen","Folgt den Projektkonventionen für die Erstellung von Komponenten"],"pt":["Criação de componentes React novos","Uso de componentes funcionais com hooks","Definição de PropTypes","Conformidade com as convenções do projeto","Integração com arquivos de recursos existentes","Suporte à criação de componentes personalizados"],"ru":["Создание новых компонентов React","Использование функциональных компонентов с хуками","Определение PropTypes","Совместимость с проектными конвенциями","Интеграция с существующими ресурсными файлами","Поддержка создания пользовательских компонентов"],"ar":["إنشاء مكونات React جديدة","استخدام المكونات الوظيفية مع Hooks","تعريف PropTypes","الامتثال لإرشادات المشروع","التكامل مع الملفات المصدرية الحالية","دعم إنشاء مكونات مخصصة"]},"keywords":{"en":["how to use new-component","new-component react setup","create react component with new-component","new-component vs create-react-app","new-component install guide","react component best practices with new-component","what is new-component","new-component alternative","new-component setup tutorial"],"zh":["新组件","React组件","CLI命令","Props类型","AIエージェント","项目规范","函数组件","钩子"],"ja":["新コンポーネント","Reactコンポーネント","CLIコマンド","Propsタイプ","AIエージェント","プロジェクト規約","関数コンポーネント","フック"],"ko":["새 컴포넌트","React 컴포넌트","CLI 명령","Props 유형","AI 에이전트","프로젝트 규약","함수 컴포넌트","훅"],"es":["nuevo componente React","herramienta de línea de comandos","convenciones de proyecto","componentes personalizados","React con hooks","PropTyp","src/components","AI Agentes","desarrollo de software"],"fr":["nouveau composant React","outil en ligne de commande","conventions de projet","composants personnalisés","React avec hooks","PropTyp","src/components","Outils d''IA","développement de logiciels"],"de":["neue React-Komponente","Befehlszeilen-Tool","Projektkonventionen","benutzerdefinierte Komponenten","React mit Hooks","PropTyp","src/components","KI-Tools","Software-Entwicklung"],"pt":["new-component","criar componente react","react hooks","propTypes","convenções do projeto","componentes react personalizados","ferramentas de desenvolvimento react","ai agents","desenvolvimento de software","tecnologias web"],"ru":["new-component","создать компонент react","react хуки","propTypes","проектные конвенции","пользовательские компоненты react","инструменты разработки react","ИИ Агенты","разработка программного обеспечения","веб-технологии"],"ar":["المكون الجديد","إنشاء مكون react","Hooks react","propTypes","إرشادات المشروع","مكونات react مخصصة","أدوات تطوير react","أدوات الذكاء الاصطناعي","تطوير البرمجيات","تكنولوجيا الويب"]}},"owner":"bdfinst","repo":"vsm-workshop","repoPath":"bdfinst/vsm-workshop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"new-component","description":"Create a new React component following project conventions with PropTypes and test attributes","bodyPreview":"# Skill: Create New Component\n\nCreate a new React component following project conventions.\n\n## Usage\n\n```\n/new-component <ComponentName> [directory]\n```\n\n## Prerequisites\n\nThis should typically be done as part of implementing a feature. Ensure:\n- A feature file exists that requires this component\n- Step definitions reference the component''s behavior\n\n## Steps\n\n1. Create the component file at `src/components/{directory}/{ComponentName}.jsx`\n2. Use functional component with hooks\n3. Define PropTyp","body":"# Skill: Create New Component\n\nCreate a new React component following project conventions.\n\n## Usage\n\n```\n/new-component <ComponentName> [directory]\n```\n\n## Prerequisites\n\nThis should typically be done as part of implementing a feature. Ensure:\n- A feature file exists that requires this component\n- Step definitions reference the component''s behavior\n\n## Steps\n\n1. Create the component file at `src/components/{directory}/{ComponentName}.jsx`\n2. Use functional component with hooks\n3. Define PropTypes for type checking\n4. Export the component as default\n5. Add data-testid attributes for acceptance testing\n\n## Template\n\n```jsx\n// src/components/{directory}/{ComponentName}.jsx\n\nimport { useState } from ''react'';\nimport PropTypes from ''prop-types'';\n\nfunction {ComponentName}({ prop1, prop2 }) {\n  // Component logic here\n\n  return (\n    <div data-testid=\"{component-name}\">\n      {/* Component content */}\n    </div>\n  );\n}\n\n{ComponentName}.propTypes = {\n  prop1: PropTypes.string.isRequired,\n  prop2: PropTypes.number\n};\n\n{ComponentName}.defaultProps = {\n  prop2: 0\n};\n\nexport default {ComponentName};\n```\n\n## Naming Conventions\n\n- Component files: PascalCase (`StepEditor.jsx`)\n- Test IDs: kebab-case (`data-testid=\"step-editor\"`)\n- CSS classes: kebab-case with BEM (`step-editor__input`)\n\n## Test ID Guidelines\n\nAdd `data-testid` attributes for elements that acceptance tests need to interact with:\n\n```jsx\n<button data-testid=\"add-step-button\">Add Step</button>\n<input data-testid=\"step-name-input\" />\n<div data-testid=\"metrics-dashboard\">...</div>\n```\n\n## Integration with Acceptance Tests\n\nComponents should be designed to support acceptance testing:\n\n```javascript\n// In step definitions\nWhen(''I click the add step button'', async function () {\n  const button = await this.page.$(''[data-testid=\"add-step-button\"]'');\n  await button.click();\n});\n\nThen(''I should see the step editor'', async function () {\n  const editor = await this.page.$(''[data-testid=\"step-editor\"]'');\n  expect(editor).to.exist;\n});\n```\n"},"lastSynced":"2026-03-08T02:03:41.516Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring rapid React component development with precise step definitions.","zh":"适合需要快速React组件开发和精确步骤定义的前端代理。","ja":"Reactコンポーネントの迅速な開発と正確なステップ定義を必要とするフロントエンドエージェントに適しています。","ko":"신속한 React 컴포넌트 개발 및 정확한 단계 정의가 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes Frontend que requieren un desarrollo rápido de componentes React con definiciones de paso precisas.","fr":"Idéal pour les agents Frontend nécessitant un développement rapide de composants React avec des définitions de pas précises.","de":"Ideal für Frontend-Agents, die eine schnelle Entwicklung von React-Komponenten mit präzisen Schrittdefinitionen erfordern.","pt":"Ideal para Agentes Frontend que necessitam de desenvolvimento rápido de componentes React com definições de etapas precisas.","ru":"Идеально для агентов Frontend, требующих быстрого разработки компонентов React с точными определениями шагов.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى تطوير مكونات React سريع مع تعريفات خطوات دقيقة."},"recommendation":{"en":"Empowers agents to create new React components following project conventions, utilizing functional components with hooks and defining PropTypes, all while adhering to a structured directory setup like `src/components/{directory}/{ComponentName}.jsx`.","zh":"赋予代理创建新的React组件的能力，遵循项目惯例，利用带有钩子的函数组件和定义PropTypes，同时遵循结构化的目录设置，如`src/components/{directory}/{ComponentName}.jsx`。","ja":"プロジェクトの規約に従って新しいReactコンポーネントを作成するエージェントに力を与え、フック付きの関数コンポーネントを使用し、PropTypesを定義し、`src/components/{directory}/{ComponentName}.jsx`などの構造化されたディレクトリ設定に従います。","ko":"프로젝트 규칙을 따르면서 새로운 React 컴포넌트를 생성할 수 있는 에이전트에게 권한을 부여하며, 훅이 있는 함수 컴포넌트를 사용하고 PropTypes를 정의하며, `src/components/{directory}/{ComponentName}.jsx`와 같은 구조화된 디렉토리 설정을 따릅니다.","es":"Permite a los agentes crear nuevos componentes React siguiendo las convenciones del proyecto, utilizando componentes funcionales con hooks y definiendo PropTypes, todo mientras se adhiere a una configuración de directorio estructurada como `src/components/{directory}/{ComponentName}.jsx`.","fr":"Permet aux agents de créer de nouveaux composants React en suivant les conventions de projet, en utilisant des composants fonctionnels avec des hooks et en définissant des PropTypes, le tout en respectant une configuration de répertoire structurée comme `src/components/{directory}/{ComponentName}.jsx`.","de":"Ermächtigt Agents, neue React-Komponenten gemäß den Projekt-Konventionen zu erstellen, wobei funktionale Komponenten mit Hooks verwendet und PropTypes definiert werden, während eine strukturierte Verzeichniseinstellung wie `src/components/{directory}/{ComponentName}.jsx` eingehalten wird.","pt":"Habilita os agentes a criar novos componentes React seguindo as convenções do projeto, utilizando componentes funcionais com hooks e definindo PropTypes, tudo enquanto adere a uma estrutura de diretório estruturada como `src/components/{directory}/{ComponentName}.jsx`.","ru":"Наделяет агентов возможностью создавать новые компоненты React, следуя конвенциям проекта, используя функциональные компоненты с хуками и определяя PropTypes, все это придерживаясь структурированной настройки директории, как `src/components/{directory}/{ComponentName}.jsx`.","ar":"تمكن الوكلاء من إنشاء مكونات React جديدة اتباعًا لاتفاقيات المشروع، باستخدام المكونات الوظيفية مع Hooks وتعريف PropTypes، وكل ذلك مع التمسك بترتيب دليل منظم مثل `src/components/{directory}/{ComponentName}.jsx`."},"useCases":{"en":["Automating React component creation for feature implementations","Generating component files with proper directory structuring","Defining component behavior through step definitions"],"zh":["为功能实现自动化React组件创建","生成具有适当目录结构的组件文件","通过步骤定义来定义组件行为"],"ja":["機能実装のためのReactコンポーネントの自動生成","適切なディレクトリ構造を持つコンポーネントファイルの生成","ステップ定義を通じてコンポーネントの動作を定義"],"ko":["기능 구현을 위한 React 컴포넌트 자동 생성","적절한 디렉토리 구조를 갖는 컴포넌트 파일 생성","단계 정의를 통해 컴포넌트 동작 정의"],"es":["Automatización de la creación de componentes React para implementaciones de características","Generación de archivos de componentes con una estructura de directorio adecuada","Definición del comportamiento del componente a través de definiciones de pasos"],"fr":["Automatisation de la création de composants React pour les implémentations de fonctionnalités","Génération de fichiers de composants avec une structure de répertoire appropriée","Définition du comportement du composant via des définitions de pas"],"de":["Automatisierung der Erstellung von React-Komponenten für die Implementierung von Funktionen","Erzeugung von Komponenten-Dateien mit einer geeigneten Verzeichnisstruktur","Definition des Komponentenverhaltens durch Schrittdefinitionen"],"pt":["Automatizar a criação de componentes React para implementações de recursos","Gerar arquivos de componentes com estruturação de diretório adequada","Definir comportamento de componentes por meio de definições de etapas"],"ru":["Автоматизация создания компонентов React для реализации функций","Генерация файлов компонентов с правильной структурировкой директории","Определение поведения компонентов через определения шагов"],"ar":["تأتمتة إنشاء مكونات React لتنفيذ الميزات","توليد ملفات المكونات بترتيب دليلي مناسب","تعريف سلوك المكونات من خلال تعريفات الخطوات"]},"limitations":{"en":["Requires existing feature files and step definitions","Adherence to specific project directory conventions"],"zh":["需要现有的功能文件和步骤定义","遵守特定的项目目录约定"],"ja":["既存の機能ファイルとステップ定義が必要","特定のプロジェクトディレクトリ規約の遵守"],"ko":["기존 기능 파일 및 단계 정의가 필요","특정 프로젝트 디렉토리 규칙을 준수"],"es":["Requiere archivos y definiciones de pasos de características existentes","Adhesión a convenciones de directorio de proyecto específicas"],"fr":["Nécessite des fichiers et des définitions de pas de fonctionnalités existants","Respect des conventions de répertoire de projet spécifiques"],"de":["Benötigt vorhandene Feature-Dateien und Schrittdefinitionen","Einhaltung spezifischer Projekt-Verzeichiskonventionen"],"pt":["Exige arquivos de recursos existentes e definições de etapas","Adesão a convenções de diretório de projeto específicas"],"ru":["Требует существующих файлов функций и определений шагов","Соблюдение конкретных конвенций директории проекта"],"ar":["يتطلب ملفات ميزات موجودة وتعريفات خطوات","الامتثال لاتفاقيات دليل مشروع محددة"]},"version":4},"contentHash":"60b9a5e571eda66b98bfd17e2448d000a2660efe692488ebbbb7f1c37e2ebba5","qualityScore":51}');
