INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bdfinst/vsm-workshop/new-component', 'new-component', 'bdfinst', 'vsm-workshop', 'community', 'new-component bdfinst vsm-workshop community The new-component skill creates a new React component following project conventions, benefiting developers who need to implement features with step definitions. 新组件技能帮助您创建符合项目规范的React组件，包括使用CLI命令和定义Props类型 新コンポーネントスキルは、プロジェクト規約に従ったReactコンポーネントを作成するのに役立ちます。CLIコマンドとPropsタイプ定義を使用します 새 컴포넌트 스킬은 프로젝트 규약에 따라 React 컴포넌트를 생성하는 데 도움이 되며 CLI 명령과 Props 유형 정의를 사용합니다 El nuevo componente es una herramienta de línea de comandos que permite a los desarrolladores crear nuevos componentes React siguiendo las convenciones del proyecto Le nouveau composant est un outil en ligne de commande qui permet aux développeurs de créer de nouveaux composants React en suivant les conventions du projet Die neue Komponente ist ein Befehlszeilen-Tool, mit dem Entwickler neue React-Komponenten erstellen können, die den Projektkonventionen entsprechen O skill new-component cria um novo componente React seguindo as convenções do projeto. Ele usa componentes funcionais com hooks e define PropTypes Навык new-component создает новый компонент React, следуя проектным конвенциям. Он использует функциональные компоненты с хуками и определяет PropTypes المهارة المكون الجديد تخلق مكونًا جديدًا من مكونات React متوافقًا مع إرشادات المشروع. إنها تستخدم المكونات الوظيفية مع Hooks وتعرف PropTypes how to use new-component new-component react setup create react component with new-component new-component vs create-react-app new-component install guide react component best practices with new-component what is new-component new-component alternative new-component setup tutorial 新组件 React组件 CLI命令 Props类型 AIエージェント 项目规范 函数组件 钩子 Creates a new React component file at src/components/{directory}/{ComponentName}.jsx Uses functional components with hooks Defines PropTypes for component properties Follows project conventions for directory structure Requires a feature file and step definitions for component behavior Supports command-line usage with /new-component <ComponentName> [directory] new-component is a skill that generates a new React component file with functional components and hooks, following a specific directory structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('UnaMentis/unamentis/mcp-setup', 'community', 'UnaMentis', 'unamentis', 'UnaMentis/unamentis', 'mcp-setup', 0, 0, 51, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:41.844Z', 'db9850a924eeea1b40c4e923e3a4b89321aa479889c9209f8740109cd5f1eb7e', '{"id":"UnaMentis/unamentis/mcp-setup","name":"mcp-setup","description":{"en":"The mcp-setup skill configures MCP session defaults for iOS simulator and Xcode build operations, ensuring correct project, scheme, and simulator settings. This skill benefits developers working with iOS apps and Xcode.","zh":"MCP Setup是一种iOS基于AI驱动的个人学习助手，用于配置MCP会话默认值，确保正确的项目、方案和模拟器设置","ja":"MCP Setupは、AIエージェントによるiOS学習支援ツールで、MCPセッションのデフォルト値を設定し、正しいプロジェクト、スキーム、シミュレータの設定を実施","ko":"MCP Setup은 iOS 기반의 AI 구동 개인 학습 보조도구로서 MCP 세션 기본값을 설정하여 올바른 프로젝트, 스키마 및 시뮬레이터 설정을 보장","es":"El skill mcp-setup configura los valores predeterminados de la sesión MCP para operaciones de simulador de iOS y compilación de Xcode","fr":"Le skill mcp-setup configure les valeurs par défaut de la session MCP pour les opérations de simulateur iOS et de build Xcode","de":"Das mcp-setup-Skill konfiguriert die Standardwerte für die MCP-Sitzung für iOS-Simulator- und Xcode-Build-Vorgänge","pt":"O mcp-setup é uma ferramenta de configuração para desenvolvedores iOS que garante a configuração correta do projeto, esquema e simulador antes de qualquer operação de build ou teste.","ru":"mcp-setup - это инструмент для настройки разработчиков iOS, который обеспечивает правильную настройку проекта, схемы и симулятора перед любыми операциями сборки или тестирования.","ar":"مكتبة mcp-setup هي أداة إعداد للمانحين تؤكد إعداد المشروع والخطة والمحاكي بشكل صحيح قبل أي عملية بناء أو اختبار"},"seo":{"title":{"en":"mcp-setup: MCP Session Configuration Setup Guide | AI Age...","zh":"MCP Setup 指南：iOS AI 个人学习助手配置","ja":"MCP Setup ガイド：AIエージェントによるiOS学習支援","ko":"MCP Setup 가이드: iOS AI 개인 학습 보조도구 설정","es":"Configuración de MCP: Guía de setup para iOS","fr":"Configuration MCP : Guide de setup pour les développeurs iOS","de":"MCP-Setup: Leitfaden für iOS-Entwickler","pt":"Guia de Configuração mcp-setup para Desenvolvedores","ru":"Настройка mcp-setup: Руководство для разработчиков ИИ Аге...","ar":"دليل إعداد mcp-setup لمنصة iOS"},"description":{"en":"Configure MCP session defaults for iOS simulator and Xcode build operations with mcp-setup. Learn how to set up MCP defaults and ensure successful builds.","zh":"了解MCP Setup的技术细节，配置iOS模拟器和Xcode构建操作，确保正确的项目、方案和模拟器设置","ja":"MCP Setupの技術的な詳細を学び、iOSシミュレータとXcodeビルド操作を設定し、正しいプロジェクト、スキーム、シミュレータの設定を確実に実施","ko":"MCP Setup의 기술적 세부 정보를 학습하고 iOS 시뮬레이터 및 Xcode 빌드 작업을 설정하여 올바른 프로젝트, 스키마 및 시뮬레이터 설정을 보장","es":"Aprende a configurar MCP para sesiones de simulador de iOS y operaciones de compilación de Xcode con nuestra guía de setup","fr":"Découvrez comment configurer MCP pour les sessions de simulateur iOS et les opérations de build Xcode avec notre guide de setup","de":"Erfahren Sie, wie Sie MCP für iOS-Simulator-Sitzungen und Xcode-Build-Vorgänge konfigurieren","pt":"Aprenda a configurar o mcp-setup para desenvolver aplicações iOS com segurança e eficiência","ru":"Узнайте, как настроить mcp-setup для разработки приложений iOS с помощью ИИ Агентов","ar":"تعلم كيفية إعداد mcp-setup لتنمية تطبيقات iOS بسهولة وسرعة"},"definition":{"en":"mcp-setup is a skill that configures Model Context Protocol (MCP) session defaults for iOS simulator and Xcode build operations.","zh":"MCP Setup是一种用于配置MCP会话默认值的技术，用于iOS模拟器和Xcode构建操作","ja":"MCP Setupは、MCPセッションのデフォルト値を設定する技術で、iOSシミュレータとXcodeビルド操作に使用","ko":"MCP Setup은 MCP 세션 기본값을 설정하는 기술로서 iOS 시뮬레이터 및 Xcode 빌드 작업에 사용","es":"MCP es un protocolo que establece los valores predeterminados para sesiones de simulador de iOS y compilación de Xcode","fr":"MCP est un protocole qui définit les valeurs par défaut pour les sessions de simulateur iOS et de build Xcode","de":"MCP ist ein Protokoll, das die Standardwerte für iOS-Simulator- und Xcode-Build-Sitzungen festlegt","pt":"O mcp-setup é uma ferramenta de configuração para desenvolvedores iOS que define as configurações padrão do MCP","ru":"mcp-setup - это инструмент для настройки разработчиков iOS, который определяет стандартные настройки MCP","ar":"مكتبة mcp-setup هي أداة إعداد لتعريف إعدادات MCP الافتراضية"},"features":{"en":["Configures MCP session defaults for iOS simulator","Sets correct project, scheme, and simulator settings for Xcode build operations","Supports configuration for main iOS app and Server Manager","Ensures successful builds by setting MCP defaults before building","Uses commands like /mcp-setup ios and /mcp-setup usm for configuration"],"zh":["配置MCP会话默认值","支持iOS模拟器和Xcode构建操作","确保正确的项目、方案和模拟器设置","支持多种配置选项，包括iOS主应用和Server Manager"],"ja":["MCPセッションのデフォルト値を設定","iOSシミュレータとXcodeビルド操作をサポート","正しいプロジェクト、スキーム、シミュレータの設定を実施","複数の設定オプションをサポート、包括iOSメインアプリとServer Manager"],"ko":["MCP 세션 기본값 설정","iOS 시뮬레이터 및 Xcode 빌드 작업 지원","올바른 프로젝트, 스키마 및 시뮬레이터 설정 보장","다양한 설정 옵션 지원, 포함 iOS 메인 앱 및 Server Manager"],"es":["Configuración de valores predeterminados de la sesión MCP","Compatibilidad con simulador de iOS y compilación de Xcode","Soporte para proyectos y esquemas de iOS","Configuración de la sesión MCP para operaciones de build y prueba","Integración con herramientas de desarrollo de iOS"],"fr":["Configuration des valeurs par défaut de la session MCP","Compatibilité avec le simulateur iOS et la compilation Xcode","Prise en charge des projets et des schémas iOS","Configuration de la session MCP pour les opérations de build et de test","Intégration avec les outils de développement iOS"],"de":["Konfiguration der Standardwerte für die MCP-Sitzung","Kompatibilität mit dem iOS-Simulator und der Xcode-Compilierung","Unterstützung für iOS-Projekte und -Schemata","Konfiguration der MCP-Sitzung für Build- und Testvorgänge","Integration mit iOS-Entwicklungstools"],"pt":["Configuração do projeto e esquema para build e teste","Definição do simulador para operações de build e teste","Garantia de configuração correta do MCP antes de qualquer operação","Suporte para desenvolvimento de aplicações iOS","Integração com Xcode para operações de build e teste"],"ru":["Настройка проекта и схемы для сборки и тестирования","Определение симулятора для операций сборки и тестирования","Гарантия правильной настройки MCP перед любыми операциями","Поддержка разработки приложений iOS","Интеграция с Xcode для операций сборки и тестирования"],"ar":["إعداد المشروع والخطة لعمليات البناء والاختبار","تحديد المحاكي لعمليات البناء والاختبار","ضمان إعداد MCP بشكل صحيح قبل أي عملية","دعم تطوير تطبيقات iOS","التكامل مع Xcode لعمليات البناء والاختبار"]},"keywords":{"en":["how to use mcp-setup","mcp-setup setup guide","mcp-setup alternative","mcp-setup vs Xcode","what is mcp-setup","mcp-setup install","MCP session configuration","iOS simulator setup","Xcode build operations"],"zh":["MCP Setup","iOS AI 个人学习助手","MCP 会话默认值","iOS 模拟器","Xcode 构建操作","AI 学习工具","iOS 开发"],"ja":["MCP Setup","AIエージェント","MCPセッションのデフォルト値","iOSシミュレータ","Xcodeビルド操作","AI学習ツール","iOS開発"],"ko":["MCP Setup","AI 개인 학습 보조도구","MCP 세션 기본값","iOS 시뮬레이터","Xcode 빌드 작업","AI 학습 도구","iOS 개발"],"es":["mcp setup","configuración de mcp","desarrollo de ios","simulador de ios","compilación de xcode","herramientas de desarrollo de ios","protocolo mcp","agentes de aprendizaje automático","herramientas de ai para desarrolladores"],"fr":["mcp setup","configuration mcp","développement ios","simulateur ios","compilation xcode","outils de développement ios","protocole mcp","agents d''apprentissage automatique","outils d''ia pour développeurs"],"de":["mcp setup","mcp-konfiguration","ios-entwicklung","ios-simulator","xcode-compilierung","ios-entwicklungstools","mcp-protokoll","künstliche intelligenz agenten","ai-tools für entwickler"],"pt":["mcp-setup","desenvolvimento iOS","configuração MCP","Xcode","simulador iOS","build e teste","desenvolvedores iOS","ferramentas de desenvolvimento","configuração de projeto"],"ru":["mcp-setup","разработка приложений iOS","настройка MCP","Xcode","симулятор iOS","сборка и тестирование","разработчики iOS","инструменты разработки","настройка проекта"],"ar":["mcp-setup","تطوير تطبيقات iOS","إعداد MCP","Xcode","محاكي iOS","بناء واختبار","مانحون iOS","أدوات التطوير","إعداد المشروع"]}},"owner":"UnaMentis","repo":"unamentis","repoPath":"UnaMentis/unamentis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"mcp-setup","description":"Configure MCP session defaults for different project components","bodyPreview":"# /mcp-setup - MCP Session Configuration\n\n## Purpose\n\nConfigures MCP (Model Context Protocol) session defaults for iOS simulator and Xcode build operations. This skill ensures the correct project, scheme, and simulator are set before any build or test operations.\n\n**Critical Rule:** MCP defaults MUST be set before building. Building without proper defaults will fail.\n\n## Usage\n\n```\n/mcp-setup ios        # Configure for main iOS app (default)\n/mcp-setup usm        # Configure for Server Manager a","body":"# /mcp-setup - MCP Session Configuration\n\n## Purpose\n\nConfigures MCP (Model Context Protocol) session defaults for iOS simulator and Xcode build operations. This skill ensures the correct project, scheme, and simulator are set before any build or test operations.\n\n**Critical Rule:** MCP defaults MUST be set before building. Building without proper defaults will fail.\n\n## Usage\n\n```\n/mcp-setup ios        # Configure for main iOS app (default)\n/mcp-setup usm        # Configure for Server Manager app\n/mcp-setup show       # Show current session defaults\n/mcp-setup clear      # Clear session defaults\n```\n\n## Configurations\n\n### iOS App (default)\n```\nProject: $PROJECT_ROOT/UnaMentis.xcodeproj\nScheme: UnaMentis\nSimulator: iPhone 16 Pro\n```\n\n### Server Manager (USM)\n```\nWorkspace: $PROJECT_ROOT/server/server-manager/USMXcode/USM.xcworkspace\nScheme: USM\nSimulator: iPhone 16 Pro\n```\n\nWhere `$PROJECT_ROOT` is the absolute path to the unamentis repository on this machine (the current working directory).\n\n## Workflow\n\n### 1. Set Session Defaults\n\nFor iOS app:\n```\nmcp__XcodeBuildMCP__session-set-defaults({\n  projectPath: \"$PROJECT_ROOT/UnaMentis.xcodeproj\",\n  scheme: \"UnaMentis\",\n  simulatorName: \"iPhone 16 Pro\"\n})\n```\n\nFor USM:\n```\nmcp__XcodeBuildMCP__session-set-defaults({\n  workspacePath: \"$PROJECT_ROOT/server/server-manager/USMXcode/USM.xcworkspace\",\n  scheme: \"USM\",\n  simulatorName: \"iPhone 16 Pro\"\n})\n```\n\n**Note:** Replace `$PROJECT_ROOT` with the actual absolute path to the unamentis directory (use `pwd` in the project root to get this).\n\n### 2. Verify Configuration\n\n```\nmcp__XcodeBuildMCP__session-show-defaults()\n```\n\n### 3. Confirm Simulator Available\n\n```\nmcp__XcodeBuildMCP__list_sims()\n```\n\nEnsure the target simulator exists and is available.\n\n## Success Criteria\n\n- Session defaults set successfully\n- Scheme is valid for the project\n- Simulator exists and is available\n\n## Examples\n\n**Configure for iOS development:**\n```\nUser: /mcp-setup ios\nClaude: Configuring MCP for iOS app development...\n\nSetting defaults:\n- Project: UnaMentis.xcodeproj\n- Scheme: UnaMentis\n- Simulator: iPhone 16 Pro\n\nConfiguration complete. You can now use:\n- /ios-build or build commands\n- MCP simulator tools\n```\n\n**Configure for USM development:**\n```\nUser: /mcp-setup usm\nClaude: Configuring MCP for Server Manager development...\n\nSetting defaults:\n- Workspace: USM.xcworkspace\n- Scheme: USM\n- Simulator: iPhone 16 Pro\n\nConfiguration complete. Ready to build USM.\n```\n\n**Show current configuration:**\n```\nUser: /mcp-setup show\nClaude: Current MCP session defaults:\n\nProject: $PROJECT_ROOT/UnaMentis.xcodeproj\nScheme: UnaMentis\nSimulator: iPhone 16 Pro (ID: 12345678-1234-1234-1234-123456789ABC)\nConfiguration: Debug\n```\n\n**Clear configuration:**\n```\nUser: /mcp-setup clear\nClaude: Clearing MCP session defaults...\n\nAll session defaults cleared. Run /mcp-setup ios or /mcp-setup usm to reconfigure.\n```\n\n## Available Simulators\n\nCommon simulators (verify with `list_sims`):\n- iPhone 16 Pro (preferred for CI parity)\n- iPhone 17 Pro\n- iPhone 15 Pro\n- iPad Pro 13-inch\n\n**Note:** iPhone 16 Pro is the default to match CI. The test runner includes automatic fallback to other available simulators if the preferred one is not found.\n\n## Integration\n\nThis skill should be run:\n- At the start of a development session\n- When switching between iOS app and USM development\n- Before any build or test operations\n- When the simulator needs to change\n"},"lastSynced":"2026-03-08T02:03:41.844Z","agentAnalysis":{"suitability":{"en":"Perfect for iOS Development Agents requiring streamlined Xcode build operations and simulator management.","zh":"非常适合需要简化Xcode构建操作和模拟器管理的iOS开发代理。","ja":"Xcodeのビルド操作とシミュレータ管理をストリームライン化する必要があるiOS開発エージェントに最適です。","ko":"Xcode 빌드 작업 및 시뮬레이터 관리를 간소화해야 하는 iOS 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de iOS que requieren operaciones de compilación de Xcode optimizadas y administración de simulador.","fr":"Parfait pour les agents de développement iOS nécessitant des opérations de construction Xcode rationalisées et une gestion de simulateur.","de":"Perfekt für iOS-Entwicklungsagenten, die optimierte Xcode-Buildvorgänge und Simulatorverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento do iOS que exigem operações de compilação do Xcode otimizadas e gerenciamento de simulador.","ru":"Идеально подходит для агентов разработки iOS, требующих оптимизированных операций сборки Xcode и управления симулятором.","ar":"مثالي لعمليات التطوير على نظام iOS التي تتطلب عمليات بناء Xcode مُدارة وجيدة وإدارة محاكي"},"recommendation":{"en":"Empowers agents to configure MCP session defaults for iOS simulator and Xcode build operations, ensuring correct project, scheme, and simulator settings through Model Context Protocol (MCP) for seamless development and testing workflows.","zh":"赋予代理配置MCP会话默认值用于iOS模拟器和Xcode构建操作，确保通过模型上下文协议（MCP）正确的项目、方案和模拟器设置，从而实现无缝的开发和测试工作流。","ja":"エージェントがMCPセッションのデフォルトをiOSシミュレータとXcodeのビルド操作のために設定できるようにし、モデルコンテキストプロトコル（MCP）を介して正しいプロジェクト、スキーム、シミュレータ設定を確実に行い、シームレスな開発とテストのワークフローを実現します。","ko":"에이전트가 MCP 세션 기본 값을 iOS 시뮬레이터 및 Xcode 빌드 작업을 위해 구성 할 수있게 하여 모델 컨텍스트 프로토콜 (MCP)을 통해 올바른 프로젝트, 스키마 및 시뮬레이터 설정을 보장하고, 무제한 개발 및 테스트 워크 플로를 구현합니다.","es":"Habilita a los agentes a configurar los valores predeterminados de la sesión MCP para el simulador iOS y las operaciones de compilación de Xcode, garantizando la configuración correcta del proyecto, esquema y ajustes del simulador a través del Protocolo de Contexto de Modelo (MCP) para flujos de trabajo de desarrollo y prueba sin problemas.","fr":"Autorise les agents à configurer les valeurs par défaut de la session MCP pour le simulateur iOS et les opérations de construction Xcode, garantissant les paramètres de projet, de schéma et de simulateur corrects via le Protocole de Contexte de Modèle (MCP) pour des flux de travail de développement et de test sans problème.","de":"Ermöglicht es Agenten, die Standardwerte der MCP-Sitzung für den iOS-Simulator und die Xcode-Buildvorgänge zu konfigurieren, wodurch sichergestellt wird, dass die Projekt-, Scheme- und Simulator-Einstellungen über das Model Context Protocol (MCP) für reibungslose Entwicklung- und Testworkflows korrekt sind.","pt":"Habilita os agentes a configurar os padrões de sessão do MCP para o simulador do iOS e as operações de compilação do Xcode, garantindo configurações de projeto, esquema e simulador corretas por meio do Protocolo de Contexto de Modelo (MCP) para fluxos de trabalho de desenvolvimento e teste sem interrupções.","ru":"Наделяет агентов возможностью настраивать значения по умолчанию для сессии MCP для симулятора iOS и операций сборки Xcode, обеспечивая правильные настройки проекта, схемы и симулятора через Протокол модели контекста (MCP) для бесперебойных рабочих процессов разработки и тестирования.","ar":"تمكّن الوكلاء من تكوين إعدادات جلسة MCP الافتراضية لمحاكي iOS وعمليات بناء Xcode، مما يضمن إعدادات مشروع وخطط ومحاكي صحيحة من خلال بروتوكول سياق النموذج (MCP) من أجل سير عمل التطوير والاختبار السلس"},"useCases":{"en":["Configuring MCP defaults for iOS app development","Setting up Xcode build operations for automated testing","Managing simulator settings for diverse iOS app testing scenarios"],"zh":["为iOS应用开发配置MCP默认值","为自动化测试设置Xcode构建操作","为多样化的iOS应用测试场景管理模拟器设置"],"ja":["iOSアプリ開発のためのMCPデフォルトの設定","自動テストのためのXcodeビルド操作の設定","多様なiOSアプリテストシナリオのためのシミュレータ設定の管理"],"ko":["iOS 애플리케이션 개발을 위한 MCP 기본값 설정","자동화된 테스트를 위한 Xcode 빌드 작업 설정","다양한 iOS 애플리케이션 테스트 시나리오를 위한 시뮬레이터 설정 관리"],"es":["Configuración de los valores predeterminados de MCP para el desarrollo de aplicaciones iOS","Configuración de las operaciones de compilación de Xcode para pruebas automatizadas","Administración de la configuración del simulador para diversos escenarios de pruebas de aplicaciones iOS"],"fr":["Configuration des valeurs par défaut de MCP pour le développement d''applications iOS","Configuration des opérations de construction Xcode pour les tests automatisés","Gestion des paramètres du simulateur pour divers scénarios de test d''applications iOS"],"de":["Konfiguration der MCP-Standardwerte für die Entwicklung von iOS-Apps","Einrichtung der Xcode-Buildvorgänge für automatisierte Tests","Verwaltung der Simulator-Einstellungen für verschiedene iOS-App-Test-Szenarien"],"pt":["Configurando padrões do MCP para desenvolvimento de aplicativos iOS","Configurando operações de compilação do Xcode para testes automatizados","Gerenciando configurações do simulador para cenários de teste de aplicativos iOS diversificados"],"ru":["Настройка значений по умолчанию для MCP для разработки приложений iOS","Настройка операций сборки Xcode для автоматизированного тестирования","Управление настройками симулятора для различных сценариев тестирования приложений iOS"],"ar":["تكوين إعدادات MCP الافتراضية لتطوير تطبيقات iOS","تكوين عمليات بناء Xcode للاختبارات الآلية","إدارة إعدادات المحاكي لسيناريوهات اختبار تطبيقات iOS متنوعة"]},"limitations":{"en":["Requires Xcode installation","iOS simulator setup necessary","MCP defaults must be set before building"],"zh":["需要Xcode安装","需要iOS模拟器设置","构建之前必须设置MCP默认值"],"ja":["Xcodeのインストールが必要","iOSシミュレータの設定が必要","ビルド前にMCPデフォルトを設定する必要がある"],"ko":["Xcode 설치 필요","iOS 시뮬레이터 설정 필요","빌드 전에 MCP 기본값을 설정해야 함"],"es":["Se requiere la instalación de Xcode","Configuración del simulador iOS necesaria","Los valores predeterminados de MCP deben establecerse antes de la compilación"],"fr":["L''installation de Xcode est requise","La configuration du simulateur iOS est nécessaire","Les valeurs par défaut de MCP doivent être définies avant la construction"],"de":["Xcode-Installation erforderlich","iOS-Simulator-Setup erforderlich","MCP-Standardwerte müssen vor dem Build festgelegt werden"],"pt":["Exige a instalação do Xcode","Configuração do simulador do iOS necessária","Os padrões do MCP devem ser definidos antes da compilação"],"ru":["Требует установки Xcode","Необходима настройка симулятора iOS","Значения по умолчанию для MCP должны быть установлены до сборки"],"ar":["يتطلب تثبيت Xcode","يتطلب إعداد محاكي iOS","يجب تعيين إعدادات MCP الافتراضية قبل البناء"]},"version":4},"contentHash":"db9850a924eeea1b40c4e923e3a4b89321aa479889c9209f8740109cd5f1eb7e","qualityScore":51}');
