INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('UnaMentis/unamentis/mcp-setup', 'mcp-setup', 'UnaMentis', 'unamentis', 'community', 'mcp-setup UnaMentis unamentis community The mcp-setup skill configures MCP session defaults for iOS simulator and Xcode build operations, ensuring correct project, scheme, and simulator settings. This skill benefits developers working with iOS apps and Xcode. MCP Setup是一种iOS基于AI驱动的个人学习助手，用于配置MCP会话默认值，确保正确的项目、方案和模拟器设置 MCP Setupは、AIエージェントによるiOS学習支援ツールで、MCPセッションのデフォルト値を設定し、正しいプロジェクト、スキーム、シミュレータの設定を実施 MCP Setup은 iOS 기반의 AI 구동 개인 학습 보조도구로서 MCP 세션 기본값을 설정하여 올바른 프로젝트, 스키마 및 시뮬레이터 설정을 보장 El skill mcp-setup configura los valores predeterminados de la sesión MCP para operaciones de simulador de iOS y compilación de Xcode Le skill mcp-setup configure les valeurs par défaut de la session MCP pour les opérations de simulateur iOS et de build Xcode Das mcp-setup-Skill konfiguriert die Standardwerte für die MCP-Sitzung für iOS-Simulator- und Xcode-Build-Vorgänge O mcp-setup é uma ferramenta de configuração para desenvolvedores iOS que garante a configuração correta do projeto, esquema e simulador antes de qualquer operação de build ou teste. mcp-setup - это инструмент для настройки разработчиков iOS, который обеспечивает правильную настройку проекта, схемы и симулятора перед любыми операциями сборки или тестирования. مكتبة mcp-setup هي أداة إعداد للمانحين تؤكد إعداد المشروع والخطة والمحاكي بشكل صحيح قبل أي عملية بناء أو اختبار how to use mcp-setup mcp-setup setup guide mcp-setup alternative mcp-setup vs Xcode what is mcp-setup mcp-setup install MCP session configuration iOS simulator setup Xcode build operations MCP Setup iOS AI 个人学习助手 MCP 会话默认值 iOS 模拟器 Xcode 构建操作 AI 学习工具 iOS 开发 Configures MCP session defaults for iOS simulator Sets correct project, scheme, and simulator settings for Xcode build operations Supports configuration for main iOS app and Server Manager Ensures successful builds by setting MCP defaults before building Uses commands like /mcp-setup ios and /mcp-setup usm for configuration mcp-setup is a skill that configures Model Context Protocol (MCP) session defaults for iOS simulator and Xcode build operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dchuk/source_monitor/sm-configure', 'community', 'dchuk', 'source_monitor', 'dchuk/source_monitor', 'sm-configure', 0, 0, 51, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:45.221Z', 'dc4d0e4424cf77c0eed2c8de95536a6c3707a1ca45b688122f320a476212204f', '{"id":"dchuk/source_monitor/sm-configure","name":"sm-configure","description":{"en":"sm-configure is a comprehensive configuration DSL for SourceMonitor, allowing developers to customize settings and debug issues. It benefits developers working with Ruby and SourceMonitor.","zh":"sm-configure 是 SourceMonitor 的配置 DSL，用于在应用程序初始化器中设置配置选项","ja":"sm-configure は SourceMonitor の構成 DSL であり、アプリケーション初期化器内で構成オプションを設定するために使用されます","ko":"sm-configure는 SourceMonitor의 구성 DSL로서, 응용 프로그램 초기화器 내에서 구성 옵션을 설정하는 데 사용됩니다","es":"sm-configure es un lenguaje de configuración DSL para SourceMonitor. Configura tus proyectos de desarrollo de manera efectiva","fr":"sm-configure est un langage de configuration DSL pour SourceMonitor. Configurez vos projets de développement de manière efficace","de":"sm-configure ist eine Konfigurations-DSL für SourceMonitor. Konfigurieren Sie Ihre Entwicklungsprojekte effektiv","pt":"O sm-configure é uma linguagem de configuração do SourceMonitor que permite personalizar as configurações do aplicativo. Aprenda a configurar o sm-configure para atender às suas necessidades.","ru":"Sm-configure - это язык конфигурации SourceMonitor, который позволяет настраивать параметры приложения. Узнайте, как настроить sm-configure в соответствии с вашими потребностями.","ar":"sm-configure هو لغة ضبط SourceMonitor التي تمكنك من تخصيص إعدادات التطبيق. تعرف على كيفية ضبط sm-configure لتلبي احتياجاتك."},"seo":{"title":{"en":"sm-configure: Engine Configuration Setup Guide | AI Agent...","zh":"sm-configure 设置指南：SourceMonitor 配置 DSL","ja":"sm-configure セットアップガイド：SourceMonitor 構成