INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dchuk/source_monitor/sm-configure', 'sm-configure', 'dchuk', 'source_monitor', 'community', 'sm-configure dchuk source_monitor community sm-configure is a comprehensive configuration DSL for SourceMonitor, allowing developers to customize settings and debug issues. It benefits developers working with Ruby and SourceMonitor. sm-configure 是 SourceMonitor 的配置 DSL，用于在应用程序初始化器中设置配置选项 sm-configure は SourceMonitor の構成 DSL であり、アプリケーション初期化器内で構成オプションを設定するために使用されます sm-configure는 SourceMonitor의 구성 DSL로서, 응용 프로그램 초기화器 내에서 구성 옵션을 설정하는 데 사용됩니다 sm-configure es un lenguaje de configuración DSL para SourceMonitor. Configura tus proyectos de desarrollo de manera efectiva sm-configure est un langage de configuration DSL pour SourceMonitor. Configurez vos projets de développement de manière efficace sm-configure ist eine Konfigurations-DSL für SourceMonitor. Konfigurieren Sie Ihre Entwicklungsprojekte effektiv O sm-configure é uma linguagem de configuração do SourceMonitor que permite personalizar as configurações do aplicativo. Aprenda a configurar o sm-configure para atender às suas necessidades. Sm-configure - это язык конфигурации SourceMonitor, который позволяет настраивать параметры приложения. Узнайте, как настроить sm-configure в соответствии с вашими потребностями. sm-configure هو لغة ضبط SourceMonitor التي تمكنك من تخصيص إعدادات التطبيق. تعرف على كيفية ضبط sm-configure لتلبي احتياجاتك. how to use sm-configure sm-configure setup guide SourceMonitor configuration sm-configure vs alternative configurations what is sm-configure sm-configure install Ruby configuration best practices debugging sm-configure issues environment-specific overrides in sm-configure sm-configure SourceMonitor 配置 AI 工具 配置 DSL Ruby 编程 应用程序初始化器 配置选项 调试配置 环境特定设置 Configures SourceMonitor via the `SourceMonitor.configure` block Supports environment-specific overrides in `config/initializers/source_monitor.rb` Provides a comprehensive reference for understanding configuration options Enables debugging of configuration-related issues Allows for adding or modifying settings in the initializer file sm-configure is a configuration entry point for SourceMonitor, providing a comprehensive reference for configuring the engine via the SourceMonitor.configure block.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nibzard/2025-intro-swe/student-activity-analysis', 'community', 'nibzard', '2025-intro-swe', 'nibzard/2025-intro-swe', 'student-activity-analysis', 0, 0, 51, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:46.754Z', '1f1b1bb3a8c4d6fe1ca7f667e40b26b92eab59496c4158b572b485e7077aff7e', '{"id":"nibzard/2025-intro-swe/student-activity-analysis","name":"student-activity-analysis","description":{"en":"The student-activity-analysis skill automates the analysis of student git activity in software engineering, helping educators track student progress and identify areas of improvement.","zh":"学生活动分析工具自动化分析学生 Git 活动，帮助老师了解学生进度和参与情况。","ja":"学生活動分析 AIエージェントは、学生の Git 活動を自動分析し、教師が学生の進度と参加状況を把握することを支援します。","ko":"학생 활동 분석 툴은 학생의 Git 활동을 자동화하여 분석하고 교사가 학생의 진행 상황과 참여도를 파악하도록 도와줍니다.","es":"El análisis de actividad estudiantil es una habilidad que automatiza el análisis de la actividad de los estudiantes en git para identificar a los que están en riesgo.","fr":"L''analyse d''activité étudiante est une compétence qui automatise l''analyse de l''activité des étudiants dans git pour identifier ceux qui sont à risque.","de":"Die Studentenaktivitätsanalyse ist eine Fähigkeit, die die Analyse der Studentenaktivität in git automatisiert, um gefährdete Studenten zu identifizieren.","pt":"O análise de atividade estudantil é uma habilidade que automata a análise de atividade de git dos estudantes em engenharia de software","ru":"Анализ студенческой активности - это навык, который автоматизирует анализ активности студентов в git в области программной инженерии","ar":"تحليل نشاط الطلاب هو مهارة تتيح автомatisation تحليل نشاط جيت للطلاب في هندسة البرمجيات"},"seo":{"title":{"en":"Student-Activity-Analysis: Automated Git Activity Setup G...","zh":"学生活动分析工具 Setup Guide","ja":"学生活動分析 AIエージェントのベストプラクティス","ko":"학생 활동 분석 툴 사용 방법","es":"Guía de configuración de análisis de actividad estudianti...","fr":"Mise en place de l''analyse d''activité étudiante avec Outi...","de":"Einrichtungsleitfaden für Studentenaktivitätsanalyse mit ...","pt":"Guia de Configuração do Análise de Atividade Estudantil c...","ru":"Настройка ИИ Агентов для Анализа Студенческой Активности","ar":"دليل إعداد تحليل نشاط الطلاب باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to automate student git activity analysis and identify at-risk students. Learn how to invoke this skill and get started today!","zh":"自动化学生 Git 活动分析，提高教学效率。了解学生活动分析工具的功能和优点。","ja":"学生の Git 活動を自動分析し、教學の効率を上げる。学生活動分析 AIエージェントの詳細を確認。","ko":"학생의 Git 활동을 자동화하여 분석하고 교학效率를 높입니다. 학생 활동 분석 툴의 기능과 장점을 확인하세요.","es":"Automatice el análisis de actividad de estudiantes con git y identifique a estudiantes en riesgo con nuestra guía de análisis de actividad estudiantil","fr":"Automatisez l''analyse d''activité des étudiants avec git et identifiez les étudiants à risque avec notre guide d''analyse d''activité étudiante","de":"Automatisieren Sie die Analyse der Studentenaktivität mit git und identifizieren Sie gefährdete Studenten mit unserem Leitfaden für die Studentenaktivitätsan...","pt":"Aprenda a configurar o análise de atividade estudantil com ferramentas de IA para automatizar a análise de atividade de git dos estudantes","ru":"Узнайте, как настроить анализ студенческой активности с помощью ИИ агентов для автоматизации анализа активности студентов в git","ar":"تعلم كيفية إعداد تحليل نشاط الطلاب باستخدام أدوات الذكاء الاصطناعي لتحليل نشاط جيت للطلاب"},"definition":{"en":"student-activity-analysis is a skill that automates the analysis of student git activity in software engineering to track progress and identify at-risk students.","zh":"学生活动分析工具是一种自动化分析学生 Git 活动的软件","ja":"学生活動分析 AIエージェントは、学生の Git 活動を自動分析するための AI ツールです","ko":"학생 활동 분석 툴은 학생의 Git 활동을 자동화하여 분석하는 소프트웨어입니다","es":"Análisis de actividad estudiantil es una herramienta de IA que analiza la actividad de los estudiantes en git","fr":"L''analyse d''activité étudiante est un outil IA qui analyse l''activité des étudiants dans git","de":"Studentenaktivitätsanalyse ist ein KI-Tool, das die Aktivität der Studenten in git analysiert","pt":"O que é análise de atividade estudantil? É uma habilidade que analisa a atividade de git dos estudantes em engenharia de software","ru":"Что такое анализ студенческой активности? Это навык, который анализирует активность студентов в git в области программной инженерии","ar":"ما هو تحليل نشاط الطلاب? هو مهارة تتيح تحليل نشاط جيت للطلاب في هندسة البرمجيات"},"features":{"en":["Analyzes student git activity to track progress","Identifies at-risk students through automated analysis","Supports tracking of lab submissions and project work","Provides insights into student participation and engagement","Automates the process of checking class activity and student contributions"],"zh":["自动化分析学生 Git 活动","支持检查班级活动、实验提交和项目工作","帮助老师了解学生进度和参与情况","支持识别处于风险中的学生","集成 Git 技术","提供学生参与和进度的详细报告"],"ja":["学生の Git 活動を自動分析","クラス活動、実験提出、プロジェクト作業の確認をサポート","教師が学生の進度と参加状況を把握することを支援","リスクにある学生の特定をサポート","Git 技術との統合","学生の参加と進度の詳細なレポートを提供"],"ko":["학생의 Git 활동을 자동화하여 분석","교실 활동, 실험 제출, 프로젝트 작업 확인 지원","교사가 학생의 진행 상황과 참여도를 파악하도록 도와줌","위험에 처한 학생의 식별을 지원","Git 기술과 통합","학생의 참여와 진행 상황에 대한 자세한 보고서 제공"],"es":["Análisis automático de la actividad de los estudiantes en git","Identificación de estudiantes en riesgo","Verificación de la participación de los estudiantes","Análisis de la actividad en clase, trabajos de laboratorio y proyectos","Visualización de los estudiantes que han completado trabajos de laboratorio o contribuyen activamente"],"fr":["Analyse automatique de l''activité des étudiants dans git","Identification des étudiants à risque","Vérification de la participation des étudiants","Analyse de l''activité en classe, travaux de laboratoire et projets","Visualisation des étudiants qui ont complété des travaux de laboratoire ou contribuent activement"],"de":["Automatisierte Analyse der Studentenaktivität in git","Identifizierung von gefährdeten Studenten","Überprüfung der Teilnahme der Studenten","Analyse der Aktivität im Unterricht, Laborarbeiten und Projekten","Visualisierung der Studenten, die Laborarbeiten abgeschlossen haben oder aktiv beitragen"],"pt":["Automatização da análise de atividade de git dos estudantes","Verificação de participação estudantil","Identificação de estudantes em risco","Análise de lab submissions e project work","Integração com ferramentas de IA para melhorar a eficiência"],"ru":["Автоматизация анализа активности студентов в git","Проверка участия студентов","Определение студентов, находящихся в группе риска","Анализ лабораторных работ и проектов","Интеграция с ИИ агентами для повышения эффективности"],"ar":["تحليل تلقائي لنشاط جيت للطلاب","تحقق من مشاركة الطلاب","تحديد الطلاب المعرضين للخطر","تحليل أعمال المعمل وال مشاريع","التكامل مع أدوات الذكاء الاصطناعي لتحسين الكفاءة"]},"keywords":{"en":["how to use student-activity-analysis","student-activity-analysis setup guide","automated git activity analysis","student-activity-analysis alternative","student-activity-analysis vs manual tracking","student-activity-analysis install","what is student-activity-analysis","student-activity-analysis for educators","student-activity-analysis benefits"],"zh":["学生活动分析工具","Git 活动分析","教学效率","学生进度","学生参与","自动化分析","教育技术","AI 教育工具","学生活动分析软件"],"ja":["学生活動分析 AIエージェント","Git 活動分析","教學の効率","学生の進度","学生の参加","自動分析","教育技術","AI 教育ツール","学生活動分析ソフトウェア"],"ko":["학생 활동 분석 툴","Git 활동 분석","교학效率","학생 진행 상황","학생 참여도","자동화 분석","교육 기술","AI 교육 도구","학생 활동 분석 소프트웨어"],"es":["análisis de actividad estudiantil","herramienta de IA para educación","automatización de análisis de git","identificación de estudiantes en riesgo","participación de los estudiantes","análisis de clase y proyectos","visualización de datos de estudiantes","educación con tecnología"],"fr":["analyse d''activité étudiante","outil IA pour l''éducation","automatisation de l''analyse de git","identification des étudiants à risque","participation des étudiants","analyse de classe et de projets","visualisation des données des étudiants","éducation avec technologie"],"de":["Studentenaktivitätsanalyse","KI-Tool für Bildung","Automatisierung der Analyse von git","Identifizierung von gefährdeten Studenten","Teilnahme der Studenten","Analyse von Unterricht und Projekten","Visualisierung von Schülerdaten","Bildung mit Technologie"],"pt":["análise de atividade estudantil","ferramentas de IA para educação","automação de análise de git","engenharia de software","participação estudantil","estudantes em risco","lab submissions","project work"],"ru":["анализ студенческой активности","ИИ агенты для образования","автоматизация анализа git","программная инженерия","участие студентов","студенты в группе риска","лабораторные работы","проекты"],"ar":["تحليل نشاط الطلاب","أدوات الذكاء الاصطناعي للتعليم","تحليل تلقائي لجيت","هندسة البرمجيات","مشاركة الطلاب","الطلاب المعرضون للخطر","أعمال المعمل","المشاريع"]}},"owner":"nibzard","repo":"2025-intro-swe","repoPath":"nibzard/2025-intro-swe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"student-activity-analysis","description":"Analyze student git activity, lab submissions, and project work for software engineering courses. Use when asked to update student analysis, check student activity, analyze the class, or when working with student rosters and git repositories. Handles inconsistencies in student behavior like multiple usernames, name variations, and missing data.","bodyPreview":"# Student Activity Analysis Skill\n\n## When to Use This Skill\n\nInvoke this skill when the user:\n- Asks to \"update the student activity analysis\"\n- Asks \"how are students doing?\" or \"check student progress\"\n- Mentions checking class activity, lab submissions, or project work\n- Wants to see who has completed labs or is actively contributing\n- Needs to verify student participation or identify at-risk students\n\n## Overview\n\nThis skill automates the analysis of student git activity in a software engin","body":"# Student Activity Analysis Skill\n\n## When to Use This Skill\n\nInvoke this skill when the user:\n- Asks to \"update the student activity analysis\"\n- Asks \"how are students doing?\" or \"check student progress\"\n- Mentions checking class activity, lab submissions, or project work\n- Wants to see who has completed labs or is actively contributing\n- Needs to verify student participation or identify at-risk students\n\n## Overview\n\nThis skill automates the analysis of student git activity in a software engineering course. It reads from a canonical student roster (OFFICIAL_STUDENT_ROSTER.json), queries git history, checks file systems, and generates a comprehensive markdown report (STUDENT_ACTIVITY_ANALYSIS.md).\n\n## Step-by-Step Instructions\n\n### Step 0: Sync with Main Branch (CRITICAL)\n\n**Always start by syncing with the main branch** to ensure you''re analyzing the latest activity:\n\n```bash\ngit fetch origin main\ngit merge origin main -m \"Sync with main before analysis\"\n```\n\n⚠️ **Why this is critical:** Without syncing, you may miss up to 76% of student activity that exists on the main branch but not on your current branch.\n\n### Step 1: Collect Activity Data\n\nRun the data collection script:\n\n```bash\npython3 .claude/skills/student-activity-analysis/collect_data.py\n```\n\nThis script will:\n- Read OFFICIAL_STUDENT_ROSTER.json\n- Query git logs for each student (handling multiple usernames)\n- Check lab01 completion (intro.py files)\n- Check lab03 folders\n- Analyze project folder activity\n- Generate STUDENT_ACTIVITY_DATA.json\n\n### Step 2: Generate Report\n\nRun the report generation script:\n\n```bash\npython3 .claude/skills/student-activity-analysis/generate_report.py\n```\n\nThis script will:\n- Read STUDENT_ACTIVITY_DATA.json\n- Generate formatted markdown tables\n- Calculate statistics\n- Write to STUDENT_ACTIVITY_ANALYSIS.md\n\n### Step 3: Review and Commit\n\nReview the generated report and commit if everything looks good:\n\n```bash\ngit add STUDENT_ACTIVITY_ANALYSIS.md STUDENT_ACTIVITY_DATA.json\ngit commit -m \"Update student activity analysis - $(date +%Y-%m-%d)\"\ngit push -u origin <branch-name>\n```\n\n## Handling Edge Cases\n\nThe real world is messy. Students don''t always follow instructions perfectly. This skill is designed to handle common inconsistencies:\n\n### Edge Case 1: Multiple GitHub Usernames\n\n**Problem:** A student may have multiple GitHub usernames or commit under different names.\n\n**Example from roster:**\n```json\n\"github_username\": \"jcuzic/Zlicone\"\n```\n\n**Solution:** Split on \"/\" and query git with all usernames:\n```bash\ngit log --all --author=\"jcuzic\\|Zlicone\" --oneline | wc -l\n```\n\n### Edge Case 2: Name Variations and Diacritics\n\n**Problem:** Student names in folders may not match roster exactly due to diacritics or spelling.\n\n**Roster:** \"Stipe Ćubelić\"\n**Folder:** `students/lab03/scubelic/`\n\n**Solution:** Use fuzzy matching when checking for folders:\n- Convert names to lowercase\n- Remove diacritics (ć→c, š→s, ž→z)\n- Check for partial matches\n\n### Edge Case 3: Lab Submissions in Wrong Location\n\n**Problem:** Student may create intro.py in the wrong directory.\n\n**Expected:** `students/<github_username>/intro.py`\n**Actual:** `students/intro.py` or `students/lab01/<name>/intro.py`\n\n**Solution:** Search entire students/ directory:\n```bash\nfind students/ -name \"intro.py\" -type f\n```\n\nThen manually verify which file belongs to which student.\n\n### Edge Case 4: Stale or Orphaned Project Folders\n\n**Problem:** Project folders exist but no students in roster claim them.\n\n**Examples:**\n- `projects/garderoba/` (no team registered)\n- `projects/climate-analyzers-asmith-bjohnson/` (demo data?)\n\n**Solution:**\n- List all projects in report\n- Mark unmatched folders as \"Unknown Team\"\n- Show commit count to help identify ownership\n\n### Edge Case 5: Team Lead with No Commits\n\n**Problem:** Student is listed as project lead but has 0 commits in project folder.\n\n**Possible reasons:**\n- Commits under different username\n- Work done in different branch\n- Administrative lead (not technical)\n\n**Solution:**\n- Mark as \"Lead Only - Verify\" status\n- Manually review git log for project folder\n- Check if commits exist under alternative username\n\n## Validation and Error Handling\n\nBefore finalizing the report, validate:\n\n1. **Student count matches:** Number of students in report = Number in roster\n2. **No missing projects:** All project folders are accounted for\n3. **Date ranges make sense:** First commit < Last commit\n4. **Status classifications are consistent:**\n   - \"Very Active\" = 15+ commits\n   - \"Active\" = 5-14 commits\n   - \"Low Activity\" = 2-4 commits\n   - \"Minimal Activity\" = 1 commit\n   - \"No Git Activity\" = 0 commits\n\nIf validation fails:\n- Report the discrepancy\n- Show which students/projects are problematic\n- Ask user if manual review is needed\n\n## Output Format\n\nThe generated STUDENT_ACTIVITY_ANALYSIS.md should include:\n\n1. **Overview Statistics**\n   - Total students (from roster)\n   - Students with activity\n   - Activity percentage\n\n2. **Student Activity Table**\n   - ALL students (even those with 0 commits)\n   - Sorted by activity level (most active first)\n   - Columns: Name, GitHub, Commits, Status, Lab01, Lab03, Project Role\n   - NO email addresses (kept in JSON only)\n\n3. **Project Teams Table**\n   - ALL project folders\n   - Columns: Project, Total Commits, Team Lead, Status\n   - Include \"Unknown\" projects\n\n4. **Recommendations**\n   - Students needing attention (0 commits)\n   - Positive highlights (very active students)\n\n## Testing the Skill\n\nTo test this skill manually:\n\n1. Create a test branch\n2. Invoke the skill\n3. Verify output contains all 52 students\n4. Check that statistics add up correctly\n5. Manually verify a few commit counts with `git log`\n\n## Troubleshooting\n\n**Q: Script says \"OFFICIAL_STUDENT_ROSTER.json not found\"**\nA: Make sure you''re in the repository root directory `/home/user/2025-intro-swe/`\n\n**Q: Git log shows no commits for a student I know has commits**\nA: Check if they have multiple GitHub usernames. Update roster with \"username1/username2\" format.\n\n**Q: Student has intro.py but script doesn''t detect it**\nA: Check the file path. Script searches entire students/ directory but may need manual verification.\n\n**Q: Project folder exists but not in any team''s project_folder field**\nA: This is an orphaned project. Script will mark it as \"Unknown Team\" - may need manual investigation.\n\n## Files Managed by This Skill\n\n- **OFFICIAL_STUDENT_ROSTER.json** (READ ONLY - never modified by scripts)\n- **STUDENT_ACTIVITY_DATA.json** (Generated by collect_data.py)\n- **STUDENT_ACTIVITY_ANALYSIS.md** (Generated by generate_report.py)\n\n## Key Lessons Learned\n\n1. **Always sync with main first** - Missing this step caused 76% of activity to be missed initially\n2. **Include ALL enrolled students** - Even those with 0 activity need to be in the report\n3. **Separate static from dynamic data** - Roster is manual, activity data is automated\n4. **Handle real-world messiness** - Students use multiple usernames, misspell names, put files in wrong places\n5. **Make it deterministic** - Same git state should produce same report every time\n"},"lastSynced":"2026-03-08T02:03:46.754Z","agentAnalysis":{"suitability":{"en":"Ideal for Education-focused AI Agents requiring automated student progress tracking and git activity analysis.","zh":"适用于需要自动跟踪学生进度和git活动分析的教育类AI代理。","ja":"教育に特化したAIエージェントが学生の進度を自動追跡し、gitのアクティビティを分析するのに適しています。","ko":"학생 진행 상황을 자동으로 추적하고 git 활동을 분석해야 하는 교육 중심의 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA con enfoque en educación que requieren un seguimiento automatizado del progreso de los estudiantes y análisis de actividad de git.","fr":"Idéal pour les agents d''IA axés sur l''éducation nécessitant un suivi automatique des progrès des étudiants et une analyse d''activité de git.","de":"Ideal für bildungsorientierte KI-Agents, die ein automatisiertes Verfolgen des Studentenfortschritts und eine Git-Aktivitätsanalyse erfordern.","pt":"Ideal para Agentes de IA com foco em Educação que exigem acompanhamento automático do progresso dos estudantes e análise de atividade git.","ru":"Идеально для образовательных агентов ИИ, требующих автоматизированного отслеживания прогресса студентов и анализа активности git.","ar":"مثالي لعميل الذكاء الاصطناعي ذي التركيز على التعليم الذي يتطلب تتبع تقدم الطلاب الآلي وتحليل النشاط جيت."},"recommendation":{"en":"Empowers agents to analyze student git activity, providing valuable insights into class participation, lab submissions, and project work using git protocols and data visualization techniques, enabling educators to identify at-risk students and areas of improvement.","zh":"赋予代理分析学生的git活动的能力，提供有关课堂参与、实验提交和项目工作的有价值的见解，使用git协议和数据可视化技术，使教育者能够识别处于风险中的学生和改进领域。","ja":"エージェントが学生のgitアクティビティを分析し、gitプロトコルとデータ可視化技術を使用して、クラス参加、実験提出、プロジェクト作業に関する貴重な洞察を提供し、教育者がリスクにある学生や改善すべき分野を特定できるようにします。","ko":"에이전트가 학생의 git 활동을 분석하여 git 프로토콜 및 데이터 시각화 기술을 사용하여 수업 참여, 실험 제출, 프로젝트 작업에 대한贵重한 통찰력을 제공하여 교사들이 위험에 처한 학생이나 개선해야 할 영역을 식별할 수 있도록 합니다.","es":"Habilita a los agentes a analizar la actividad de git de los estudiantes, proporcionando información valiosa sobre la participación en clase, las presentaciones de laboratorio y el trabajo de proyectos utilizando protocolos de git y técnicas de visualización de datos, lo que permite a los educadores identificar a los estudiantes en riesgo y áreas de mejora.","fr":"Permet aux agents d''analyser l''activité de git des étudiants, fournissant des informations précieuses sur la participation en classe, les soumissions de laboratoire et les travaux de projet en utilisant les protocoles de git et les techniques de visualisation de données, permettant ainsi aux éducateurs d''identifier les étudiants à risque et les domaines d''amélioration.","de":"Ermächtigt die Agents, die Git-Aktivität der Studenten zu analysieren und wertvolle Einblicke in die Klassenbeteiligung, Laborabgaben und Projektarbeiten unter Verwendung von Git-Protokollen und Datenvisualisierungstechniken zu liefern, um den Lehrkräften die Identifizierung von Studenten in Gefahr und Verbesserungsbereichen zu ermöglichen.","pt":"Habilita os agentes a analisar a atividade git dos estudantes, fornecendo insights valiosos sobre a participação da classe, envios de laboratório e trabalhos de projeto usando protocolos git e técnicas de visualização de dados, permitindo que os educadores identifiquem estudantes em risco e áreas de melhoria.","ru":"Наделяет агентов возможностью анализировать активность git студентов, предоставляя ценную информацию о участии в классе, лабораторных заданиях и проектных работах с использованием git-протоколов и методов визуализации данных, позволяя педагогам выявлять студентов, находящихся в группе риска, и области для улучшения.","ar":"تمكّن الوكيل من تحليل نشاط جيت للطلاب، وتقديم رؤى قيمة حول مشاركة الفصل وإرسال مختبرات وأعمال المشروع باستخدام بروتوكولات جيت وتقنيات تمثيل البيانات، مما يسمح للمعلمين تحديد الطلاب المعرضين للخطر ومناطق التحسين."},"useCases":{"en":["Automating student progress updates","Identifying at-risk students through git activity analysis","Analyzing class participation and lab submissions","Tracking project work and contributions","Verifying student participation and engagement"],"zh":["自动更新学生进度","通过git活动分析识别处于风险中的学生","分析课堂参与和实验提交","跟踪项目工作和贡献","验证学生参与和互动"],"ja":["学生の進度を自動更新する","gitアクティビティ分析を使用してリスクにある学生を特定する","クラス参加と実験提出を分析する","プロジェクト作業と貢献を追跡する","学生の参加とエンゲージメントを確認する"],"ko":["학생 진행 상황을 자동으로 업데이트하는 것","git 활동 분석을 통해 위험에 처한 학생을 식별하는 것","수업 참여와 실험 제출을 분석하는 것","프로젝트 작업과 기여를 추적하는 것","학생의 참여와 참여도를 확인하는 것"],"es":["Automatizar las actualizaciones del progreso de los estudiantes","Identificar a los estudiantes en riesgo a través del análisis de la actividad de git","Analizar la participación en clase y las presentaciones de laboratorio","Seguir el trabajo de proyectos y las contribuciones","Verificar la participación y el compromiso de los estudiantes"],"fr":["Automatiser les mises à jour des progrès des étudiants","Identifier les étudiants à risque grâce à l''analyse de l''activité de git","Analyser la participation en classe et les soumissions de laboratoire","Suivre les travaux de projet et les contributions","Vérifier la participation et l''engagement des étudiants"],"de":["Automatisieren der Studentenfortschritts-Updates","Identifizierung von Studenten in Gefahr durch Git-Aktivitätsanalyse","Analyse der Klassenbeteiligung und Laborabgaben","Verfolgen der Projektarbeiten und Beiträge","Überprüfen der Studentenbeteiligung und des Engagements"],"pt":["Automatizar atualizações de progresso dos estudantes","Identificar estudantes em risco por meio da análise de atividade git","Analizar a participação da classe e envios de laboratório","Acompanhar trabalhos de projeto e contribuições","Verificar a participação e engajamento dos estudantes"],"ru":["Автоматизировать обновления прогресса студентов","Определить студентов, находящихся в группе риска, с помощью анализа активности git","Анализировать участие в классе и лабораторные задания","Отслеживать проектные работы и вклад","Проверять участие и вовлеченность студентов"],"ar":["تأتمة تحديثات تقدم الطلاب","تحديد الطلاب المعرضين للخطر من خلال تحليل النشاط جيت","تحليل مشاركة الفصل وإرسال مختبرات","تتبع أعمال المشروع والمساهمات","التحقق من مشاركة الطلاب والالتزام"]},"limitations":{"en":["Requires access to student git activity data","Limited to software engineering education context","Needs integration with git version control systems"],"zh":["需要访问学生的git活动数据","仅限于软件工程教育背景","需要与git版本控制系统集成"],"ja":["学生のgitアクティビティデータへのアクセスが必要","ソフトウェアエンジニアリング教育のコンテキストのみ","gitバージョン管理システムとの統合が必要"],"ko":["학생의 git 활동 데이터에 접근할 수 있어야 함","소프트웨어 공학 교육 컨텍스트에만 국한됨","git 버전 관리 시스템과 통합해야 함"],"es":["Requiere acceso a los datos de actividad de git de los estudiantes","Limitado al contexto de la educación en ingeniería de software","Necesita integración con sistemas de control de versiones de git"],"fr":["Nécessite un accès aux données d''activité de git des étudiants","Limité au contexte de l''éducation en ingénierie logicielle","Nécessite une intégration avec les systèmes de contrôle de version de git"],"de":["Erfordert Zugriff auf die Git-Aktivitätsdaten der Studenten","Begrenzt auf den Kontext der Software-Engineering-Ausbildung","Benötigt Integration mit Git-Versionierungssystemen"],"pt":["Exige acesso aos dados de atividade git dos estudantes","Limitado ao contexto da educação em engenharia de software","Necessita de integração com sistemas de controle de versão git"],"ru":["Требует доступа к данным активности git студентов","Ограничен контекстом образования в области программной инженерии","Требует интеграции с системами контроля версий git"],"ar":["يتطلب الوصول إلى بيانات النشاط جيت للطلاب","محدود بالسياق التعليمي للهندسة البرمجية","يحتاج إلى التكامل مع أنظمة التحكم بالإصدار جيت"]},"version":4},"contentHash":"1f1b1bb3a8c4d6fe1ca7f667e40b26b92eab59496c4158b572b485e7077aff7e","qualityScore":51}');
