INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('terrylica/gapless-network-data/vm-infrastructure-ops', 'vm-infrastructure-ops', 'terrylica', 'gapless-network-data', 'community', 'vm-infrastructure-ops terrylica gapless-network-data community The vm-infrastructure-ops skill helps developers troubleshoot and manage GCP e2-micro VMs running eth-realtime-collector, ensuring real-time data stream collection for Ethereum, Bitcoin, and Solana blockchain networks. vm-infrastructure-ops技能用于故障排除和管理GCP e2-micro VM，运行eth-realtime-collector，支持Ethereum、Bitcoin、Solana vm-infrastructure-opsスキルは、GCP e2-micro VMのトラブルシューティングと管理に使用され、eth-realtime-collectorを実行し、Ethereum、Bitcoin、Solanaをサポートします vm-infrastructure-ops스킬은 GCP e2-micro VM의 트러블슈ーティング과 관리에 사용되며 eth-realtime-collector를 실행하며 Ethereum, Bitcoin, Solana를 지원합니다 vm-infrastructure-ops es una habilidad para recopilar métricas de blockchain de Ethereum, Bitcoin y Solana con garantía de cero brechas vm-infrastructure-ops est une compétence pour collecter des métriques de blockchain d''Ethereum, Bitcoin et Solana avec garantie de zéro rupture vm-infrastructure-ops ist eine Fähigkeit zur Sammlung von Blockchain-Metriken von Ethereum, Bitcoin und Solana mit Garantie auf Null-Unterbrechung O vm-infrastructure-ops é uma habilidade que coleta métricas de redes blockchain multi-chain com garantia de zero-gap, suportando Ethereum, Bitcoin e Solana. ИИ Агент vm-infrastructure-ops - это навык, который собирает метрики многоцепочных блокчейн-сетей с гарантией нулевого разрыва, поддерживающий Ethereum, Bitcoin и Solana. vm-infrastructure-ops هو مهارة تقوم بجمع معايير شبكات البلوكشين متعددة السلاسل مع ضمان عدم وجود فجوات، تدعم Ethereum و Bitcoin و Solana. how to use vm-infrastructure-ops vm-infrastructure-ops setup guide vm-infrastructure-ops alternative vm-infrastructure-ops vs blockchain monitoring tools troubleshooting GCP e2-micro VM multi-chain blockchain network metrics collection zero-gap guarantee blockchain data vm-infrastructure-ops install vm-infrastructure-ops for Ethereum and Bitcoin vm-infrastructure-ops GCP e2-micro VM eth-realtime-collector 多链区块链网络指标收集 零间隙保证 systemd journalctl gcloud compute AIエージェント Collects multi-chain blockchain network metrics with zero-gap guarantee for Ethereum, Bitcoin, and Solana Troubleshoots GCP e2-micro VM issues using systemd and journalctl Resolves real-time data stream issues with ClickHouse Manages VM network issues and DNS resolution failures Provides service status checks and log viewing capabilities using gcloud compute vm-infrastructure-ops is a skill for collecting multi-chain blockchain network metrics with a zero-gap guarantee, supporting Ethereum, Bitcoin, and Solana, and troubleshooting GCP e2-micro VM issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tolluset/local-review/api-designer', 'community', 'tolluset', 'local-review', 'tolluset/local-review', 'api-designer', 0, 0, 51, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:52.129Z', '1615f280be638223f3a3529e7067e05dabb08fc2f2a948e9239b8ba647a595dc', '{"id":"tolluset/local-review/api-designer","name":"api-designer","description":{"en":"The api-designer skill is a simple code reviewer for backend developers, providing a set of RESTful API design principles and guidelines for implementing APIs.","zh":"API 设计师技能是设计和实现 RESTful API 的关键，包括 GET、POST、PATCH、PUT 和 DELETE 方法","ja":"API デザイナースキルは、RESTful API を設計および実装するための重要なスキルです","ko":"API 디자이너 스킬은 RESTful API를 설계하고 구현하는 데 중요한 스킬입니다","es":"El skill API Designer es una herramienta para desarrolladores que facilita el diseño y la implementación de APIs RESTful, siguiendo principios de diseño y formatos de respuesta estándar","fr":"L''outil API Designer est un outil pour les développeurs qui facilite la conception et la mise en œuvre d''API RESTful, en suivant les principes de conception et les formats de réponse standard","de":"Der Skill API Designer ist ein Tool für Entwickler, das das Entwerfen und Implementieren von RESTful-APIs erleichtert, indem es Designprinzipien und Antwortformate standardmäßig einhält","pt":"O API Designer é uma ferramenta para desenvolvedores backend que desejam criar APIs RESTful eficientes. Ele fornece um conjunto de regras e padrões para garantir a consistência e escalabilidade das APIs.","ru":"ИИ Агент API Designer - это инструмент для разработчиков backend, которые хотят создавать эффективные RESTful API. Он предоставляет набор правил и стандартов для обеспечения согласованности и масштабируемости API.","ar":"مصمم واجهة برمجة التطبيقات هو أداة للمطورين الخلفية الذين يرغبون في إنشاء واجهات برمجة التطبيقات RESTful فعالة. إنه يوفر مجموعة من القواعد والمعايير لضمان الاتساق والتماسك لواجهات برمجة التطبيقات."},"seo":{"title":{"en":"api-designer: RESTful API Setup Guide | AI Agent Skill","zh":"API 设计师技能：RESTful API 设计最佳实践","ja":"API デザイナースキル：RESTful API の設計ガイド","ko":"API 디자이너 스킬: RESTful API 설계 가이드","es":"Guía de configuración de API Designer para desarrolladores","fr":"Configurer l''outil API Designer pour les développeurs","de":"API Designer Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do API Designer: Melhores Práticas p...","ru":"Настройка ИИ Агента API Designer: Руководство для Разрабо...","ar":"دليل تنصيب مصمم واجهة برمجة التطبيقات: إرشادات أفضل للمطورين"},"description":{"en":"Discover how api-designer simplifies RESTful API design with predefined path patterns and response formats, try it now and streamline your backend development","zh":"了解 API 设计师技能，掌握 RESTful API 设计原则和方法，包括 GET、POST、PATCH、PUT 和 DELETE","ja":"API デザイナースキルを学び、RESTful API の設計原則と方法をマスターしてください","ko":"API 디자이너 스킬을 배우고 RESTful API 설계 원칙과 방법을 익혀보세요","es":"Aprende a diseñar y implementar APIs RESTful con el skill API Designer, incluyendo principios de diseño y formatos de respuesta","fr":"Découvrez comment concevoir et mettre en œuvre des API RESTful avec l''outil API Designer, y compris les principes de conception et les formats de réponse","de":"Erfahren Sie, wie Sie mit dem Skill API Designer RESTful-APIs entwerfen und implementieren, einschließlich Designprinzipien und Antwortformaten","pt":"Aprenda a configurar e implementar o API Designer com eficiência, seguindo as melhores práticas de design de API RESTful","ru":"Узнайте, как настроить и реализовать ИИ Агент API Designer, следуя лучшим практикам проектирования RESTful API","ar":"تعرف على كيفية تثبيت وتطبيق مصمم واجهة برمجة التطبيقات بفعالية، باتباع أفضل الممارسات لتصميم واجهة برمجة التطبيقات RESTful"},"definition":{"en":"api-designer is a skill that assists backend developers in designing and implementing RESTful APIs using predefined rules and response form