INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryok/team-operations/google-drive', 'google-drive', 'ryok', 'team-operations', 'community', 'google-drive ryok team-operations community The google-drive skill enables AI agents to perform Google Drive operations using gogcli, benefiting developers who need to manage files and search for specific data. 使用gogcli进行Google Drive操作，包括文件列表、搜索和管理。支持多种命令和参数 gog CLIを使用してGoogle Driveを操作する方法。ファイルリスト、検索、管理などをサポート gogcli를 이용하여 Google Drive를 운영하는 방법. 파일 목록, 검색, 관리 등을 지원합니다 gogcli es una herramienta de línea de comandos para interactuar con Google Drive. Permite autenticación, listado de archivos y búsqueda de archivos. gogcli est un outil en ligne de commande pour interagir avec Google Drive. Il permet l''authentification, la liste de fichiers et la recherche de fichiers. gogcli ist ein Kommandozeilen-Tool für die Interaktion mit Google Drive. Es ermöglicht die Authentifizierung, die Auflistung von Dateien und die Suche nach Dateien. O gogcli é uma ferramenta de linha de comando para operar o Google Drive, permitindo listagem de arquivos e busca por pastas Gogcli - это консольная утилита для работы с Google Drive, позволяющая перечислять файлы и искать папки gogcli هو أداة سطر أوامر للتشغيل مع محرك جوجل، يسمح بقائمة الملفات والبحث عن المجلدات how to use google-drive what is google-drive google-drive alternative google-drive vs dropbox google-drive install google-drive setup guide gogcli commands google drive file management Google Drive gogcli 命令行工具 文件操作 文件管理 搜索 列表 认证 登录 Lists files in the root folder using the gog drive ls command Supports searching for files using the gog drive search command with full-text queries Allows for filtering files by mime type using the --query flag Enables authentication with Google Drive using the gog auth login command Supports specifying the parent folder ID using the --parent flag Allows for limiting the number of results using the --max flag google-drive is a command-line interface for interacting with Google Drive using gogcli, allowing for file listing, searching, and management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DevChiJay/next-claude/use-modern-browser-apis', 'community', 'DevChiJay', 'next-claude', 'DevChiJay/next-claude', 'use-modern-browser-apis', 0, 0, 51, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.122Z', 'a7275320c6d85b1b7d7dd17cf3f6e89e0803d08e5ceb58c512b591852251afa7', '{"id":"DevChiJay/next-claude/use-modern-browser-apis","name":"use-modern-browser-apis","description":{"en":"The use-modern-browser-apis skill enables developers to utilize native, modern browser APIs for simplified logic and improved performance. It benefits developers who prefer standardized and widely supported APIs over heavy external libraries.","zh":"使用现代浏览器API来简化逻辑、提高性能和减少包大小，推荐使用浏览器原生能力而不是第三方依赖","ja":"モダンブラウザAPIを使用してロジックを簡素化し、パフォーマンスを向上させ、バンドルサイズを削減します。ブラウザ原生能力を第三パーティ依存よりも優先します","ko":"모던 브라우저 API를 사용하여 로직을 단순화하고 성능을 향상시키고 번들 크기를 줄입니다. 브라우저 네이티브 기능을 第三方 의존보다 선호합니다","es":"Esta habilidad se centra en el uso de API de navegador modernas para simplificar la lógica y mejorar el rendimiento","fr":"Cette compétence se concentre sur l''utilisation des API de navigateur modernes pour simplifier la logique et améliorer les performances","de":"Diese Fähigkeit konzentriert sich auf die Verwendung moderner Browser-APIs, um Logik zu vereinfachen und Leistung zu verbessern","pt":"Use APIs modernas de navegador para simplificar a lógica e melhorar o desempenho","ru":"Используйте современные браузерные API для упрощения логики и улучшения производительности","ar":"استخدم واجهات برمجة التطبيقات الحديثة للمتصفح لتبسيط المنطق وتحسين الأداء"},"seo":{"title":{"en":"use-modern-browser-apis: Simplify Logic with Native APIs ...","zh":"使用现代浏览器API：开发指南","ja":"モダンブラウザAPIの使用: ベストプラクティス","ko":"모던 브라우저 API 사용 가이드","es":"Guía de configuración para usar API modernas de navegador","fr":"Guide de mise en route des API de navigateur modernes","de":"Einrichtungsleitfaden für moderne Browser-APIs","pt":"Guia de Configuração para Uso de APIs Modernas de Navegador","ru":"Настройка современных браузерных API: лучшие практики для...","ar":"إعداد استخدام واجهات برمجة التطبيقات الحديثة للمتصفح"},"description":{"en":"Discover how to leverage modern browser APIs for improved performance and reduced bundle size. Learn to use promise-based and async APIs for a seamless exper...","zh":"了解如何使用现代浏览器API来简化逻辑、提高性能和减少包大小，AIエージェント","ja":"モダンブラウザAPIを使用してロジックを簡素化し、パフォーマンスを向上させ、バンドルサイズを削減する方法を学びましょう、AIエージェント","ko":"모던 브라우저 API를 사용하여 로직을 단순화하고 성능을 향상시키고 번들 크기를 줄이는 방법을 알아보세요, AI Tools","es":"Aprende a utilizar API de navegador modernas para simplificar la lógica, mejorar el rendimiento y reducir el tamaño de la carga","fr":"Découvrez comment utiliser les API de navigateur modernes pour simplifier la logique, améliorer les performances et réduire la taille de la charge","de":"Erfahren Sie, wie Sie moderne Browser-APIs verwenden, um Logik zu vereinfachen, Leistung zu verbessern und die Bundle-Größe zu reduzieren","pt":"Aprenda a utilizar APIs modernas de navegador para simplificar a lógica, melhorar o desempenho e reduzir o tamanho do pacote","ru":"Узнайте, как использовать современные браузерные API для упрощения логики, улучшения производительности и уменьшения размера пакета для ИИ Агентов","ar":"تعلم كيفية استخدام واجهات برمجة التطبيقات الحديثة للمتصفح لتبسيط المنطق وتحسين الأداء وتقليل حجم الحزمة"},"definition":{"en":"use-modern-browser-apis is a skill that promotes the use of native, modern browser APIs to simplify logic, improve performance, and reduce bundle size.","zh":"现代浏览器API是指标准化、广泛支持和高效的浏览器原生API","ja":"モダンブラウザAPIとは、標準化された、広くサポートされている、高度なブラウザ原生APIのこと","ko":"모던 브라우저 API는 표준화된 광범위하게 지원되고 고성능인 브라우저 네이티브 API를 말합니다","es":"Uso de API de navegador modernas para simplificar la lógica y mejorar el rendimiento","fr":"Utilisation des API de navigateur modernes pour simplifier la logique et améliorer les performances","de":"Verwendung moderner Browser-APIs, um Logik zu vereinfachen und Leistung zu verbessern","pt":"Uso de APIs modernas de navegador para desenvolver aplicações web eficientes","ru":"Использование современных браузерных API для разработки эффективных веб-приложений для ИИ Агентов","ar":"استخدام واجهات برمجة التطبيقات الحديثة للمتصفح لتطوير تطبيقات ويب فعالة"},"features":{"en":["Utilizes standardized and widely supported browser-native capabilities","Provides sensible fallbacks for APIs that aren’t available in all clients via progressive enhancement","Employs promise-based and async APIs for secure and efficient data handling","Reduces bundle size by minimizing reliance on heavy external libraries","Improves performance through optimized use of modern browser APIs","Supports simplified logic for enhanced developer productivity"],"zh":["使用浏览器原生能力","提供进步式增强的fallback","使用Promise-based和安全的API","简化逻辑和提高性能","减少包大小"],"ja":["ブラウザ原生能力を使用する","プログレッシブエンハンスのfallbackを提供する","Promise-basedと安全なAPIを使用する","ロジックを簡素化し、パフォーマンスを向上させる","バンドルサイズを削減する"],"ko":["브라우저 네이티브 기능을 사용","진보적인增强의fallback을 제공","Promise-based와 안전한 API를 사용","로직을 단순화하고 성능을 향상","번들 크기를 줄임"],"es":["Preferencia por capacidades nativas del navegador sobre dependencias de terceros","Implementación de mejoras progresivas para APIs no disponibles en todos los clientes","Uso de API basadas en promesas y seguras","Reducción del tamaño de la carga y mejora del rendimiento","Simplificación de la lógica y reducción de la complejidad"],"fr":["Préférence pour les capacités natives du navigateur par rapport aux dépendances tierces","Mise en œuvre d''améliorations progressives pour les API non disponibles sur tous les clients","Utilisation d''API basées sur des promesses et sécurisées","Réduction de la taille de la charge et amélioration des performances","Simplification de la logique et réduction de la complexité"],"de":["Bevorzugung von Browser-eigenen Fähigkeiten gegenüber Drittanbieter-Abhängigkeiten","Implementierung von schrittweisen Verbesserungen für APIs, die nicht auf allen Clients verfügbar sind","Verwendung von Promise-basierten und sicheren APIs","Reduzierung der Bundle-Größe und Verbesserung der Leistung","Vereinfachung der Logik und Reduzierung der Komplexität"],"pt":["Uso de capacidades nativas do navegador","Simplificação da lógica","Melhoria do desempenho","Redução do tamanho do pacote","Suporte a promessas e segurança"],"ru":["Использование браузерных возможностей","Упрощение логики","Улучшение производительности","Уменьшение размера пакета","Поддержка промисов и безопасности для ИИ Агентов"],"ar":["استخدام القدرات الأصلية للمتصفح","تبسيط المنطق","تحسين الأداء","تقليل حجم الحزمة","دعم الوعد والأمان"]},"keywords":{"en":["how to use use-modern-browser-apis","what is use-modern-browser-apis","use-modern-browser-apis alternative","use-modern-browser-apis vs polyfills","use-modern-browser-apis setup guide","use-modern-browser-apis install","modern browser APIs tutorial","native browser APIs best practices","use-modern-browser-apis for web development"],"zh":["现代浏览器API","浏览器原生能力","进步式增强","Promise-based","安全API","AIエージェント","开发指南","浏览器API最佳实践"],"ja":["モダンブラウザAPI","ブラウザ原生能力","プログレッシブエンハンス","Promise-based","安全API","AIエージェント","開発ガイド","ブラウザAPIベストプラクティス"],"ko":["모던 브라우저 API","브라우저 네이티브 기능","진보적인增强","Promise-based","안전한 API","AI Tools","개발 가이드","브라우저 API 최적화"],"es":["API de navegador modernas","Herramientas de desarrollo web","Mejora del rendimiento web","Simplificación de la lógica","Reducción del tamaño de la carga","Desarrollo de aplicaciones web","API de navegador","Herramientas de desarrollo de software"],"fr":["API de navigateur modernes","Outils de développement web","Amélioration des performances web","Simplification de la logique","Réduction de la taille de la charge","Développement d''applications web","API de navigateur","Outils de développement de logiciels"],"de":["Moderne Browser-APIs","Webentwicklungstools","Webleistungsverbesserung","Logikvereinfachung","Bundle-Größenreduzierung","Webanwendungsentwicklung","Browser-API","Software-Entwicklungstools"],"pt":["APIs modernas de navegador","desenvolvimento web eficiente","otimização de desempenho","redução de tamanho de pacote","promessas e segurança","guias de configuração","melhores práticas de desenvolvimento"],"ru":["современные браузерные API","эффективное веб-разработка","оптимизация производительности","уменьшение размера пакета","промисы и безопасность для ИИ Агентов","настройка и конфигурация","лучшие практики разработки"],"ar":["واجهات برمجة التطبيقات الحديثة للمتصفح","تطوير ويب فعال","تحسين الأداء","تقليل حجم الحزمة","دعم الوعد والأمان","إعداد وتكوين","أفضل ممارسات التطوير"]}},"owner":"DevChiJay","repo":"next-claude","repoPath":"DevChiJay/next-claude","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"use-modern-browser-apis","description":"Utilize built-in browser APIs (like Popover API, View Transitions etc) instead of building features manually via JavaScript","bodyPreview":"# Using Modern Browser APIs\n\nWe prefer native, modern browser APIs — _standardized, widely supported, and high-leverage_ — to heavy external libraries or custom fallbacks. Use them to simplify logic, improve performance, and reduce bundle size where appropriate.\n\n## Philosophy\n\n- **PREFER** browser-native capabilities over third-party dependencies\n- **PROGRESSIVE ENHANCE**: Always provide sensible fallbacks for APIs that aren’t available in all clients\n- **ASYNC & SECURE**: Use promise-based and","body":"# Using Modern Browser APIs\n\nWe prefer native, modern browser APIs — _standardized, widely supported, and high-leverage_ — to heavy external libraries or custom fallbacks. Use them to simplify logic, improve performance, and reduce bundle size where appropriate.\n\n## Philosophy\n\n- **PREFER** browser-native capabilities over third-party dependencies\n- **PROGRESSIVE ENHANCE**: Always provide sensible fallbacks for APIs that aren’t available in all clients\n- **ASYNC & SECURE**: Use promise-based and secure context APIs for non-blocking, safe access\n\n## Core & Widely Supported APIs\n\nThese APIs are stable, broadly implemented, and useful in everyday applications.\n\n### UI & Interaction\n\n- **Intersection Observer API** — Efficiently detect when elements enter/exit the viewport (lazy loading, infinite scroll).\n- **ResizeObserver API** — React to element size changes without layout thrashing.\n- **PerformanceObserver API** — Observe performance metrics (RUM/perf insights).\n- **BroadcastChannel API** — Cross-tab communication in the same origin.\n\n### Navigation & View Management\n\n- **View Transitions API** — Native, hardware-accelerated transitions between UI states.\n- **URLPattern API** — Declaratively match and parse URLs (helps in routing logic).\n\n### Clipboard & Sharing\n\n- **Clipboard Async API** — Non-blocking, modern clipboard read/write with user consent.\n- **Web Share API Level 2** — Share text, links, files through native device dialogs.\n\n### Files & Persistence\n\n- **File System Access API** — Read/write local files with user permissions.\n- **File Handle & Directory Picker** extensions for batch file/directory selection.\n\n### Concurrency & Scheduling\n\n- **Web Locks API** — Coordinate async access to shared resources (avoid races).\n- **Scheduling API** — Prioritize/background non-essential work to improve responsiveness.\n\n### Workers & Off-Main Thread\n\n- **Web Workers API** — Run scripts off the main thread for intensive tasks.\n- **OffscreenCanvas** — Use canvas rendering in workers for performant graphics/visuals.\n\n### Speech & Accessibility\n\n- **Web Speech API** — Integrate speech recognition and synthesis for accessibility and voice UI.\n\n### Advanced Graphics & Compute\n\n- **WebGPU API** — Low-level GPU access for high-perf rendering and compute workloads (in many browsers; includes Chromium + newer Safari + Firefox support).\n\n### Real-Time & Networking\n\n- **WebRTC** — Real-time peer-to-peer audio/video communication without plugins.\n\n## When to Use & How to Fallback\n\n- **FEATURE DETECTION** is required before use:\n  ```js\n  if (''clipboard'' in navigator) { … }\n  ```\n\nFor APIs not universally supported (e.g., WebGPU), provide a graceful fallback (WebGL or degraded UI).\n\nAlways combine user gesture requirements (e.g., for sharing or clipboard) with permission checks.\n\n## Best Practices\n\n**ASYNC FIRST**: Prefer promise/async APIs to avoid blocking UI.\n\n**PERMISSIONS UI**: Convey clearly to users when the browser will ask for access (files, clipboard, sharing).\n\n**PERFORMANCE MINDFUL**: Observe and prioritize main thread work using PerformanceObserver or Scheduling APIs.\n\n**SECURE CONTEXTS**: Use HTTPS; many APIs require secure contexts to function.\n\n## General Principles\n\nWrite code for browsers as platforms, not just JS engines.\n\nPrefer native semantics (e.g., lazy loading via IntersectionObserver vs manual scroll handlers).\n\nReduce external dependencies where modern browser APIs suffice.\n\nDocument API usage and fallback patterns for maintenance and cross-browser support.\n"},"lastSynced":"2026-03-08T02:03:57.122Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing native browser API integration for simplified logic and improved performance.","zh":"非常适合需要原生浏览器API集成以简化逻辑和提高性能的前端代理。","ja":"ネイティブブラウザAPI統合を必要とするフロントエンドエージェントにとって最適で、ロジックを簡素化し、パフォーマンスを向上させることができます。","ko":"네이티브 브라우저 API 통합이 필요한 프론트엔드 에이전트에게 적합하여 논리를 단순화하고 성능을 개선합니다.","es":"Perfecto para agentes frontend que necesitan integración de API de navegador nativa para lógica simplificada y mejor rendimiento.","fr":"Parfait pour les agents frontend ayant besoin d''une intégration native de l''API de navigateur pour une logique simplifiée et de meilleures performances.","de":"Perfekt für Frontend-Agents, die eine native Browser-API-Integration für vereinfachte Logik und verbesserte Leistung benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de integração de API de navegador nativa para lógica simplificada e desempenho melhorado.","ru":"Идеально для фронтенд-агентов, которым требуется родная интеграция браузерного API для упрощенной логики и повышения производительности.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تكامل واجهة برمجة تطبيقات المتصفح الأصلي لتسجيل منطقي مبسط وتحسين الأداء."},"recommendation":{"en":"Empowers agents to utilize standardized and widely supported browser APIs, reducing reliance on heavy external libraries and improving bundle size, while ensuring progressive enhancement with sensible fallbacks for non-supported clients, and leveraging async and secure promise-based APIs.","zh":"赋予代理使用标准化和广泛支持的浏览器API的能力，减少对重型外部库的依赖，改善包大小，同时确保非支持客户端的渐进增强和合理的回退，并利用异步和安全的基于承诺的API。","ja":"エージェントが標準化されたブラウザAPIを利用できるようにし、外部ライブラリへの依存を減らし、バンドルサイズを縮小しながら、非対応クライアントのための継続的な機能強化と適切なフォールバックを保証し、非同期および安全なPromiseベースのAPIを活用します。","ko":"에이전트가 표준화되고廣泛 지원되는 브라우저 API를 사용할 수 있도록 하여 외부 라이브러리 의존성을 줄이고 번들 크기를 개선하면서 비지원 클라이언트에 대한渐进增强 및 적절한 fallback을 보장하고 비동기 및 보안 Promise 기반 API를 활용할 수 있습니다.","es":"Habilita a los agentes a utilizar API de navegador estandarizadas y ampliamente admitidas, reduciendo la dependencia de bibliotecas externas pesadas y mejorando el tamaño del paquete, al mismo tiempo que garantiza una mejora progresiva con fallbacks sensatos para clientes no compatibles, y aprovecha API basadas en promesas asíncronas y seguras.","fr":"Permet aux agents d''utiliser des API de navigateur standardisées et largement prises en charge, réduisant la dépendance à l''égard de bibliothèques externes lourdes et améliorant la taille du paquet, tout en garantissant une amélioration progressive avec des fallbacks sensés pour les clients non pris en charge, et en exploitant des API basées sur des promesses asynchrones et sécurisées.","de":"Ermächtigt Agenten, standardisierte und weit verbreitete Browser-APIs zu nutzen, reduziert die Abhängigkeit von externen Bibliotheken und verbessert die Bundle-Größe, während gleichzeitig eine progressive Verbesserung mit sinnvollen Fallbacks für nicht unterstützte Clients sichergestellt wird und asynchrone und sichere promise-basierte APIs genutzt werden.","pt":"Habilita os agentes a utilizarem APIs de navegador padronizadas e amplamente suportadas, reduzindo a dependência de bibliotecas externas pesadas e melhorando o tamanho do pacote, garantindo melhoria progressiva com recursos de fallback sensatos para clientes não suportados e aproveitando APIs baseadas em promessas assíncronas e seguras.","ru":"Наделяет агентов возможностью использовать стандартизированные и широко поддерживаемые браузерные API, уменьшая зависимость от тяжелых внешних библиотек и улучшая размер пакета, обеспечивая прогрессивное улучшение с разумными fallback для не поддерживаемых клиентов, и используя асинхронные и безопасные API на основе обещаний.","ar":"تمكّن الوكلاء من استخدام واجهات برمجة تطبيقات المتصفح الموحدة والمعتمدة على نطاق واسع، وتقليل الاعتماد على المكتبات الخارجية الثقيلة وتحسين حجم الحزمة، مع ضمان تحسين تدريجي مع إمكانيات fallback معقولة للعملاء غير المدعومين، واستخدام واجهات برمجة تطبيقات قائمة على وعد آمنة ومتزامنة."},"useCases":{"en":["Simplifying browser logic with native APIs","Improving web application performance by reducing external library dependencies","Enhancing security with async and secure promise-based APIs"],"zh":["使用原生API简化浏览器逻辑","通过减少外部库依赖来提高Web应用程序性能","使用异步和安全的Promise基于API来增强安全性"],"ja":["ネイティブAPIを使用してブラウザロジックを簡素化する","外部ライブラリへの依存を減らしてWebアプリケーションのパフォーマンスを向上させる","非同期および安全なPromiseベースのAPIを使用してセキュリティを強化する"],"ko":["네이티브 API를 사용하여 브라우저 논리를 단순화한다","외부 라이브러리 의존성을 줄여 웹 애플리케이션 성능을 개선한다","비동기 및 보안 Promise 기반 API를 사용하여 보안을 강화한다"],"es":["Simplificar la lógica del navegador con API nativas","Mejorar el rendimiento de las aplicaciones web reduciendo las dependencias de bibliotecas externas","Mejorar la seguridad con API basadas en promesas asíncronas y seguras"],"fr":["Simplifier la logique du navigateur avec des API natives","Améliorer les performances des applications web en réduisant les dépendances aux bibliothèques externes","Améliorer la sécurité avec des API basées sur des promesses asynchrones et sécurisées"],"de":[" Vereinfachen der Browserlogik mit nativen APIs","Verbesserung der Webanwendungsleistung durch Reduzierung der Abhängigkeit von externen Bibliotheken","Verbesserung der Sicherheit mit asynchronen und sicheren promise-basierten APIs"],"pt":["Simplificar lógica de navegador com APIs nativas","Melhorar o desempenho de aplicativos web reduzindo as dependências de bibliotecas externas","Aumentar a segurança com APIs baseadas em promessas assíncronas e seguras"],"ru":["Упрощение логики браузера с помощью родных API","Повышение производительности веб-приложений за счет уменьшения зависимости от внешних библиотек","Повышение безопасности с помощью асинхронных и безопасных API на основе обещаний"],"ar":["تبسيط منطق المتصفح مع واجهات برمجة تطبيقات المتصفح الأصلية","تحسين أداء تطبيقات الويب عن طريق تقليل الاعتماد على المكتبات الخارجية","تعزيز الأمان مع واجهات برمجة تطبيقات قائمة على وعد آمنة ومتزامنة"]},"limitations":{"en":["Requires modern browser support","Needs careful handling of fallbacks for non-supported APIs"],"zh":["需要现代浏览器支持","需要小心处理非支持API的回退"],"ja":["モダンブラウザのサポートが必要","非対応APIのフォールバックを慎重に処理する必要がある"],"ko":["모던 브라우저 지원이 필요하다","비지원 API에 대한 fallback을 주의해서 처리해야 한다"],"es":["Requiere soporte de navegador moderno","Requiere un manejo cuidadoso de los fallbacks para APIs no compatibles"],"fr":["Nécessite un support de navigateur moderne","Nécessite une gestion soigneuse des fallbacks pour les API non prises en charge"],"de":["Benötigt Unterstützung für moderne Browser","Benötigt eine sorgfältige Handhabung von Fallbacks für nicht unterstützte APIs"],"pt":["Requer suporte de navegador moderno","Necessita de manipulação cuidadosa de fallbacks para APIs não suportadas"],"ru":["Требует поддержки современных браузеров","Требует тщательного обращения с fallback для не поддерживаемых API"],"ar":["يتطلب دعم متصفح حديث","يحتاج إلى التعامل بحذر مع إمكانيات fallback لواجهات برمجة تطبيقات المتصفح غير المدعومة"]},"version":4},"contentHash":"a7275320c6d85b1b7d7dd17cf3f6e89e0803d08e5ceb58c512b591852251afa7","qualityScore":51}');
