INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DevChiJay/next-claude/use-modern-browser-apis', 'use-modern-browser-apis', 'DevChiJay', 'next-claude', 'community', 'use-modern-browser-apis DevChiJay next-claude community The use-modern-browser-apis skill enables developers to utilize native, modern browser APIs for simplified logic and improved performance. It benefits developers who prefer standardized and widely supported APIs over heavy external libraries. 使用现代浏览器API来简化逻辑、提高性能和减少包大小，推荐使用浏览器原生能力而不是第三方依赖 モダンブラウザAPIを使用してロジックを簡素化し、パフォーマンスを向上させ、バンドルサイズを削減します。ブラウザ原生能力を第三パーティ依存よりも優先します 모던 브라우저 API를 사용하여 로직을 단순화하고 성능을 향상시키고 번들 크기를 줄입니다. 브라우저 네이티브 기능을 第三方 의존보다 선호합니다 Esta habilidad se centra en el uso de API de navegador modernas para simplificar la lógica y mejorar el rendimiento Cette compétence se concentre sur l''utilisation des API de navigateur modernes pour simplifier la logique et améliorer les performances Diese Fähigkeit konzentriert sich auf die Verwendung moderner Browser-APIs, um Logik zu vereinfachen und Leistung zu verbessern Use APIs modernas de navegador para simplificar a lógica e melhorar o desempenho Используйте современные браузерные API для упрощения логики и улучшения производительности استخدم واجهات برمجة التطبيقات الحديثة للمتصفح لتبسيط المنطق وتحسين الأداء how to use use-modern-browser-apis what is use-modern-browser-apis use-modern-browser-apis alternative use-modern-browser-apis vs polyfills use-modern-browser-apis setup guide use-modern-browser-apis install modern browser APIs tutorial native browser APIs best practices use-modern-browser-apis for web development 现代浏览器API 浏览器原生能力 进步式增强 Promise-based 安全API AIエージェント 开发指南 浏览器API最佳实践 Utilizes standardized and widely supported browser-native capabilities Provides sensible fallbacks for APIs that aren’t available in all clients via progressive enhancement Employs promise-based and async APIs for secure and efficient data handling Reduces bundle size by minimizing reliance on heavy external libraries Improves performance through optimized use of modern browser APIs Supports simplified logic for enhanced developer productivity use-modern-browser-apis is a skill that promotes the use of native, modern browser APIs to simplify logic, improve performance, and reduce bundle size.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcd35/health-tracker-9000/generate-store-action', 'community', 'marcd35', 'health-tracker-9000', 'marcd35/health-tracker-9000', 'generate-store-action', 0, 0, 51, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.838Z', 'bf60c662ef4b484b8f967b579a7e897e92bdf4f9a086d4facbbe851e08bc7366', '{"id":"marcd35/health-tracker-9000/generate-store-action","name":"generate-store-action","description":{"en":"The generate-store-action skill generates Zustand async actions for health store management, benefiting developers working with Zustand and API endpoints. It streamlines the process of creating store actions.","zh":"Generate Store Action 是一个用于生成 Zustand 异步操作的 Skill，支持 loading 和 error 状态管理，适用于 Health Tracker 9000 开发","ja":"Generate Store Action は、Zustand の非同期アクションを生成するスキルで、ローディングとエラー状態の管理をサポートします","ko":"Generate Store Action은 Zustand 비동기 액션을 생성하는 스킬로 로딩 및 에러 상태 관리를 지원하여 Health Tracker 9000 개발에 적합합니다","es":"Genera acciones asincrónicas de Zustand con gestión de estado de carga y error para tu aplicación health-tracker-9000","fr":"Générez des actions asynchrones de Zustand avec gestion d''état de chargement et d''erreur pour votre application health-tracker-9000","de":"Generieren Sie asynchrone Zustand-Aktionen mit Lade- und Fehlerzustandsverwaltung für Ihre health-tracker-9000-Anwendung","pt":"O Generate Store Action gera ações assíncronas do Zustand com gerenciamento de estado de carregamento/erro para a loja de saúde","ru":"Generate Store Action генерирует асинхронные действия Zustand с управлением состоянием загрузки/ошибки для магазина здоровья","ar":"Generate Store Action يولد إجراءات غير متزامنة من Zustand مع إدارة حالة التحميل/الخطأ للمتجر الصحي"},"seo":{"title":{"en":"generate-store-action: Zustand Async Action Setup Guide |...","zh":"Zustand 异步操作生成器设置指南 - Generate Store Action","ja":"Zustand 非同期アクション生成ツールのベ