INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcd35/health-tracker-9000/generate-store-action', 'generate-store-action', 'marcd35', 'health-tracker-9000', 'community', 'generate-store-action marcd35 health-tracker-9000 community The generate-store-action skill generates Zustand async actions for health store management, benefiting developers working with Zustand and API endpoints. It streamlines the process of creating store actions. Generate Store Action 是一个用于生成 Zustand 异步操作的 Skill，支持 loading 和 error 状态管理，适用于 Health Tracker 9000 开发 Generate Store Action は、Zustand の非同期アクションを生成するスキルで、ローディングとエラー状態の管理をサポートします Generate Store Action은 Zustand 비동기 액션을 생성하는 스킬로 로딩 및 에러 상태 관리를 지원하여 Health Tracker 9000 개발에 적합합니다 Genera acciones asincrónicas de Zustand con gestión de estado de carga y error para tu aplicación health-tracker-9000 Générez des actions asynchrones de Zustand avec gestion d''état de chargement et d''erreur pour votre application health-tracker-9000 Generieren Sie asynchrone Zustand-Aktionen mit Lade- und Fehlerzustandsverwaltung für Ihre health-tracker-9000-Anwendung O Generate Store Action gera ações assíncronas do Zustand com gerenciamento de estado de carregamento/erro para a loja de saúde Generate Store Action генерирует асинхронные действия Zustand с управлением состоянием загрузки/ошибки для магазина здоровья Generate Store Action يولد إجراءات غير متزامنة من Zustand مع إدارة حالة التحميل/الخطأ للمتجر الصحي how to use generate-store-action generate-store-action alternative generate-store-action install what is generate-store-action generate-store-action vs Redux generate-store-action setup guide Zustand async action generation health-tracker-9000 development Zustand 异步操作 Health Tracker 9000 AI 工具 状态管理 loading 状态 error 状态 API 端点 HTTP 方法 Generates Zustand async actions with loading/error state management Supports API endpoint configuration (e.g., /api/water-intake, /api/sleep) Handles HTTP methods (GET, POST, PUT, DELETE) for request/response types Enables state updates for storing data in Zustand Follows implementation pattern based on src/lib/store/h generate-store-action is a skill that generates Zustand async actions for the health store with loading/error state management, simplifying the development process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Wox-launcher/Wox/wox-update-changelog', 'community', 'Wox-launcher', 'Wox', 'Wox-launcher/Wox', 'wox-update-changelog', 0, 0, 51, '2026-03-08T01:57:15.369Z', '2026-03-08T02:04:24.750Z', 'ff5c25c62ab94d7dff6759c8edf46b308b3c9a3b7c52af07fcb948e4368b04b8', '{"id":"Wox-launcher/Wox/wox-update-changelog","name":"wox-update-changelog","description":{"en":"The wox-update-changelog skill automates updates to CHANGELOG.md, ensuring consistent wording and markdown style. It benefits developers by streamlining changelog management.","zh":"Wox Update Changelog 是一个跨平台的启动器，用于更新 CHANGELOG.md 文件，保持一致的风格和格式。它支持 Git 标签和提交范围","ja":"Wox Update Changelog は、CHANGELOG.md ファイルを更新し、一貫したスタイルとフォーマットを維持するクロスプラットフォーム ランチャーです。Git タグとコミット範囲をサポートしています","ko":"Wox Update Changelog는 CHANGELOG.md 파일을 업데이트하고 일관된 스타일과 형식을 유지하는 크로스 플랫폼 런처입니다. Git 태그와 커밋 범위를 지원합니다","es":"wox-update-changelog es una herramienta que actualiza automáticamente el archivo CHANGELOG.md con los cambios realizados desde la última versión","fr":"wox-update-changelog est un outil qui met à jour automatiquement le fichier CHANGELOG.md avec les modifications effectuées depuis la dernière version","de":"wox-update-changelog ist ein Tool, das die Datei CHANGELOG.md automatisch mit den Änderungen aktualisiert, die seit der letzten Version vorgenommen wurden","pt":"O Wox Update Changelog é uma ferramenta que atualiza o CHANGELOG.md com commits recentes de forma automática.","ru":"Wox Update Changelog - это инструмент, который автоматически обновляет CHANGELOG.md с последними коммитами.","ar":"وكس أبديت تشانجلوج هو أداة تحديث CHANGELOG.md تلقائيًا باستخدام آخر التعليقات الملتزمة"},"seo":{"title":{"en":"wox-update-changelog: Automated Changelog Updates for AI ...","zh":"Wox Update Changelog Setup Guide - AI工具","ja":"Wox Update Changelog ベストプラクティス - AIエージェント","ko":"Wox Update Changelog 설정 가이드 - 인공지능 도구","es":"Guía de configuración de wox-update-changelog para actual...","fr":"Guide d''installation de wox-update-changelog pour mises à...","de":"Setup-Anleitung für wox-update-changelog zur automatische...","pt":"Guia de Configuração do Wox Update Changelog","ru":"Настройка Wox Update Changelog: ИИ Агенты для автоматизации","ar":"دليل إعداد وكس أبديت تشانجلوج - أدوات ذكاء اصطناعي"},"description":{"en":"Discover how wox-update-changelog simplifies changelog management. Learn how to automate updates from the latest release to HEAD and maintain consistent form...","zh":"Wox Update Changelog 是一个跨平台的启动器，用于更新 CHANGELOG.md 文件，保持一致的风格和格式","ja":"Wox Update Changelog は、CHANGELOG.md ファイルを更新し、一貫したスタイルとフォーマットを維持するクロスプラットフォーム ランチャーです","ko":"Wox Update Changelog는 CHANGELOG.md 파일을 업데이트하고 일관된 스타일과 형식을 유지하는 크로스 플랫폼 런처입니다","es":"Aprende a utilizar wox-update-changelog para mantener tu CHANGELOG.md actualizado con las últimas versiones y commits","fr":"Découvrez comment utiliser wox-update-changelog pour maintenir votre CHANGELOG.md à jour avec les dernières versions et commits","de":"Erfahren Sie, wie Sie wox-update-changelog verwenden, um Ihre CHANGELOG.md-Datei mit den neuesten Versionen und Commits zu aktualisieren","pt":"Aprenda a configurar o Wox Update Changelog para automatizar a atualização do CHANGELOG.md com commits recentes","ru":"ИИ Агенты для автоматизации: настройка Wox Update Changelog для обновления CHANGELOG.md","ar":"اكتشف كيفية إعداد وكس أبديت تشانجلوج لتحديث CHANGELOG.md تلقائيًا باستخدام أدوات ذكاء اصطناعي"},"definition":{"en":"wox-update-changelog is a cross-platform launcher that automates CHANGELOG.md updates from the latest released version to HEAD.","zh":"Wox Update Changelog 是一个用于更新 CHANGELOG.md 文件的跨平台启动器","ja":"Wox Update Changelog は、CHANGELOG.md ファイルを更新するクロスプラットフォーム ランチャーです","ko":"Wox Update Changelog는 CHANGELOG.md 파일을 업데이트하는 크로스 플랫폼 런처입니다","es":"wox-update-changelog es una herramienta de actualización de registros de cambios que utiliza Git para mantener el archivo CHANGELOG.md actualizado","fr":"wox-update-changelog est un outil de mise à jour de journal des modifications qui utilise Git pour maintenir le fichier CHANGELOG.md à jour","de":"wox-update-changelog ist ein Tool zur Aktualisierung von Änderungsprotokollen, das Git verwendet, um die Datei CHANGELOG.md zu aktualisieren","pt":"O Wox Update Changelog é uma ferramenta de linha de comando que atualiza o CHANGELOG.md","ru":"Wox Update Changelog - это командная строка инструмент, который обновляет CHANGELOG.md","ar":"وكس أبديت تشانجلوج هو أداة سطر الأوامر التي تحديث CHANGELOG.md"},"features":{"en":["Identifies release boundaries using git tag --sort=-creatordate","Updates CHANGELOG.md from the latest released version to HEAD","Maintains consistent wording, section order, and markdown style","Uses commit range last_release_tag..HEAD by default","Detects the target section in CHANGELOG.md"],"zh":["支持 Git 标签","支持提交范围","保持一致的风格和格式","跨平台兼容","自动更新 CHANGELOG.md 文件"],"ja":["Git タグをサポート","コミット範囲をサポート","一貫したスタイルとフォーマットを維持","クロスプラットフォーム対応","CHANGELOG.md ファイルを自動更新"],"ko":["Git 태그 지원","커밋 범위 지원","일관된 스타일과 형식을 유지","크로스 플랫폼 호환","CHANGELOG.md 파일 자동 업데이트"],"es":["Actualiza automáticamente el archivo CHANGELOG.md con los cambios realizados desde la última versión","Utiliza Git para detectar los cambios y actualizar el archivo","Mantiene el estilo y la estructura del archivo CHANGELOG.md","Permite personalizar el rango de commits para la actualización","Es compatible con múltiples plataformas"],"fr":["Met à jour automatiquement le fichier CHANGELOG.md avec les modifications effectuées depuis la dernière version","Utilise Git pour détecter les modifications et mettre à jour le fichier","Maintient le style et la structure du fichier CHANGELOG.md","Permet de personnaliser la plage de commits pour la mise à jour","Est compatible avec plusieurs plateformes"],"de":["Aktualisiert automatisch die Datei CHANGELOG.md mit den Änderungen, die seit der letzten Version vorgenommen wurden","Verwendet Git, um die Änderungen zu erkennen und die Datei zu aktualisieren","Behält den Stil und die Struktur der Datei CHANGELOG.md bei","Ermöglicht die Anpassung des Commit-Bereichs für die Aktualisierung","Ist mit mehreren Plattformen kompatibel"],"pt":["Atualiza o CHANGELOG.md com commits recentes","Detecta a última tag de lançamento com git tag","Usa o commit range last_release_tag..HEAD por padrão","Mantém a consistência de estilo e marcação com entradas existentes","Suporta múltiplas plataformas"],"ru":["Обновляет CHANGELOG.md с последними коммитами","Обнаруживает последний тег релиза с git tag","Использует диапазон коммитов last_release_tag..HEAD по умолчанию","Сохраняет последовательность стиля и маркировки с существующими записями","Поддерживает несколько платформ"],"ar":["يحديث CHANGELOG.md بالالتزامات الحديثة","يكتشف آخر علامة إصدار مع git tag","يستخدم مدى الالتزام last_release_tag..HEAD افتراضيًا","يحافظ على συνέовательية الأسلوب والتدوين مع المدخلات الحالية","يدعم منصات متعددة"]},"keywords":{"en":["how to use wox-update-changelog","wox-update-changelog alternative","wox-update-changelog setup guide","what is wox-update-changelog","wox-update-changelog vs manual updates","automated changelog updates"],"zh":["Wox Update Changelog","AI工具","CHANGELOG.md","Git 标签","提交范围","跨平台启动器","自动更新"],"ja":["Wox Update Changelog","AIエージェント","CHANGELOG.md","Git タグ","コミット範囲","クロスプラットフォーム ランチャー","自動更新"],"ko":["Wox Update Changelog","인공지능 도구","CHANGELOG.md","Git 태그","커밋 범위","크로스 플랫폼 런처","자동 업데이트"],"es":["wox-update-changelog","actualización automática de CHANGELOG.md","herramientas de Git","actualización de registros de cambios","compatibilidad con múltiples plataformas","personalización de commits","automatización de tareas","desarrollo de software","herramientas de desarrollo"],"fr":["wox-update-changelog","mise à jour automatique de CHANGELOG.md","outils Git","mise à jour de journal des modifications","compatibilité avec plusieurs plateformes","personnalisation de commits","automatisation de tâches","développement de logiciels","outils de développement"],"de":["wox-update-changelog","automatische Aktualisierung von CHANGELOG.md","Git-Tools","Aktualisierung von Änderungsprotokollen","Kompatibilität mit mehreren Plattformen","Anpassung von Commits","Automatisierung von Aufgaben","Software-Entwicklung","Entwicklungstools"],"pt":["wox update changelog","atualização automática","CHANGELOG.md","git tag","commit range","ferramenta de linha de comando","desenvolvimento de software","automatização de tarefas"],"ru":["wox update changelog","автоматическое обновление","CHANGELOG.md","git tag","диапазон коммитов","командная строка инструмент","разработка программного обеспечения","автоматизация задач","ИИ Агенты"],"ar":["وكس أبديت تشانجلوج","تحديث تلقائي","CHANGELOG.md","git tag","مدى الالتزام","أداة سطر الأوامر","تطوير البرمجيات","تحديث CHANGELOG.md","أدوات ذكاء اصطناعي"]}},"owner":"Wox-launcher","repo":"Wox","repoPath":"Wox-launcher/Wox","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.369Z","topics":[],"category":"community","skillMd":{"name":"wox-update-changelog","description":"Update Wox CHANGELOG.md based on commits since the last release. Use when the user asks to update changelog, write release notes, or summarize changes since last release and the output must follow the repositorys existing changelog format.","bodyPreview":"# Wox Update Changelog\n\n## Overview\n\nUpdate `CHANGELOG.md` from the latest released version to `HEAD` and keep wording, section order, and markdown style consistent with existing entries.\n\n## Workflow\n\n1. Identify the release boundary.\n- Read the top of `CHANGELOG.md` and detect the target section (usually newest version at the top).\n- Detect the last released tag with `git tag --sort=-creatordate`.\n- Use commit range `last_release_tag..HEAD` by default.\n- If changelog heading and git tag disagr","body":"# Wox Update Changelog\n\n## Overview\n\nUpdate `CHANGELOG.md` from the latest released version to `HEAD` and keep wording, section order, and markdown style consistent with existing entries.\n\n## Workflow\n\n1. Identify the release boundary.\n- Read the top of `CHANGELOG.md` and detect the target section (usually newest version at the top).\n- Detect the last released tag with `git tag --sort=-creatordate`.\n- Use commit range `last_release_tag..HEAD` by default.\n- If changelog heading and git tag disagree, prefer changelog context and state the assumption.\n\n2. Collect candidate changes.\n- Run `git log --oneline --no-merges <range>`.\n- Open key commits with `git show --stat --oneline <sha>` to classify user-facing impact.\n- Ignore pure build/version bump commits unless they change user-visible behavior.\n\n3. Classify into changelog buckets.\n- `Add`: new user-visible features/settings/components.\n- `Improve`: behavioral or UX improvements without new core capability.\n- `Fix`: user-facing bug fixes/regressions.\n- Exclude internal refactors/tests/docs/chore unless directly user-visible.\n- Exclude tiny UI-only polish by default (for example spacing, alignment, minor color/wording tweaks) unless it fixes a functional UX issue or the user explicitly asks to include small UI changes.\n\n4. Write changelog entries in repository style.\n- Preserve header pattern exactly (for example: `## v2.0.1 -`).\n- Keep section order: `Add`, `Improve`, `Fix`.\n- Use bullet nesting style already used in file.\n- Keep wording concise, user-facing, and factual.\n- Prefer plugin/module prefix when clear, e.g. ``[`Shell`]`` or ``[`Clipboard`]``.\n- Keep issue references in existing style, e.g. `#4339`.\n- Keep existing screenshots and add new image lines only when already available in repo.\n\n5. Validate before finishing.\n- Ensure no duplicate bullets.\n- Ensure every bullet maps to at least one commit in range.\n- Ensure markdown renders cleanly and section spacing matches nearby versions.\n- Avoid rewriting old release sections unless explicitly requested.\n- If a commit set only contains tiny UI-only polish, keep it out of changelog by default.\n\n## Command Reference\n\n```bash\ngit tag --sort=-creatordate | head -n 20\nsed -n ''1,120p'' CHANGELOG.md\ngit log --oneline --no-merges <last_tag>..HEAD\ngit show --stat --oneline <sha>\ngit diff -- CHANGELOG.md\n```\n\n## Output Rules\n\n- Edit `CHANGELOG.md` directly.\n- Keep final response short: what section was updated and what categories were changed.\n- If commit intent is ambiguous, state the assumption briefly in the final response.\n"},"lastSynced":"2026-03-08T02:04:24.750Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing automated changelog management with consistent markdown style and wording.","zh":"适合需要自动化变更日志管理的版本控制代理，具有统一的markdown样式和用词。","ja":"自動化された変更ログ管理が必要なバージョン管理エージェントに最適です。一貫したマークダウンスタイルと用語を備えています。","ko":"자동화된 변경 로그 관리가 필요한 버전 관리 에이전트에 적합합니다. 일관된 마크다운 스타일과 용어를 가집니다.","es":"Ideal para agentes de control de versiones que necesitan una gestión de registros de cambios automatizada con estilo y redacción de markdown consistentes.","fr":"Idéal pour les agents de contrôle de version nécessitant une gestion de journal des modifications automatisée avec un style et une formulation de markdown cohérents.","de":"Ideal für Version Control Agents, die eine automatisierte Änderungsprotokollverwaltung mit konsistenter Markdown-Stil und -Formulierung benötigen.","pt":"Ideal para Agentes de Controle de Versão que necessitam de gerenciamento de changelog automatizado com estilo markdown consistente e redação.","ru":"Идеально для Агентов Контроля Версий, требующих автоматизированного управления журналом изменений с последовательным стилем markdown и формулировкой.","ar":"مثالي لوكلاء التحكم في الإصدار الذين يحتاجون إلى إدارة سجل التغييرات التلقائي بطريقة تنسيق markdown متسقة وكتابة."},"recommendation":{"en":"Empowers agents to maintain consistent CHANGELOG.md files by automating updates from the latest released version to HEAD, utilizing git tag detection and commit range analysis with `git tag --sort=-creatordate` and markdown formatting.","zh":"赋予代理维护一致的CHANGELOG.md文件的能力，通过自动更新最新发布版本到HEAD，利用git标签检测和提交范围分析以及markdown格式化，使用`git tag --sort=-creatordate`。","ja":"最新のリリースバージョンからHEADまで自動で更新し、`git tag --sort=-creatordate`を使用してgitタグ検出とコミット範囲分析を行い、マークダウン形式で変更ログを管理することで、エージェントが一貫したCHANGELOG.mdファイルを維持できるようにします。","ko":"최신 릴리스 버전에서 HEAD까지 자동으로 업데이트하고, `git tag --sort=-creatordate`를 사용하여 git 태그 감지 및 커밋 범위 분석을 수행하며, 마크다운 형식으로 변경 로그를 관리하여 에이전트가 일관된 CHANGELOG.md 파일을 유지할 수 있도록 합니다.","es":"Habilita a los agentes a mantener archivos CHANGELOG.md consistentes mediante la automatización de actualizaciones desde la última versión publicada hasta HEAD, utilizando la detección de etiquetas git y el análisis de rangos de confirmación con `git tag --sort=-creatordate` y formato de markdown.","fr":"Permet aux agents de maintenir des fichiers CHANGELOG.md cohérents en automatisant les mises à jour depuis la dernière version publiée jusqu''à HEAD, en utilisant la détection de balises git et l''analyse de plage de commit avec `git tag --sort=-creatordate` et mise en forme de markdown.","de":"Ermächtigt die Agenten, konsistente CHANGELOG.md-Dateien zu pflegen, indem sie Updates von der neuesten veröffentlichten Version bis zum HEAD automatisieren, unter Verwendung von git-Tag-Erkennung und Commit-Bereichsanalyse mit `git tag --sort=-creatordate` und Markdown-Formatierung.","pt":"Permite que os agentes mantenham arquivos CHANGELOG.md consistentes, automatizando atualizações da última versão lançada para HEAD, utilizando detecção de tag git e análise de faixa de commits com `git tag --sort=-creatordate` e formatação markdown.","ru":"Наделяет агентов возможностью поддерживать последовательные файлы CHANGELOG.md, автоматизируя обновления с последней выпущенной версии в HEAD, используя обнаружение тега git и анализ диапазона коммитов с `git tag --sort=-creatordate` и форматирование markdown.","ar":"تمكّن الوكلاء من الحفاظ على ملفات CHANGELOG.md متسقة من خلال تلقين تحديثات من الإصدار المنشور الأخير إلى HEAD، باستخدام كشف علامة git وتحليل نطاق الإلتزامات مع `git tag --sort=-creatordate` وتنسيق markdown."},"useCases":{"en":["Automating changelog updates","Standardizing markdown styles across versions","Detecting release boundaries with git tags"],"zh":["自动化变更日志更新","标准化版本间的markdown样式","使用git标签检测发布边界"],"ja":["変更ログの自動更新","バージョン間のマークダウンスタイルの標準化","gitタグを使用したリリース境界の検出"],"ko":["변경 로그 자동 업데이트","버전 간 마크다운 스타일 표준화","git 태그를 사용한 릴리스 경계 감지"],"es":["Automatizar actualizaciones de registros de cambios","Establecer estilos de markdown estandarizados en varias versiones","Detectar límites de lanzamiento con etiquetas git"],"fr":["Automatiser les mises à jour du journal des modifications","Normaliser les styles de markdown à travers les versions","Détecter les limites de version avec des balises git"],"de":["Automatisierung von Änderungsprotokoll-Updates","Standardisierung von Markdown-Stilen über verschiedene Versionen","Erkennung von Release-Grenzen mit git-Tags"],"pt":["Automatizar atualizações de changelog","Padronizar estilos markdown em diferentes versões","Detectar limites de lançamento com tags git"],"ru":["Автоматизировать обновления журнала изменений","Стандартизировать стили markdown во всех версиях","Обнаруживать границы релизов с помощью тегов git"],"ar":["تلقين تحديثات سجل التغييرات","تقييس أساليب markdown عبر الإصدارات","كشف حدود الإصدار باستخدام علامات git"]},"limitations":{"en":["Requires access to git repository","Limited to updating CHANGELOG.md files","Dependent on consistent git tag naming conventions"],"zh":["需要访问git仓库","仅限更新CHANGELOG.md文件","依赖一致的git标签命名约定"],"ja":["gitリポジトリへのアクセスが必要","CHANGELOG.mdファイルの更新のみ","一貫したgitタグ命名規約に依存"],"ko":["git 리포지토리 접근이 필요","CHANGELOG.md 파일 업데이트만 가능","일관된 git 태그命명 규칙에 의존"],"es":["Requiere acceso al repositorio git","Limitado a la actualización de archivos CHANGELOG.md","Dependiente de convenciones de nombres de etiquetas git consistentes"],"fr":["Nécessite l''accès au référentiel git","Limité à la mise à jour des fichiers CHANGELOG.md","Dépendant de conventions de nommage de balises git cohérentes"],"de":["Benötigt Zugriff auf das git-Repository","Begrenzt auf die Aktualisierung von CHANGELOG.md-Dateien","Abhängig von konsistenten git-Tag-Namenskonventionen"],"pt":["Requer acesso ao repositório git","Limitado à atualização de arquivos CHANGELOG.md","Dependente de convenções de nomenclatura de tag git consistentes"],"ru":["Требует доступа к репозиторию git","Ограничен обновлением файлов CHANGELOG.md","Зависит от последовательных соглашений об именовании тегов git"],"ar":["يتطلب الوصول إلى مستودع git","محدود بالتحديث الخاص بملفات CHANGELOG.md","يعتمد على اتفاقيات تسمية علامات git المتناسقة"]},"version":4},"contentHash":"ff5c25c62ab94d7dff6759c8edf46b308b3c9a3b7c52af07fcb948e4368b04b8","qualityScore":51}');
