INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Wox-launcher/Wox/wox-update-changelog', 'wox-update-changelog', 'Wox-launcher', 'Wox', 'community', 'wox-update-changelog Wox-launcher Wox community The wox-update-changelog skill automates updates to CHANGELOG.md, ensuring consistent wording and markdown style. It benefits developers by streamlining changelog management. Wox Update Changelog 是一个跨平台的启动器，用于更新 CHANGELOG.md 文件，保持一致的风格和格式。它支持 Git 标签和提交范围 Wox Update Changelog は、CHANGELOG.md ファイルを更新し、一貫したスタイルとフォーマットを維持するクロスプラットフォーム ランチャーです。Git タグとコミット範囲をサポートしています Wox Update Changelog는 CHANGELOG.md 파일을 업데이트하고 일관된 스타일과 형식을 유지하는 크로스 플랫폼 런처입니다. Git 태그와 커밋 범위를 지원합니다 wox-update-changelog es una herramienta que actualiza automáticamente el archivo CHANGELOG.md con los cambios realizados desde la última versión wox-update-changelog est un outil qui met à jour automatiquement le fichier CHANGELOG.md avec les modifications effectuées depuis la dernière version wox-update-changelog ist ein Tool, das die Datei CHANGELOG.md automatisch mit den Änderungen aktualisiert, die seit der letzten Version vorgenommen wurden O Wox Update Changelog é uma ferramenta que atualiza o CHANGELOG.md com commits recentes de forma automática. Wox Update Changelog - это инструмент, который автоматически обновляет CHANGELOG.md с последними коммитами. وكس أبديت تشانجلوج هو أداة تحديث CHANGELOG.md تلقائيًا باستخدام آخر التعليقات الملتزمة how to use wox-update-changelog wox-update-changelog alternative wox-update-changelog setup guide what is wox-update-changelog wox-update-changelog vs manual updates automated changelog updates Wox Update Changelog AI工具 CHANGELOG.md Git 标签 提交范围 跨平台启动器 自动更新 Identifies release boundaries using git tag --sort=-creatordate Updates CHANGELOG.md from the latest released version to HEAD Maintains consistent wording, section order, and markdown style Uses commit range last_release_tag..HEAD by default Detects the target section in CHANGELOG.md wox-update-changelog is a cross-platform launcher that automates CHANGELOG.md updates from the latest released version to HEAD.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('motoya0118/pavlok_CLI_agent/slack', 'community', 'motoya0118', 'pavlok_CLI_agent', 'motoya0118/pavlok_CLI_agent', 'slack', 0, 0, 51, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:27.221Z', '57b4b1528430f954a703bdd756b5393782d8f642977bee95fc6b645f6583c4ef', '{"id":"motoya0118/pavlok_CLI_agent/slack","name":"slack","description":{"en":"The Slack skill enables AI agents to post questions and replies using scripts/slack.py, benefiting developers who need to automate Slack interactions.","zh":"Slack CLI Agent允许您使用Python脚本自动化任务。使用uv命令行工具运行脚本并与Slack集成","ja":"Slack CLIエージェントは、Pythonスクリプトを使用してタスクを自動化することを可能にします。uvコマンドラインツールを使用してスクリプトを実行し、Slackと統合します","ko":"Slack CLI 에이전트는 Python 스크립트를 사용하여 태스크를 자동화할 수 있습니다. uv 명령줄 도구를 사용하여 스크립트를 실행하고 Slack과 통합합니다","es":"Configura Slack para agentes de CLI con scripts de Python y ejecución de comandos personalizados para mejorar la productividad","fr":"Configurez Slack pour les agents CLI avec des scripts Python et des commandes personnalisées pour améliorer la productivité","de":"Richten Sie Slack für CLI-Agenten mit Python-Skripten und benutzerdefinierten Befehlen ein, um die Produktivität zu verbessern","pt":"O Slack é uma plataforma de colaboração que pode ser automatizada com scripts Python e CLI para melhorar a produtividade","ru":"Slack - это платформа для сотрудничества, которую можно автоматизировать с помощью скриптов Python и CLI для повышения производительности","ar":"السلاك هو منصة للتعاون يمكن تخصيصها باستخدام سكريبتات بايثون وCLI لتحسين الإنتاجية"},"seo":{"title":{"en":"Slack: Setup Guide for AI Agents | AI Agent Skill","zh":"Slack集成指南：使用CLI Agent自动化任务","ja":"Slack CLIエージェントの設定方法：自動化のベストプラクティス","ko":"Slack 자동화 가이드: CLI 에이전트를 사용한 태스크 자동화","es":"Guía de configuración de Slack para agentes de CLI","fr":"Paramétrer Slack pour les agents CLI : Meilleures pratiques","de":"Slack-Setup-Anleitung für CLI-Agenten","pt":"Guia de Configuração do Slack para Desenvolvedores","ru":"Настройка Slack для разработчиков: beste практики","ar":"دليل إعداد السلاك لmîة المطورين"},"description":{"en":"Discover how to leverage Slack with AI agents, explore technical details, and get started with setup and implementation today!","zh":"了解如何使用Slack CLI Agent自动化任务和提高生产力。发现使用Python脚本和uv命令行工具的优势","ja":"Slack CLIエージェントを使用してタスクを自動化し、生産性を向上させる方法を学びます。Pythonスクリプトとuvコマンドラインツールの利点を発見します","ko":"Slack CLI 에이전트를 사용하여 태스크를 자동화하고 생산성을 향상시키는 방법을 알아보세요. Python 스크립트와 uv 명령줄 도구의 이점을 발견하세요","es":"Aprende a configurar Slack para agentes de línea de comandos con scripts de Python y ejecución de comandos personalizados","fr":"Découvrez comment paramétrer Slack pour les agents CLI avec des scripts Python et des commandes personnalisées","de":"Erfahren Sie, wie Sie Slack für CLI-Agenten mit Python-Skripten und benutzerdefinierten Befehlen einrichten","pt":"Aprenda a configurar o Slack com scripts Python e CLI para automação de tarefas e melhorias de produtividade","ru":"Узнайте, как настроить Slack с помощью скриптов Python и CLI для автоматизации задач и повышения производительности","ar":"تعلم كيفية إعداد السلاك باستخدام سكريبتات بايثون وCLI لتحسين الإنتاجية وتسريع المهام"},"definition":{"en":"Slack is a CLI agent skill that allows posting questions and replies using Python scripts, facilitating automated interactions within Slack threads.","zh":"Slack CLI Agent是一种使用Python脚本自动化Slack任务的工具","ja":"Slack CLIエージェントは、Pythonスクリプトを使用してSlackのタスクを自動化するツールです","ko":"Slack CLI 에이전트는 Python 스크립트를 사용하여 Slack 태스크를 자동화하는 도구입니다","es":"Slack para agentes de CLI es una herramienta que permite la interacción con Slack mediante scripts de Python","fr":"Slack pour les agents CLI est un outil qui permet l''interaction avec Slack via des scripts Python","de":"Slack für CLI-Agenten ist ein Tool, das die Interaktion mit Slack über Python-Skripte ermöglicht","pt":"O Slack é uma plataforma de colaboração que permite automação de tarefas com scripts Python e CLI","ru":"Slack - это платформа для сотрудничества, которая позволяет автоматизировать задачи с помощью скриптов Python и CLI","ar":"السلاك هو منصة للتعاون التي تسمح بالتخصيص باستخدام سكريبتات بايثون وCLI"},"features":{"en":["Posts questions and waits for the first reply using scripts/slack.py","Supports posting replies into existing threads with --mode reply","Utilizes --interval and --follow-up-message for customized interaction","Accepts question or reply text as input for flexible messaging","Employs uv run for executing scripts with specified parameters"],"zh":["使用Python脚本自动化Slack任务","支持uv命令行工具","可以在现有线程中发布回复","可以设置间隔时间和跟进消息","支持问答模式和回复模式"],"ja":["Pythonスクリプトを使用してSlackのタスクを自動化","uvコマンドラインツールをサポート","既存のスレッドに返信を投稿できる","間隔時間とフォローアップメッセージを設定できる","質問モードと返信モードをサポート"],"ko":["Python 스크립트를 사용하여 Slack 태스크를 자동화","uv 명령줄 도구를 지원","既存의 스레드에 반환 메시지를 게시할 수 있습니다","간격 시간과 후속 메시지를 설정할 수 있습니다","질문 모드와 반환 모드를 지원"],"es":["Ejecución de comandos personalizados con scripts de Python","Compatibilidad con la ejecución de comandos en segundo plano","Soporte para la respuesta en hilos de conversación","Uso de la biblioteca `uv` para la ejecución de comandos","Personalización de los mensajes de pregunta y respuesta","Soporte para la ejecución de comandos con intervalos personalizados"],"fr":["Exécution de commandes personnalisées avec des scripts Python","Compatibilité avec l''exécution de commandes en arrière-plan","Prise en charge de la réponse dans les threads de conversation","Utilisation de la bibliothèque `uv` pour l''exécution de commandes","Personnalisation des messages de question et de réponse","Prise en charge de l''exécution de commandes avec des intervalles personnalisés"],"de":["Ausführung von benutzerdefinierten Befehlen mit Python-Skripten","Kompatibilität mit der Ausführung von Befehlen im Hintergrund","Unterstützung für die Antwort in Konversationsthreads","Verwendung der Bibliothek `uv` für die Ausführung von Befehlen","Anpassung der Frage- und Antwortnachrichten","Unterstützung für die Ausführung von Befehlen mit benutzerdefinierten Intervallen"],"pt":["Automação de tarefas com scripts Python","Integração com CLI para controle de tarefas","Envio de perguntas e respostas em threads","Utilização de comandos como `uv run` para execução de scripts"],"ru":["Автоматизация задач с помощью скриптов Python","Интеграция с CLI для контроля задач","Отправка вопросов и ответов в потоках","Использование команд như `uv run` для выполнения скриптов"],"ar":["تخصيص المهام باستخدام سكريبتات بايثون","التكامل مع CLI للتحكم في المهام","إرسال الأسئلة والإجابات في Threads","استخدام أوامر مثل `uv run` لتشغيل السكريبتات"]},"keywords":{"en":["how to use slack with AI agents","slack setup guide for developers","slack alternative for automation","slack vs microsoft teams for AI integration","slack install for python scripts","slack api for automated interactions"],"zh":["Slack自动化","CLI Agent","Python脚本","uv命令行工具","Slack集成","自动化任务","提高生产力"],"ja":["Slack自動化","CLIエージェント","Pythonスクリプト","uvコマンドラインツール","Slack統合","自動化タスク","生産性向上"],"ko":["Slack 자동화","CLI 에이전트","Python 스크립트","uv 명령줄 도구","Slack 통합","자동화 태스크","생산성 향상"],"es":["agentes de CLI","scripts de Python","configuración de Slack","herramientas de productividad","automatización de tareas","integración de Slack","desarrollo de agentes de CLI","uso de la biblioteca uv","personalización de mensajes"],"fr":["agents CLI","scripts Python","configuration de Slack","outils de productivité","automatisation de tâches","intégration de Slack","développement d''agents CLI","utilisation de la bibliothèque uv","personnalisation de messages"],"de":["CLI-Agenten","Python-Skripte","Slack-Setup","Produktivitätstools","Aufgabenautomatisierung","Slack-Integration","Entwicklung von CLI-Agenten","Verwendung der Bibliothek uv","Anpassung von Nachrichten"],"pt":["Slack para desenvolvedores","Automação de tarefas no Slack","Scripts Python para Slack","CLI para Slack","Integração Slack com Python","Desenvolvimento de bots para Slack"],"ru":["Slack для разработчиков","Автоматизация задач в Slack","Скрипты Python для Slack","CLI для Slack","Интеграция Slack с Python","Разработка ботов для Slack"],"ar":["السلاك للمطورين","تخصيص المهام في السلاك","سكريبتات بايثون للسلاك","CLI للسلاك","التكامل بين السلاك وبايثون","تطوير البوتات للسلاك"]}},"owner":"motoya0118","repo":"pavlok_CLI_agent","repoPath":"motoya0118/pavlok_CLI_agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"slack","description":"Post a question to Slack and wait for a reply, or post a reply into a thread using scripts/slack.py.","bodyPreview":"# Slack Ask + Thread Reply\n\nUse `scripts/slack.py` to post a question and wait for the first reply, or to post a reply into an existing thread.\n\n## Run\n\n```bash\nuv run scripts/slack.py \"Did you finish the task?\" --interval 2 --follow-up-message \"This counts as another ignore. Please reply in the thread.\"\n```\n\n```bash\nuv run scripts/slack.py --mode reply --thread-ts 1700000000.000000 \"Reply text\"\n```\n\n## Inputs\n\n- `question` is the message text (question in `ask` mode, reply in `reply` mode).\n- `","body":"# Slack Ask + Thread Reply\n\nUse `scripts/slack.py` to post a question and wait for the first reply, or to post a reply into an existing thread.\n\n## Run\n\n```bash\nuv run scripts/slack.py \"Did you finish the task?\" --interval 2 --follow-up-message \"This counts as another ignore. Please reply in the thread.\"\n```\n\n```bash\nuv run scripts/slack.py --mode reply --thread-ts 1700000000.000000 \"Reply text\"\n```\n\n## Inputs\n\n- `question` is the message text (question in `ask` mode, reply in `reply` mode).\n- `--mode` chooses behavior (`ask` default, `reply` posts into a thread).\n- `--no-reply-hint` skips appending \"Reply in thread.\"\n- `--follow-up-message` sets the message to post when a reply is not received within the ignore window.\n  - Required in `ask` mode.\n- `ask` mode:\n  - `--interval` sets polling interval in seconds (default: 2).\n  - `--thread-ts` and `--channel` are not required.\n- `reply` mode:\n  - `--thread-ts` is required.\n  - `--channel` overrides `SLACK_CHANNEL` (accepts name or ID).\n  - `--interval` is not used.\n\n## Outputs\n\nAsk mode prints a single line:\n\n```\n{assistant_question: ..., user_answer: ..., is_answer: true|false, thread_ts: ..., message_ts: ...}\n```\n\nIf no reply arrives before timeout, `user_answer` is `null` and `is_answer` is `false`.\n\nReply mode prints a single line:\n\n```\n{assistant_question: ..., user_answer: null, is_answer: false, thread_ts: ..., message_ts: ...}\n```\n\n## Notes\n\n- Requires `SLACK_BOT_USER_OAUTH_TOKEN`.\n- Optional `SLACK_USER_OAUTH_TOKEN` is used for reading replies; if unset, the bot token is reused.\n- Missing history scopes will cause `missing_scope` errors; add `channels:history`, `groups:history`, `im:history`, and `mpim:history` as needed.\n- The CLI unescapes `\\n`, `\\r`, and `\\t` sequences in `question` before sending.\n- Ask mode timeout is derived from env: `IGNORE_SPAN * REPLY_COUNT_LIMIT`.\n- `ask` mode requires `--follow-up-message`.\n"},"lastSynced":"2026-03-08T02:04:27.221Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational Agents requiring automated Slack interactions and thread management.","zh":"适用于需要自动化Slack交互和线程管理的对话式代理。","ja":"Slackの自動化とスレッド管理が必要な会話エージェントに最適。","ko":"Slack 상호작용 및 스레드 관리 자동화가 필요한 대화형 에이전트에 적합합니다.","es":"Ideal para agentes de conversación que requieren interacciones automatizadas de Slack y gestión de hilos.","fr":"Idéal pour les agents de conversation nécessitant des interactions Slack automatisées et une gestion de threads.","de":"Ideal für Konversationsagenten, die automatisierte Slack-Interaktionen und Thread-Verwaltung erfordern.","pt":"Ideal para Agentes de Conversação que exigem interações automatizadas do Slack e gerenciamento de threads.","ru":"Идеально для разговорных агентов, требующих автоматизированных взаимодействий Slack и управления потоками.","ar":"مثالي للوكلاء المحادثين الذين يتطلبون تفاعلات Slack автомاتيزيه وإدارة الخيوط."},"recommendation":{"en":"Empowers agents to post questions and replies using scripts/slack.py, leveraging Slack''s API for seamless integration, and enables features like follow-up messages and thread replies using specific thread-ts identifiers.","zh":"赋予代理使用scripts/slack.py发布问题和回复，利用Slack的API实现无缝集成，并启用诸如后续消息和线程回复等功能，使用特定的线程-ts标识符。","ja":"scripts/slack.pyを使用して質問と回答を投稿し、SlackのAPIを利用してシームレスな統合を実現し、特定のスレッド-ts識別子を使用してフォローアップメッセージやスレッドの返信などの機能を有効にすることでエージェントを強化します。","ko":"에이전트가 scripts/slack.py를 사용하여 질문과 답을 게시하고 Slack의 API를 활용하여 무결점 통합을实现하며 특정 스레드-ts 식별자를 사용하여 후속 메시지 및 스레드 회신 등의 기능을 활성화하는 것을 가능하게 합니다.","es":"Habilita a los agentes a publicar preguntas y respuestas utilizando scripts/slack.py, aprovechando la API de Slack para una integración sin problemas, y permite características como mensajes de seguimiento y respuestas de threads utilizando identificadores de thread-ts específicos.","fr":"Permet aux agents de publier des questions et des réponses en utilisant scripts/slack.py, en exploitant l''API Slack pour une intégration transparente, et permet des fonctionnalités comme les messages de suivi et les réponses de threads en utilisant des identificateurs de thread-ts spécifiques.","de":"Ermächtigt Agenten, Fragen und Antworten mithilfe von scripts/slack.py zu posten, wobei die Slack-API für eine nahtlose Integration genutzt wird, und ermöglicht Funktionen wie Follow-up-Nachrichten und Thread-Antworten mithilfe spezifischer thread-ts-Identifikatoren.","pt":"Habilita os agentes a postar perguntas e respostas usando scripts/slack.py, aproveitando a API do Slack para integração sem problemas, e permite recursos como mensagens de acompanhamento e respostas de thread usando identificadores de thread-ts específicos.","ru":"Наделяет агентов возможностью публиковать вопросы и ответы с помощью scripts/slack.py, используя API Slack для бесшовной интеграции, и позволяет функции, такие как сообщения-напоминания и ответы на поток, используя конкретные идентификаторы thread-ts.","ar":"يمنح الوكلاء القدرة على نشر الأسئلة والإجابات باستخدام scripts/slack.py، واستخدام واجهة برمجة تطبيقات Slack للدمج السلس، ويمكنه الميزات مثل رسائل المتابعة والردود على الخيط باستخدام معرّفات thread-ts محددة."},"useCases":{"en":["Automating Slack notifications for task updates","Generating threaded conversations for collaborative workflows","Posting questions and awaiting replies for dynamic feedback loops"],"zh":["自动化Slack通知以进行任务更新","为协作工作流生成线程化会话","发布问题并等待回复以实现动态反馈循环"],"ja":["タスクの更新のためのSlack通知の自動化","コラボレーション・ワークフロー用のスレッド化会話の生成","動的フィードバック・ループを実現するための質問の投稿と回答の待機"],"ko":["작업 업데이트에 대한 Slack 알림 자동화","협업 워크플로우를 위한 스레드화된 대화 생성","동적 피드백 루프를 위해 질문 게시 및 답신 대기"],"es":["Automatización de notificaciones de Slack para actualizaciones de tareas","Generación de conversaciones en hilos para flujos de trabajo colaborativos","Publicación de preguntas y espera de respuestas para bucles de retroalimentación dinámicos"],"fr":["Automatisation des notifications Slack pour les mises à jour de tâches","Génération de conversations en threads pour les flux de travail collaboratifs","Publication de questions et attente de réponses pour des boucles de rétroaction dynamiques"],"de":["Automatisierung von Slack-Benachrichtigungen für Aufgaben-Updates","Erzeugung von Thread-Konversationen für kollaborative Workflows","Veröffentlichung von Fragen und Warten auf Antworten für dynamische Feedback-Schleifen"],"pt":["Automatizar notificações do Slack para atualizações de tarefas","Gerar conversas encadeadas para fluxos de trabalho colaborativos","Publicar perguntas e aguardar respostas para loops de feedback dinâmicos"],"ru":["Автоматизировать уведомления Slack для обновлений задач","Генерировать потоковые разговоры для совместных рабочих процессов","Публиковать вопросы и ожидать ответов для динамических петлей обратной связи"],"ar":["أتمتة إشعارات Slack لتحديثات المهام","توليد محادثات متسلسلة لمسارات عمل تعاونية","نشر الأسئلة وانتظار الردود لألقاطع الارتجاعية الديناميكية"]},"limitations":{"en":["Requires scripts/slack.py execution","Slack API compatibility needed","Specific interval and follow-up message configurations required"],"zh":["需要执行scripts/slack.py","需要Slack API兼容性","需要特定间隔和后续消息配置"],"ja":["scripts/slack.pyの実行が必要","Slack APIの互換性が必要","特定の間隔とフォローアップ・メッセージの構成が必要"],"ko":["scripts/slack.py 실행 필요","Slack API 호환성 필요","특정 간격 및 후속 메시지 구성 필요"],"es":["Requiere la ejecución de scripts/slack.py","Se requiere compatibilidad con la API de Slack","Se requieren configuraciones de intervalo y mensaje de seguimiento específicas"],"fr":["Nécessite l''exécution de scripts/slack.py","La compatibilité avec l''API Slack est nécessaire","Des configurations d''intervalles et de messages de suivi spécifiques sont requises"],"de":["Erfordert die Ausführung von scripts/slack.py","Slack-API-Kompatibilität erforderlich","Spezifische Intervall- und Follow-up-Nachrichtenkonfigurationen erforderlich"],"pt":["Requer execução scripts/slack.py","Compatibilidade com a API do Slack necessária","Configurações de intervalo e mensagem de acompanhamento específicas necessárias"],"ru":["Требует выполнения scripts/slack.py","Необходимо совместимость с API Slack","Требуются конкретные конфигурации интервала и сообщения-напоминания"],"ar":["يتطلب تنفيذ scripts/slack.py","مطلوب توافق مع واجهة برمجة تطبيقات Slack","مطلوبة cấu hình فاصل زمني ورسائل المتابعة المحددة"]},"version":4},"contentHash":"57b4b1528430f954a703bdd756b5393782d8f642977bee95fc6b645f6583c4ef","qualityScore":51}');
