INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('motoya0118/pavlok_CLI_agent/slack', 'slack', 'motoya0118', 'pavlok_CLI_agent', 'community', 'slack motoya0118 pavlok_CLI_agent community The Slack skill enables AI agents to post questions and replies using scripts/slack.py, benefiting developers who need to automate Slack interactions. Slack CLI Agent允许您使用Python脚本自动化任务。使用uv命令行工具运行脚本并与Slack集成 Slack CLIエージェントは、Pythonスクリプトを使用してタスクを自動化することを可能にします。uvコマンドラインツールを使用してスクリプトを実行し、Slackと統合します Slack CLI 에이전트는 Python 스크립트를 사용하여 태스크를 자동화할 수 있습니다. uv 명령줄 도구를 사용하여 스크립트를 실행하고 Slack과 통합합니다 Configura Slack para agentes de CLI con scripts de Python y ejecución de comandos personalizados para mejorar la productividad Configurez Slack pour les agents CLI avec des scripts Python et des commandes personnalisées pour améliorer la productivité Richten Sie Slack für CLI-Agenten mit Python-Skripten und benutzerdefinierten Befehlen ein, um die Produktivität zu verbessern O Slack é uma plataforma de colaboração que pode ser automatizada com scripts Python e CLI para melhorar a produtividade Slack - это платформа для сотрудничества, которую можно автоматизировать с помощью скриптов Python и CLI для повышения производительности السلاك هو منصة للتعاون يمكن تخصيصها باستخدام سكريبتات بايثون وCLI لتحسين الإنتاجية how to use slack with AI agents slack setup guide for developers slack alternative for automation slack vs microsoft teams for AI integration slack install for python scripts slack api for automated interactions Slack自动化 CLI Agent Python脚本 uv命令行工具 Slack集成 自动化任务 提高生产力 Posts questions and waits for the first reply using scripts/slack.py Supports posting replies into existing threads with --mode reply Utilizes --interval and --follow-up-message for customized interaction Accepts question or reply text as input for flexible messaging Employs uv run for executing scripts with specified parameters Slack is a CLI agent skill that allows posting questions and replies using Python scripts, facilitating automated interactions within Slack threads.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('michaeltschreiber/logger/logfire-read', 'community', 'michaeltschreiber', 'logger', 'michaeltschreiber/logger', 'logfire-read', 0, 0, 51, '2026-03-08T01:57:15.374Z', '2026-03-08T02:04:32.974Z', 'cfb10ead6df30e9c1c07ba8d934b23698b015dfa001ea4be9094f450c4100d08', '{"id":"michaeltschreiber/logger/logfire-read","name":"logfire-read","description":{"en":"The logfire-read skill enables structured logging of Python function calls for use with containerized applications and Docker Compose, benefiting developers working with JSONL output.","zh":"Logfire Read 技术用于记录 Python 函数调用，实现结构化日志记录，适用于容器化应用和 Docker Compose","ja":"Logfire Read は Python 関数コールを構造化ログ化する技術で、コンテナ化アプリケーションと Docker Compose で使用","ko":"Logfire Read는 파이썬 함수 호출을 구조화 로깅하는 기술로, 컨테이너화된 애플리케이션 및 Docker Compose에서 사용","es":"Logfire-read es una habilidad para registrar llamadas a funciones de Python de manera estructurada para aplicaciones contenerizadas y docker compose.","fr":"Logfire-read est une compétence pour enregistrer des appels de fonctions Python de manière structurée pour les applications conteneurisées et docker compose.","de":"Logfire-read ist eine Fähigkeit zum strukturierten Protokollieren von Python-Funktionenaufrufen für containerisierte Anwendungen und docker compose.","pt":"O Logfire-Read é uma habilidade que permite o registro estruturado de chamadas de funções Python em aplicativos containerizados e Docker Compose.","ru":"Logfire-Read - это навык, который позволяет выполнять структурированный журнал вызовов функций Python в контейнеризированных приложениях и Docker Compose.","ar":"Logfire-Read هو مهارة يسمح بتسجيل هيكلي لمكالمات دوال Python في تطبيقات المحتوى الإصطناعي والdocker compose"},"seo":{"title":{"en":"logfire-read: Structured Logging Setup Guide for AI Agents","zh":"Logfire Read 技术指南：结构化日志记录","ja":"Logfire Read セットアップガイド：Python 関数コールの構造化ログ","ko":"Logfire Read 설정 가이드: 파이썬 함수 호출 구조화 로깅","es":"Guía de configuración de logfire-read para aplicaciones c...","fr":"Guide d''installation de logfire-read pour les application...","de":"Einrichtungsleitfaden für logfire-read in containerisiert...","pt":"Guia de Configuração do Logfire-Read para Aplicativos Con...","ru":"Настройка Logfire-Read для контейнеризированных приложени...","ar":"دليل إعداد Logfire-Read لأدوات الإصطناعي المحتوية"},"description":{"en":"Discover how to read Logfire records with JSONL output using logfire-read skill. Learn to set up and use the skill with containerized applications and Docker...","zh":"使用 Logfire Read 技术记录 Python 函数调用，实现结构化日志记录，适用于容器化应用和 Docker Compose","ja":"Logfire Read を使用して Python 関数コールを構造化ログ化し、コンテナ化アプリケーションと Docker Compose で使用","ko":"Logfire Read를 사용하여 파이썬 함수 호출을 구조화 로깅하고, 컨테이너화된 애플리케이션 및 Docker Compose에서 사용","es":"Aprende a configurar logfire-read para aplicaciones contenerizadas y docker compose con nuestra guía paso a paso","fr":"Découvrez comment configurer logfire-read pour les applications conteneurisées et docker compose avec notre guide étape par étape","de":"Erfahren Sie, wie Sie logfire-read für containerisierte Anwendungen und docker compose konfigurieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Logfire-Read para registrar chamadas de funções Python em aplicativos containerizados e Docker Compose","ru":"Узнайте, как настроить Logfire-Read для регистрации вызовов функций Python в контейнеризированных приложениях и Docker Compose с помощью ИИ Агенты","ar":"تعرف على كيفية إعداد Logfire-Read لتسجيل مكالمات الدوال Python في تطبيقات المحتوى الإصطناعي والdocker compose"},"definition":{"en":"logfire-read is a skill that provides structured logging of Python function calls using JSONL output for containerized applications and Docker Compose","zh":"Logfire Read 是一种用于记录 Python 函数调用结构化日志的技术","ja":"Logfire Read は Python 関数コールの構造化ログを記録する技術","ko":"Logfire Read는 파이썬 함수 호출의 구조화 로깅을 기록하는 기술","es":"Logfire-read es una herramienta de registro de aplicaciones que permite la salida JSONL para aplicaciones contenerizadas","fr":"Logfire-read est un outil de journalisation d''applications qui permet la sortie JSONL pour les applications conteneurisées","de":"Logfire-read ist ein Protokollierungstool für Anwendungen, das die JSONL-Ausgabe für containerisierte Anwendungen ermöglicht","pt":"Logfire-Read é uma habilidade de registro de logs que utiliza JSONL para saída","ru":"Logfire-Read - это навык регистрации журналов, который использует JSONL для вывода","ar":"Logfire-Read هو مهارة لتسجيل السجلات التي تستخدم JSONL للخروج"},"features":{"en":["Loads .env files from the repo root for configuration","Runs JSONL reader using python scripts/logfire-fetch.py","Supports targeted queries using the agent helper","Includes a bundled script for reading logs with specific filters","Utilizes Docker Compose for containerized applications","Generates output in JSONL format for easy parsing"],"zh":["支持 JSONL 输出","使用 repo 的 reader 实用工具","支持容器化应用和 Docker Compose","提供 agent 友好 CLI","支持目标查询","使用 Python 脚本运行"],"ja":["JSONL 出力をサポート","レポジトリの reader ユーティリティを使用","コンテナ化アプリケーションと Docker Compose をサポート","エージェント フレンドリー CLI を提供","ターゲット クエリをサポート","Python スクリプトを使用して実行"],"ko":["JSONL 출력 지원","레포지토리의 reader 유틸리티 사용","컨테이너화된 애플리케이션 및 Docker Compose 지원","에이전트 친화적인 CLI 제공","목표 쿼리 지원","파이썬 스크립트 사용하여 실행"],"es":["Registro estructurado de llamadas a funciones de Python","Compatibilidad con aplicaciones contenerizadas y docker compose","Salida JSONL para fácil análisis de registros","Uso de utilidades de lectura de registros para recuperar registros","Soporte para consultas dirigidas con la ayuda del agente"],"fr":["Enregistrement structuré des appels de fonctions Python","Compatibilité avec les applications conteneurisées et docker compose","Sortie JSONL pour une analyse facile des journaux","Utilisation des utilitaires de lecture de journaux pour récupérer les journaux","Prise en charge des