INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sologa/codex-pipeline/pytdc', 'pytdc', 'Sologa', 'codex-pipeline', 'community', 'pytdc Sologa codex-pipeline community pytdc provides AI-ready datasets and benchmarks for drug discovery and development, benefiting researchers and developers. It offers curated datasets with standardized evaluation metrics. PyTDC 是一个开源科学平台，提供 AI 即时数据集和基准，用于药物发现和开发 PyTDC は、AI エージェントによるデータセットとベンチマークを提供するオープンソースの科学プラットフォームです PyTDC는 AI 에이전트를 위한 데이터셋과 벤치마크를 제공하는 오픈소스 과학 플랫폼입니다 pytdc es una plataforma de ciencia abierta que proporciona conjuntos de datos y benchmarks listos para inteligencia artificial para el descubrimiento y desarrollo de fármacos pytdc est une plateforme de science ouverte qui fournit des ensembles de données et des benchmarks prêts pour l''intelligence artificielle pour la découverte et le développement de médicaments pytdc ist eine Open-Science-Plattform, die AI-bereite Datensätze und Benchmarks für die Arzneimittelentwicklung und -forschung bereitstellt PyTDC é uma plataforma de ciência aberta que fornece conjuntos de dados e benchmarks prontos para IA para descoberta e desenvolvimento de drogas. Oferece dados curados que abrangem todo o pipeline terapêutico. PyTDC — это открытая научная платформа, предоставляющая наборы данных и бенчмарки, готовые для ИИ, для открытия и разработки лекарств. Предоставляет отобранные данные, охватывающие весь терапевтический пайплайн. PyTDC هي منصة العلوم المفتوحة التي توفر مجموعات بيانات وبنوك الاختبار جاهزة للذكاء الاصطناعي لاكتشاف وتطوير الأدوية. توفر بيانات مدققة تغطي toàn مسار العلاج how to use pytdc pytdc alternative pytdc install what is pytdc pytdc vs other platforms pytdc setup guide pytdc for drug discovery pytdc benchmarks pytdc datasets pytdc for AI agents PyTDC AI 即时数据集 基准 标准化评估指标 药物发现 开发 开源科学平台 AI エージェント Provides AI-ready datasets spanning the entire therapeutics pipeline Offers standardized evaluation metrics and meaningful data splits Includes datasets for single-instance prediction, such as molecular properties Supports multi-instance prediction, including drug-target interactions and DDI Enables generation tasks, such as molecule generation and retrosynthesis Organizes datasets into three categories for easy access pytdc is an open-science platform providing access to curated datasets and benchmarks for therapeutics pipeline, including molecular properties and drug-target interactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RainerSeventeen/paper-tracker/plan-implement-dual-review', 'community', 'RainerSeventeen', 'paper-tracker', 'RainerSeventeen/paper-tracker', 'plan-implement-dual-review', 0, 0, 51, '2026-03-08T01:57:15.385Z', '2026-03-08T02:05:48.501Z', 'ed1beae56ef19287415d1cd4709b050b03ab33932f212856bdff7dbfb6ab2e1f', '{"id":"RainerSeventeen/paper-tracker/plan-implement-dual-review","name":"plan-implement-dual-review","description":{"en":"The plan-implement-dual-review skill automates code review by generating reports from arXiv searches and implementing code based on plans. It benefits developers by simplifying the review process.","zh":"计划实施双重审查是一种将代码实现和规则自修复相结合的流程，旨在让主线程只承载高价值决策信息","ja":"プラン実装デュアルレビューは、コードの実装とルールの自己修復を組み合わせたプロセスであり、メインスレッドに高価値の意思決定情報のみを負担させることを目的としています","ko":"계획實施雙重審查는 코드 구현과 규칙 自己修复를 결합한 프로세스로, 메인 스레드에 높은 가치의 의사 결정 정보만을 담당시키는 것을 목적으로 한다","es":"Plan-implement-dual-review es un proceso que combina implementación de código y revisión dual para mejorar la calidad del código. Utiliza herramientas de AI para automatizar la revisión.","fr":"Plan-implement-dual-review est un processus qui combine la mise en œuvre de code et la revue dual pour améliorer la qualité du code. Il utilise des outils d''IA pour automatiser la revue.","de":"Plan-implement-dual-review ist ein Prozess, der Code-Implementierung und duale Überprüfung kombiniert, um die Code-Qualität zu verbessern. Es verwendet AI-Tools, um die Überprüfung zu automatisieren.","pt":"O plan-implement-dual-review é uma habilidade que permite implementar código com revisão dual, melhorando a qualidade do código. Ele segue um fluxo de trabalho estruturado para garantir a consistência e a qualidade do código.","ru":"План-реализация двойного обзора - это навык, который позволяет реализовать код с двойным обзором, улучшая качество кода. Он следует структурированному рабочему процессу для обеспечения согласованности и качества кода.","ar":"خطة التنفيذ المراجعة المزدوجة هي مهارة تتيح تنفيذ код مع مراجعة مزدوجة، مما يحسن جودة الكود. تتتبع عملية عمل مهيكلة لضمان الاتساق وجودة الكود."},"seo":{"title":{"en":"plan-implement-dual-review: Automated Code Review Setup G...","zh":"计划实施双重审查 Setup Guide","ja":"プラン実装デュアルレビューのためのAIエージェントベストプラクティス","ko":"계획實施雙重審查를 위한 AI 툴 설정 가이드","es":"Guía de Configuración para plan-implement-dual-review: Im...","fr":"Guide de Configuration pour plan-implement-dual-review : ...","de":"Konfigurationsleitfaden für plan-implement-dual-review: C...","pt":"Guia de Configuração do plan-implement-dual-review: Imple...","ru":"Настройка план-реализация двойного обзора: Руководство по...","ar":"دليل إعداد خطة التنفيذ المراجعة المزدوجة: إعداد код مع مر..."},"description":{"en":"Streamline your code review process with plan-implement-dual-review. Learn how to automate arXiv searches and generate JSON/Markdown reports. Get started now!","zh":"了解计划实施双重审查的技术细节，包括代码规则和结构性审查","ja":"プラン実装デュアルレビューのための技術的な詳細を学ぶ、コードルールと構造的レビューを含む","ko":"계획實施雙重審查의 기술적인 세부사항을 배우다, 코드 규칙과 구조적审查를 포함한다","es":"Aprende a configurar plan-implement-dual-review para implementar código y revisión dual con herramientas de AI como agentes de inteligencia artificial","fr":"Découvrez comment configurer plan-implement-dual-review pour mettre en œuvre du code et une revue dual avec des outils d''IA tels que les agents d''intelligenc...","de":"Erfahren Sie, wie Sie plan-implement-dual-review konfigurieren, um Code und duale Überprüfung mit AI-Tools wie künstlichen Intelligenzagenten zu implementieren","pt":"Aprenda a configurar o plan-implement-dual-review para implementar código com revisão dual e melhore a qualidade do seu código","ru":"Узнайте, как настроить план-реализация двойного обзора для реализации кода с двойным обзором и улучшению качества кода","ar":"تعرف على كيفية إعداد خطة التنفيذ المراجعة المزدوجة لتنفيذ код مع مراجعة مزدوجة وتحسين جودة الكود"},"definition":{"en":"plan-implement-dual-review is a skill that automates the code review process by generating reports and implementing code based on predefined plans and rules.","zh":"计划实施双重审查是指将计划文件路径、分支创建和验证方式等输入参数结合起来，进行代码实现和结构性审查的过程","ja":"プラン実装デュアルレビューとは、プランファイルパス、ブランチの作成、バリデーション方式などを含む入力パラメータを組み合わせて、コードの実装と構造的レビューを行うプロセスを指します","ko":"계획實施雙重審查는 계획 파일 경로, 분기 생성, 검증 방식 等을 포함한 입력 매개변수를 결합하여, 코드 구현과 구조적审查를 수행하는 프로세스를 말한다","es":"Plan-implement-dual-review es un enfoque de desarrollo de software que combina implementación de código y revisión dual para garantizar la calidad del código","fr":"Plan-implement-dual-review est une approche de développement de logiciels qui combine la mise en œuvre de code et la revue dual pour garantir la qualité du code","de":"Plan-implement-dual-review ist ein Ansatz für die Software-Entwicklung, der Code-Implementierung und duale Überprüfung kombiniert, um die Code-Qualität zu gewährleisten","pt":"O plan-implement-dual-review é uma habilidade que combina implementação de código com revisão dual para melhorar a qualidade do código","ru":"План-реализация двойного обзора - это навык, который сочетает реализацию кода с двойным обзором для улучшения качества кода","ar":"خطة التنفيذ المراجعة المزدوجة هي مهارة تجمع بين تنفيذ الكود والمراجعة المزدوجة لتحسين جودة الكود"},"features":{"en":["Automatically searches arXiv by subject and keyword","Extracts title, author, and abstract information","Generates JSON, Markdown, and HTML reports using AI summarization","Implements code based on plans and rules defined in .ai_docs/rules/code_rules.md","Performs structural code review based on .ai_docs/rules/code_review_structure_rules.md","Supports automatic branch creation and switching"],"zh":["代码规则遵守 `.ai_docs/rules/code_rules.md`","结构性审查遵守 `.ai_docs/rules/code_review_structure_rules.md`","支持创建并切换新分支","验证方式支持优先执行计划中要求的测试","支持显式假设并继续执行"],"ja":["コードルールが `.ai_docs/rules/code_rules.md` に準拠","構造的レビューが `.ai_docs/rules/code_review_structure_rules.md` に準拠","新しいブランチの作成と切り替えをサポート","バリデーション方式がプラン中の要求されたテストを優先的に実行","明示的な仮定を続行することをサポート"],"ko":["コード 규칙이 `.ai_docs/rules/code_rules.md`에 준수","구조적审查가 `.ai_docs/rules/code_review_structure_rules.md`에 준수","新的 브랜치 생성과 전환을 지원","검증 방식이 계획 중 요구된 테스트를 우선적으로 실행","명시적인 가정을 계속 진행하는 것을 지원"],"es":["Implementación de código en una nueva rama","Revisión dual para garantizar la calidad del código","Uso de herramientas de AI para automatizar la revisión","Compatibilidad con formato JSON y Markdown","Soporte para la creación y conmutación de nuevas ramas"],"fr":["Mise en œuvre de code dans une nouvelle branche","Revue dual pour garantir la qualité du code","Utilisation d''outils d''IA pour automatiser la revue","Compatibilité avec les formats JSON et Markdown","Prise en charge de la création et de la commutation de nouvelles branches"],"de":["Code-Implementierung in einem neuen Branch","Duale Überprüfung zur Gewährleistung der Code-Qualität","Verwendung von AI-Tools zur Automatisierung der Überprüfung","Kompatibilität mit JSON- und Markdown-Formaten","Unterstützung für die Erstellung und Umschaltung neuer Branches"],"pt":["Implementação de código com revisão dual","Fluxo de trabalho estruturado para garantir a consistência e a qualidade do código","Suporte a criação de novos branches","Verificação de teste priorizada","Leitura completa do arquivo de plano","Integração com o arquivo de regras de código"],"ru":["Реализация кода с двойным обзором","Структурированный рабочий процесс для обеспечения согласованности и качества кода","Поддержка создания новых веток","Приоритетная проверка тестов","Полное чтение файла плана","Интеграция с файлом правил кода"],"ar":["تنفيذ الكود مع المراجعة المزدوجة","عملية عمل مهيكلة لضمان الاتساق وجودة الكود","دعم إنشاء فروع جديدة","فحص اختبار متقدم","قراءة كاملة لملف الخطة","التكامل مع ملف قواعد الكود"]},"keywords":{"en":["how to use plan-implement-dual-review","plan-implement-dual-review setup guide","automated code review tools","arXiv search api","ai powered code review","plan-implement-dual-review vs manual code review","plan-implement-dual-review install","code review automation best practices","plan-implement-dual-review alternative solutions"],"zh":["计划实施双重审查","代码规则","结构性审查","AI工具","代码实现","规则自修复","主线程","高价值决策信息"],"ja":["プラン実装デュアルレビュー","コードルール","構造的レビュー","AIエージェント","コードの実装","ルールの自己修復","メインスレッド","高価値の意思決定情報"],"ko":["계획實施雙重審查","コード 규칙","구조적审查","AI 툴","コード 구현","규칙 自己修复","메인 스레드","높은 가치의 의사 결정 정보"],"es":["plan-implement-dual-review","herramientas de AI","agentes de inteligencia artificial","desarrollo de software","implementación de código","revisión dual","calidad del código","automatización de la revisión"],"fr":["plan-implement-dual-review","outils d''IA","agents d''intelligence artificielle","développement de logiciels","mise en œuvre de code","revue dual","qualité du code","automatisation de la revue"],"de":["plan-implement-dual-review","AI-Tools","künstliche Intelligenzagenten","Software-Entwicklung","Code-Implementierung","duale Überprüfung","Code-Qualität","Automatisierung der Überprüfung"],"pt":["plan-implement-dual-review","implementação de código","revisão dual","qualidade do código","fluxo de trabalho","criação de novos branches","verificação de teste","leitura de arquivo de plano","integração com regras de código","ИИ Агенты","ferramentas de desenvolvimento"],"ru":["план-реализация двойного обзора","реализация кода","двойной обзор","качество кода","рабочий процесс","создание новых веток","проверка тестов","чтение файла плана","интеграция с правилами кода","ИИ Агенты","инструменты разработки"],"ar":["خطة التنفيذ المراجعة المزدوجة","تنفيذ الكود","المراجعة المزدوجة","جودة الكود","عملية العمل","إنشاء فروع جديدة","فحص الاختبار","قراءة ملف الخطة","التكامل مع قواعد الكود","أدوات التطوير","وكالات الذكاء الاصطناعي"]}},"owner":"RainerSeventeen","repo":"paper-tracker","repoPath":"RainerSeventeen/paper-tracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.385Z","topics":[],"category":"community","skillMd":{"name":"plan-implement-dual-review","description":"当用户提供项目计划文件并希望按计划落地代码时使用。该技能用于主agent编排两个subagent：subagent1读取计划并在新分支实现代码、随后依据 .ai_docs/rules/code_rules.md 自审并直接修复；subagent2再依据 .ai_docs/rules/code_review_structure_rules.md 做结构性审查并上报问题；主agent最终仅向用户汇报第三步的结构性问题。","bodyPreview":"# Plan Implement Dual Review\n\n## Overview\n\n将“按计划实现代码 + 规则自修复 + 结构性复审 + 主线程最小汇报”变成固定流程。\n目标是让主线程只承载高价值决策信息，不重复展开实现细节。\n其中：\n- 撰写/实现阶段统一遵守 `.ai_docs/rules/code_rules.md`。\n- 结构性审查阶段统一遵守 `.ai_docs/rules/code_review_structure_rules.md`。\n\n## Required Inputs\n\n在开始前收集并确认：\n- 计划文件路径（用户提供）\n- 是否允许创建并切换新分支（默认允许）\n- 验证方式（优先执行计划中要求的测试；若未定义，执行项目默认测试）\n\n若计划缺失关键约束，先补最少问题；其余采用显式假设并继续。\n\n## Workflow\n\n### Step 1: Subagent1 implement plan on a new branch\n\n创建 `subagent1` 并分配唯一职责：按计划实现。\n\n对 `subagent1` 的明确要求：\n- 完整阅读计划文件，不得只读摘要","body":"# Plan Implement Dual Review\n\n## Overview\n\n将“按计划实现代码 + 规则自修复 + 结构性复审 + 主线程最小汇报”变成固定流程。\n目标是让主线程只承载高价值决策信息，不重复展开实现细节。\n其中：\n- 撰写/实现阶段统一遵守 `.ai_docs/rules/code_rules.md`。\n- 结构性审查阶段统一遵守 `.ai_docs/rules/code_review_structure_rules.md`。\n\n## Required Inputs\n\n在开始前收集并确认：\n- 计划文件路径（用户提供）\n- 是否允许创建并切换新分支（默认允许）\n- 验证方式（优先执行计划中要求的测试；若未定义，执行项目默认测试）\n\n若计划缺失关键约束，先补最少问题；其余采用显式假设并继续。\n\n## Workflow\n\n### Step 1: Subagent1 implement plan on a new branch\n\n创建 `subagent1` 并分配唯一职责：按计划实现。\n\n对 `subagent1` 的明确要求：\n- 完整阅读计划文件，不得只读摘要\n- 开始实现前先阅读 `.ai_docs/rules/code_rules.md`，并在整个实现阶段持续遵守\n- 基于计划创建新分支并实现代码改动\n- 分支命名优先遵循计划内约定；若计划未给出，使用 `codex/<feature-summary>`\n- 在实现过程中记录：改动文件、关键设计决策、测试结果\n\n可直接复用的指令模板：\n\n```text\n你负责按计划落地实现，不做结构性审查。请完成：\n1) 读取计划文件：<PLAN_PATH>\n2) 阅读并严格遵守 .ai_docs/rules/code_rules.md\n3) 创建并切换新分支（遵循计划命名；无命名时用需要遵守 .ai_docs/rules/git_rules.md）\n4) 按计划完成代码修改并执行必要测试\n5) 输出：分支名、变更文件列表、测试结果、剩余风险\n```\n\n### Step 2: Subagent1 self-review by code rules and fix directly\n\n在 Step 1 完成后，继续让 `subagent1` 执行规则自审并直接修复问题。\n\n对 `subagent1` 的明确要求：\n- 读取并严格遵守 `.ai_docs/rules/code_rules.md`\n- 逐项检查刚完成的改动，发现问题直接修复，不进入上报\n- 修复后重新执行受影响测试\n- 输出：自审发现项、对应修复、最终测试结果\n\n可直接复用的指令模板：\n\n```text\n继续处理你刚才的改动：\n1) 阅读 .ai_docs/rules/code_rules.md\n2) 按规则审查你的所有改动\n3) 有问题直接修正并重新测试\n4) 输出：发现的问题与修复清单、最终测试结果\n```\n\n### Step 3: Subagent2 perform structural review and report\n\n创建 `subagent2`，只做结构性审查，不直接改代码。\n\n对 `subagent2` 的明确要求：\n- 阅读 `.ai_docs/rules/code_review_structure_rules.md`\n- 审查范围仅限当前分支改动\n- 仅输出“结构性问题”与证据，不输出风格性建议\n- 每条问题包含：严重级别、文件路径、问题描述、影响、建议方向\n\n可直接复用的指令模板：\n\n```text\n你只做结构性审查，不要修改代码：\n1) 阅读 .ai_docs/rules/code_review_structure_rules.md\n2) 仅审查当前分支改动的结构性问题\n3) 输出问题清单：severity/file/issue/impact/suggestion\n4) 若无结构性问题，明确输出“无结构性问题”\n```\n\n### Step 4: Main agent report only structural issues\n\n主agent只向用户汇报 Step 3 的结果。\n\n必须遵守：\n- 仅汇报结构性问题清单（或“无结构性问题”）\n- 不展开 Step 1/2 的实现过程细节\n- 不追加与结构无关的建议\n\n## Output Contract\n\n主线程固定输出：\n\n1. `结构性问题`：按严重级别排序（高 -> 中 -> 低）\n2. `结论`：\n   - 有问题：`请你拍板是否先修复以上结构性问题再继续。`\n   - 无问题：`本轮结构性审查通过。`\n\n## Standard Reply Template\n\n在主线程汇报时，直接套用以下模板之一。\n\n### Template A: 有结构性问题\n\n```markdown\n结构性问题\n1. [高|中|低] <问题标题>\n   - 文件: `<absolute-or-workspace-path>:<line>`\n   - 问题: <结构性问题描述>\n   - 影响: <可能导致的行为/维护风险>\n   - 建议方向: <修复方向，不展开实现细节>\n\n2. [高|中|低] <问题标题>\n   - 文件: `<absolute-or-workspace-path>:<line>`\n   - 问题: <结构性问题描述>\n   - 影响: <可能导致的行为/维护风险>\n   - 建议方向: <修复方向，不展开实现细节>\n\n结论\n请你拍板是否先修复以上结构性问题再继续。\n```\n\n### Template B: 无结构性问题\n\n```markdown\n结构性问题\n无结构性问题。\n\n结论\n本轮结构性审查通过。\n```\n\n## Guardrails\n\n- Step 1 的实现必须以 `.ai_docs/rules/code_rules.md` 为编码准绳，不能跳过。\n- Step 2 必须由 `subagent1` 执行且“发现即修复”，不能跳过。\n- Step 3 必须以 `.ai_docs/rules/code_review_structure_rules.md` 为审查准绳，且由独立的 `subagent2` 执行，不能复用 `subagent1` 结论替代。\n- 主agent最终输出不得混入实现细节、风格性意见、或非结构问题。\n- 若 Step 3 证据不足，标记为“待确认”，不得伪造确定性结论。\n"},"lastSynced":"2026-03-08T02:05:48.501Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing automated arXiv search and code implementation based on predefined plans.","zh":"适用于需要自动化arXiv搜索和基于预定义计划的代码实现的代码审查代理。","ja":"自動化arXiv検索と予め定義されたプランに基づくコード実装が必要なコードレビュー代理に適しています。","ko":"自動화된 arXiv 검색과 정의된 계획에 기반한 코드 구현이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Ideal para Agentes de Revisión de Código que necesitan búsqueda automatizada en arXiv y implementación de código basada en planes predefinidos.","fr":"Idéal pour les Agents de Revue de Code ayant besoin d''une recherche automatique arXiv et de mise en œuvre de code basée sur des plans préétablis.","de":"Ideal für Code-Review-Agenten, die eine automatisierte arXiv-Suche und eine Code-Implementierung basierend auf vordefinierten Plänen benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de busca automática arXiv e implementação de código com base em planos pré-definidos.","ru":"Идеально для агентов кодового обзора, которым необходим автоматизированный поиск arXiv и реализация кода на основе предустановленных планов.","ar":"مثالي للوكلاء المراجعة الكودية الذين يحتاجون إلى بحث أوتوماتيكي arXiv وتنفيذ الكود بناءً على خطط محددة مسبقًا."},"recommendation":{"en":"Empowers agents to automate code review by generating reports from arXiv searches and implementing code based on plans, utilizing `.ai_docs/rules/code_rules.md` and `.ai_docs/rules/code_review_structure_rules.md` for structured code review and implementation.","zh":"赋予代理自动化代码审查的能力，通过从arXiv搜索生成报告并基于计划实现代码，利用`.ai_docs/rules/code_rules.md`和`.ai_docs/rules/code_review_structure_rules.md`进行结构化代码审查和实现。","ja":"代理にコードレビューの自動化を可能にする能力を与え、arXiv検索からレポートを生成し、プランに基づいてコードを実装する。`.ai_docs/rules/code_rules.md`と`.ai_docs/rules/code_review_structure_rules.md`を使用して、構造化されたコードレビューと実装を行う。","ko":"에이전트가 코드 리뷰를 자동화할 수 있는 능력을 부여하여 arXiv 검색에서 보고서를 생성하고 계획을 기반으로 코드를 구현한다. `.ai_docs/rules/code_rules.md`와 `.ai_docs/rules/code_review_structure_rules.md`를 사용하여 구조화된 코드 리뷰와 구현을 수행한다.","es":"Habilita a los agentes a automatizar la revisión de código generando informes desde búsquedas en arXiv e implementando código basado en planes, utilizando `.ai_docs/rules/code_rules.md` y `.ai_docs/rules/code_review_structure_rules.md` para una revisión y implementación de código estructuradas.","fr":"Permet aux agents d''automatiser la revue de code en générant des rapports à partir de recherches arXiv et en mettant en œuvre du code basé sur des plans, en utilisant `.ai_docs/rules/code_rules.md` et `.ai_docs/rules/code_review_structure_rules.md` pour une revue et une mise en œuvre de code structurées.","de":"Ermächtigt die Agenten, Code-Reviews zu automatisieren, indem sie Berichte aus arXiv-Suchen generieren und Code basierend auf Plänen implementieren, wobei sie `.ai_docs/rules/code_rules.md` und `.ai_docs/rules/code_review_structure_rules.md` für eine strukturierte Code-Review und -Implementierung verwenden.","pt":"Habilita os agentes a automatizar a revisão de código, gerando relatórios de buscas arXiv e implementando código com base em planos, utilizando `.ai_docs/rules/code_rules.md` e `.ai_docs/rules/code_review_structure_rules.md` para revisão e implementação de código estruturada.","ru":"Наделяет агентов возможностью автоматизировать обзор кода, генерируя отчеты из поисков arXiv и реализуя код на основе планов, используя `.ai_docs/rules/code_rules.md` и `.ai_docs/rules/code_review_structure_rules.md` для структурированного обзора и реализации кода.","ar":"يمنح الوكلاء القدرة على تطبيق آلي لمراجعة الكود من خلال توليد تقارير من عمليات البحث arXiv وتنفيذ الكود بناءً على الخطط، باستخدام `.ai_docs/rules/code_rules.md` و `.ai_docs/rules/code_review_structure_rules.md` لمراجعة الكود المنظمة وتنفيذها."},"useCases":{"en":["Automating code review for new feature implementations","Generating reports from arXiv searches for research-based coding projects","Implementing code based on predefined plans with structured review and validation"],"zh":["自动化新功能实现的代码审查","为基于研究的编码项目生成arXiv搜索报告","基于预定义计划和结构化审查及验证实现代码"],"ja":["新機能実装のコードレビューの自動化","研究に基づくコーディングプロジェクトのためのarXiv検索レポートの生成","予め定義されたプランと構造化されたレビューと検証に基づくコードの実装"],"ko":["신기능 구현을 위한 코드 리뷰 자동화","연구 기반 코딩 프로젝트를 위한 arXiv 검색 보고서 생성","정의된 계획 및 구조화된 리뷰 및 검증을 기반으로 코드 구현"],"es":["Automatizar la revisión de código para nuevas implementaciones de características","Generar informes desde búsquedas en arXiv para proyectos de codificación basados en la investigación","Implementar código basado en planes predefinidos con revisión y validación estructuradas"],"fr":["Automatiser la revue de code pour de nouvelles mises en œuvre de fonctionnalités","Générer des rapports à partir de recherches arXiv pour des projets de codage basés sur la recherche","Mettre en œuvre du code basé sur des plans préétablis avec une revue et une validation structurées"],"de":["Automatisierung der Code-Review für neue Feature-Implementierungen","Erstellung von Berichten aus arXiv-Suchen für forschungsbasierte Codierungsprojekte","Implementierung von Code basierend auf vordefinierten Plänen mit strukturierter Überprüfung und Validierung"],"pt":["Automatizar a revisão de código para implementações de recursos novos","Gerar relatórios de buscas arXiv para projetos de codificação baseados em pesquisa","Implementar código com base em planos pré-definidos com revisão estruturada e validação"],"ru":["Автоматизировать обзор кода для реализации новых функций","Генерировать отчеты из поисков arXiv для проектов кодирования, основанных на исследовании","Реализовывать код на основе предустановленных планов со структурированным обзором и проверкой"],"ar":["تطبيق آلي لمراجعة الكود لتنفيذ ميزات جديدة","توليد تقارير من عمليات البحث arXiv لمشاريع الكود التي تعتمد على البحث","تنفيذ الكود بناءً على خطط محددة مسبقًا مع مراجعة منظمة وتصديق"]},"limitations":{"en":["Requires access to arXiv search functionality","Needs predefined plan files with specific formats and structures","Dependent on `.ai_docs/rules/code_rules.md` and `.ai_docs/rules/code_review_structure_rules.md` for code implementation and review guidelines"],"zh":["需要访问arXiv搜索功能","需要具有特定格式和结构的预定义计划文件","依赖于`.ai_docs/rules/code_rules.md`和`.ai_docs/rules/code_review_structure_rules.md`进行代码实现和审查指南"],"ja":["arXiv検索機能へのアクセスが必要","特定の形式と構造を持つ予め定義されたプランファイルが必要","`.ai_docs/rules/code_rules.md`と`.ai_docs/rules/code_review_structure_rules.md`に依存してコード実装とレビューのガイドラインを提供する"],"ko":["arXiv 검색 기능에 대한 액세스가 필요합니다","특정 형식 및 구조를 갖춘 정의된 계획 파일이 필요합니다","`.ai_docs/rules/code_rules.md`와 `.ai_docs/rules/code_review_structure_rules.md`에 의존하여 코드 구현 및 리뷰 가이드라인을 제공합니다"],"es":["Requiere acceso a la funcionalidad de búsqueda en arXiv","Necesita archivos de planes predefinidos con formatos y estructuras específicos","Depende de `.ai_docs/rules/code_rules.md` y `.ai_docs/rules/code_review_structure_rules.md` para las pautas de implementación y revisión de código"],"fr":["Nécessite un accès à la fonctionnalité de recherche arXiv","A besoin de fichiers de plans préétablis avec des formats et des structures spécifiques","Dépend de `.ai_docs/rules/code_rules.md` et `.ai_docs/rules/code_review_structure_rules.md` pour les directives de mise en œuvre et de revue de code"],"de":["Benötigt Zugriff auf die arXiv-Suchfunktion","Benötigt vordefinierte Plan-Dateien mit spezifischen Formaten und Strukturen","Hängt von `.ai_docs/rules/code_rules.md` und `.ai_docs/rules/code_review_structure_rules.md` für die Richtlinien zur Code-Implementierung und -Überprüfung ab"],"pt":["Requer acesso à funcionalidade de busca arXiv","Necessita de arquivos de plano pré-definidos com formatos e estruturas específicos","Dependente de `.ai_docs/rules/code_rules.md` e `.ai_docs/rules/code_review_structure_rules.md` para diretrizes de implementação e revisão de código"],"ru":["Требует доступа к функциональности поиска arXiv","Требует предустановленных файлов планов с определенными форматами и структурами","Зависит от `.ai_docs/rules/code_rules.md` и `.ai_docs/rules/code_review_structure_rules.md` для руководства по реализации и обзору кода"],"ar":["يتطلب الوصول إلى وظيفة البحث arXiv","يحتاج إلى ملفات خطة محددة مسبقًا ذات صيغ وتراكيب محددة","يعتمد على `.ai_docs/rules/code_rules.md` و `.ai_docs/rules/code_review_structure_rules.md` لمبادئ توجيه تنفيذ الكود ومراجعته"]},"version":4},"contentHash":"ed1beae56ef19287415d1cd4709b050b03ab33932f212856bdff7dbfb6ab2e1f","qualityScore":51}');
