INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Haseeb-Arshad/visual-storyboard/manimce-best-practices', 'manimce-best-practices', 'Haseeb-Arshad', 'visual-storyboard', 'community', 'manimce-best-practices Haseeb-Arshad visual-storyboard community The manimce-best-practices skill provides developers with in-depth guides on core concepts, creation, and transformation techniques for building complex scenes and animations. It benefits developers working with manimce. ManimCE 最佳实践提供了场景结构、物体类型和动画类的详细指导，帮助开发者提高动画开发技能 ManimCE ベストプラクティスは、シーン構造、オブジェクトタイプ、アニメーションクラスに関する詳細なガイダンスを提供し、開発者がアニメーション開発スキルを向上させるのに役立ちます ManimCE 최적화 설정은 장면 구조, 객체 유형, 애니메이션 클래스에 대한 자세한 가이드를 제공하여 개발자가 애니메이션 개발 실력을 향상시킬 수 있도록 도와줍니다 Manimce-best-practices es un conjunto de reglas para desarrolladores que buscan crear escenas y animaciones con Manim. Ofrece explicaciones detalladas y ejemplos de código para la estructura de escenas, tipos de mobjects y animaciones. Manimce-best-practices est un ensemble de règles pour les développeurs qui souhaitent créer des scènes et des animations avec Manim. Il propose des explications détaillées et des exemples de code pour la structure de scènes, les types de mobjects et les animations. Manimce-best-practices ist eine Sammlung von Regeln für Entwickler, die Szenen und Animationen mit Manim erstellen möchten. Es bietet detaillierte Erklärungen und Codebeispiele für die Szenenstruktur, Mobject-Typen und Animationen. O Manimce é uma ferramenta para criar animações personalizadas. Aprenda a configurá-lo com as melhores práticas Manimce - инструмент для создания анимаций. Узнайте, как настроить его с помощью лучших практик Manimce هو أداة لإنشاء الرسوم المتحركة المخصصة. تعرف على كيفية ضبطه باستخدام أفضل الممارسات how to use manimce-best-practices manimce-best-practices tutorial manimce scene structure mobject management in manimce animation timing in manimce manimce-best-practices setup guide manimce alternative tools mastering manimce animations manimce development best practices ManimCE 最佳实践 AI 动画开发 场景结构 物体类型 动画类 创建动画 转换动画 Fade 动画 Write 动画 Provides detailed explanations of scene structure and construct methods Covers mobject types, including VMobject, Groups, and positioning techniques Includes guides on animation classes, playing animations, and timing control Offers tutorials on creation animations, such as Create, Write, and Fade References key files, including rules/scenes.md and rules/animations.md Supports developers in building complex scenes and animations with manimce manimce-best-practices is a comprehensive skill for mastering manimce, covering scene structure, mobject types, and animation classes to enhance AI agent development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gyumaruya/minions/context-loader', 'community', 'gyumaruya', 'minions', 'gyumaruya/minions', 'context-loader', 0, 0, 51, '2026-03-08T01:57:15.391Z', '2026-03-08T02:06:05.483Z', 'fc5702cb289f89bd6241b217c2ea37004e146944a5ac9814b815a79b78a174b4', '{"id":"gyumaruya/minions/context-loader","name":"context-loader","description":{"en":"The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI has the same knowledge as Claude Code. This skill benefits developers by providing a consistent project context.","zh":"Context Loader 负责加载 `.claude/` 目录中的共享项目上下文，确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"Context Loader は `.claude/` ディレクトリ内の共有プロジェクトコンテキストをロードし、Codex CLI と Claude Code の同期を実現します","ko":"Context Loader는 `.claude/` 디렉토리의 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code가 동일한 지식을 갖도록 합니다","es":"Context Loader carga el contexto del proyecto desde el directorio `.claude/` para asegurarse de que Codex CLI tenga el mismo conocimiento que Claude Code","fr":"Context Loader charge le contexte du projet depuis le répertoire `.claude/` pour s''assurer que Codex CLI ait les mêmes connaissances que Claude Code","de":"Context Loader lädt den Projekt-Kontext aus dem Verzeichnis `.claude/`, um sicherzustellen, dass Codex CLI das gleiche Wissen wie Claude Code hat","pt":"O Context Loader é uma habilidade que carrega o contexto do projeto a partir do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code.","ru":"Context Loader - это навык, который загружает контекст проекта из директории `.claude/`, чтобы обеспечить совместимость Codex CLI и Claude Code.","ar":"مرشح السياق هو مهارة تقوم بتحميل سياق المشروع من الدليل `.claude/` لضمان توافق Codex CLI مع Claude Code."},"seo":{"title":{"en":"context-loader: Setup Guide for AI Agents | AI Agent Skill","zh":"Context Loader Setup Guide - AI工具","ja":"Context Loader ベストプラクティス - AIエージェント","ko":"Context Loader 설정 가이드 - 인공지능 툴","es":"Guía de Configuración de Context Loader para Agents de In...","fr":"Guide de Configuration de Context Loader pour Outils d''In...","de":"Einrichtungsleitfaden für Context Loader in KI-Agents","pt":"Guia de Configuração do Context Loader: Carregamento de C...","ru":"ИИ Агенты: Настройка Context Loader для Загрузки Контекст...","ar":"إعداد مرشح السياق: دليل على تحميل سياق المشروع"},"description":{"en":"Discover how to load shared project context with context-loader. Learn to ensure Codex CLI has the same knowledge as Claude Code and get started today!","zh":"了解 Context Loader 的工作原理，如何在项目中加载共享上下文，确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"Context Loader の機能と、プロジェクトで共有コンテキストをロードする方法について学びます。Codex CLI と Claude Code の同期を実現します","ko":"Context Loader가 어떻게 작동하는지 알아보세요. 프로젝트에서 공유 컨텍스트를 로드하여 Codex CLI와 Claude Code가 동일한 지식을 갖도록 합니다","es":"Aprende a configurar Context Loader para cargar el contexto del proyecto y asegurarte de que Codex CLI tenga el mismo conocimiento que Claude Code","fr":"Découvrez comment configurer Context Loader pour charger le contexte du projet et vous assurer que Codex CLI ait les mêmes connaissances que Claude Code","de":"Erfahren Sie, wie Sie Context Loader konfigurieren, um den Projekt-Kontext zu laden und sicherzustellen, dass Codex CLI das gleiche Wissen wie Claude Code hat","pt":"Aprenda a configurar o Context Loader para carregar o contexto do projeto e garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code.","ru":"Узнайте, как настроить Context Loader для загрузки контекста проекта и обеспечить совместимость Codex CLI и Claude Code.","ar":"تعرف على كيفية إعداد مرشح السياق لتحميل سياق المشروع وضمان توافق Codex CLI مع Claude Code."},"definition":{"en":"context-loader is a skill that loads shared project context from the .claude/ directory to ensure consistency between Codex CLI and Claude Code","zh":"Context Loader 是一种 AI 工具，用于加载共享项目上下文，确保不同工具之间的知识一致性","ja":"Context Loader は、共有プロジェクトコンテキストをロードし、ツール間の知識の一貫性を確保する AI エージェントです","ko":"Context Loader는 공유 프로젝트 컨텍스트를 로드하여 도구 간 지식 일관성을 보장하는 인공지능 툴입니다","es":"Context Loader es una habilidad que carga el contexto del proyecto para asegurarse de que Codex CLI tenga el mismo conocimiento que Claude Code","fr":"Context Loader est une compétence qui charge le contexte du projet pour s''assurer que Codex CLI ait les mêmes connaissances que Claude Code","de":"Context Loader ist eine Fähigkeit, die den Projekt-Kontext lädt, um sicherzustellen, dass Codex CLI das gleiche Wissen wie Claude Code hat","pt":"O Context Loader é uma habilidade que carrega o contexto do projeto para garantir a compatibilidade entre o Codex CLI e o Claude Code.","ru":"Context Loader - это навык, который загружает контекст проекта для обеспечения совместимости между Codex CLI и Claude Code.","ar":"مرشح السياق هو مهارة لتحميل سياق المشروع لضمان التوافق بين Codex CLI و Claude Code."},"features":{"en":["Loads coding rules from .claude/rules/ directory","Reads files such as coding-principles.md and dev-environment.md","Ensures Codex CLI has the same knowledge as Claude Code","Activates at the beginning of every task to load project context","Supports files in markdown format, such as .md"],"zh":["加载 `.claude/rules/` 目录中的编码规则","支持多种文件格式，包括 Markdown","确保 Codex CLI 与 Claude Code 的知识一致性","自动加载共享项目上下文","支持 `.claude/` 目录中的多种文件类型"],"ja":["`.claude/rules/` ディレクトリ内のコーディングルールのロード","Markdown を含む複数のファイル形式のサポート","Codex CLI と Claude Code の知識の一貫性の確保","共有プロジェクトコンテキストの自動ロード","`.claude/` ディレクトリ内の複数のファイルタイプのサポート"],"ko":["`.claude/rules/` 디렉토리의 코딩 규칙 로드","Markdown를 포함한 여러 파일 형식 지원","Codex CLI와 Claude Code의 지식 일관성 보장","공유 프로젝트 컨텍스트의 자동 로드","`.claude/` 디렉토리의 여러 파일 유형 지원"],"es":["Carga de reglas de codificación desde `.claude/rules/`","Compatibilidad con Codex CLI y Claude Code","Carga de contexto del proyecto desde el directorio `.claude/`","Soporte para archivos como `coding-principles.md` y `dev-environment.md`","Ejecución automática al inicio de cada tarea","Integración con herramientas de desarrollo como uv, ruff, ty y pytest"],"fr":["Chargement des règles de codage depuis `.claude/rules/`","Compatibilité avec Codex CLI et Claude Code","Chargement du contexte du projet depuis le répertoire `.claude/`","Prise en charge de fichiers tels que `coding-principles.md` et `dev-environment.md`","Exécution automatique au début de chaque tâche","Intégration avec des outils de développement tels que uv, ruff, ty et pytest"],"de":["Laden von Codierregeln aus `.claude/rules/`","Kompatibilität mit Codex CLI und Claude Code","Laden des Projekt-Kontexts aus dem Verzeichnis `.claude/`","Unterstützung für Dateien wie `coding-principles.md` und `dev-environment.md`","Automatische Ausführung am Anfang jeder Aufgabe","Integration mit Entwicklungstools wie uv, ruff, ty und pytest"],"pt":["Carregamento de regras de codificação a partir do diretório `.claude/rules/`","Leitura de arquivos de regras de codificação, como `coding-principles.md` e `dev-environment.md`","Integração com o Codex CLI para garantir a compatibilidade com o Claude Code","Ativação automática no início de cada tarefa para garantir o contexto correto","Suporte a diretórios personalizados para armazenar regras de codificação"],"ru":["Загрузка правил кодирования из директории `.claude/rules/`","Чтение файлов правил кодирования, таких как `coding-principles.md` и `dev-environment.md`","Интеграция с Codex CLI для обеспечения совместимости с Claude Code","Автоматическая активация в начале каждой задачи для обеспечения правильного контекста","Поддержка пользовательских директорий для хранения правил кодирования"],"ar":["تحميل قواعد البرمجة من الدليل `.claude/rules/`","قراءة ملفات قواعد البرمجة، مثل `coding-principles.md` و `dev-environment.md`","تكامل مع Codex CLI لضمان التوافق مع Claude Code","التنشيط التلقائي في بداية كل مهمة لضمان السياق الصحيح","دعم الدلائل المخصصة لتخزين قواعد البرمجة"]},"keywords":{"en":["how to use context-loader","context-loader setup guide","what is context-loader","context-loader alternative","context-loader vs Claude Code","context-loader install","loading project context with context-loader"],"zh":["Context Loader","AI 工具","共享项目上下文","Codex CLI","Claude Code","加载编码规则","Markdown 支持"],"ja":["Context Loader","AI エージェント","共有プロジェクトコンテキスト","Codex CLI","Claude Code","コーディングルールのロード","Markdown サポート"],"ko":["Context Loader","인공지능 툴","공유 프로젝트 컨텍스트","Codex CLI","Claude Code","코딩 규칙 로드","Markdown 지원"],"es":["Context Loader","Agents de Inteligencia Artificial","Codex CLI","Claude Code","carga de contexto del proyecto","reglas de codificación","desarrollo de software","herramientas de desarrollo","uv","ruff","ty","pytest"],"fr":["Context Loader","Outils d''Intelligence Artificielle","Codex CLI","Claude Code","chargement du contexte du projet","règles de codage","développement de logiciels","outils de développement","uv","ruff","ty","pytest"],"de":["Context Loader","KI-Agents","Codex CLI","Claude Code","Laden des Projekt-Kontexts","Codierregeln","Software-Entwicklung","Entwicklungstools","uv","ruff","ty","pytest"],"pt":["Context Loader","Carregamento de contexto de projeto","Codex CLI","Claude Code","Regras de codificação","Dev environment","Configuração do Context Loader","Guia de configuração","Setup Context Loader"],"ru":["Context Loader","Загрузка контекста проекта","Codex CLI","Claude Code","Правила кодирования","Dev среда","Настройка Context Loader","Руководство по настройке","ИИ Агенты"],"ar":["مرشح السياق","تحميل سياق المشروع","Codex CLI","Claude Code","قواعد البرمجة","بيئة التطوير","إعداد مرشح السياق","دليل الإعداد","أدوات الذكاء الاصطناعي"]}},"owner":"gyumaruya","repo":"minions","repoPath":"gyumaruya/minions","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.391Z","topics":[],"category":"community","skillMd":{"name":"context-loader","description":"ALWAYS activate this skill at the start of every task. Load project context from .claude/ directory including coding rules, design decisions, and documentation before executing any task.","bodyPreview":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements","body":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements\n├── language.md            # Think in English, respond in Japanese\n├── security.md            # Secrets, validation, SQLi/XSS prevention\n├── testing.md             # TDD, AAA pattern, 80% coverage\n└── codex-delegation.md    # (skip - not relevant for Codex itself)\n```\n\n### Step 2: Load Design Documentation\n\nRead `.claude/docs/DESIGN.md` for:\n- Architecture decisions\n- Implementation patterns\n- Library choices and constraints\n- TODO items and open questions\n\n### Step 3: Check Library Documentation\n\nIf the task involves specific libraries, read relevant files from:\n```\n.claude/docs/libraries/\n```\n\n### Step 4: Execute Task\n\nWith the loaded context, execute the requested task following:\n- Coding principles from rules\n- Design decisions from DESIGN.md\n- Library constraints from docs\n\n## Key Rules to Remember\n\nAfter loading, always follow these principles:\n\n1. **Simplicity first** - Choose readable code over complex\n2. **Single responsibility** - One function/class does one thing\n3. **Type hints required** - All functions need annotations\n4. **Use uv** - Never use pip directly\n5. **Security** - No hardcoded secrets, validate input, parameterize SQL\n\n## Language Protocol\n\n- **Thinking/Reasoning**: English\n- **Code**: English (variables, functions, comments)\n- **User communication**: Japanese (when reporting back through Claude Code)\n\n## Output\n\nAfter loading context, briefly confirm:\n- Rules loaded\n- Design document status\n- Ready to execute task\n"},"lastSynced":"2026-03-08T02:06:05.483Z","agentAnalysis":{"suitability":{"en":"Perfect for Codex CLI Agents needing consistent project context and knowledge synchronization with Claude Code.","zh":"非常适合需要与 Claude Code 一致的项目背景和知识同步的 Codex CLI 代理。","ja":"Claude Code と一貫したプロジェクトの背景と知識の同期が必要な Codex CLI エージェントに最適です。","ko":"Claude Code 와 일관된 프로젝트 컨텍스트와 지식 동기화를 필요로 하는 Codex CLI 에이전트에 적합합니다.","es":"Perfecto para agentes de Codex CLI que necesitan un contexto de proyecto y sincronización de conocimientos consistentes con Claude Code.","fr":"Parfait pour les agents Codex CLI ayant besoin d''un contexte de projet et d''une synchronisation des connaissances cohérents avec Claude Code.","de":"Perfekt für Codex-CLI-Agents, die einen konsistenten Projektkontext und eine Wissenssynchronisierung mit Claude Code benötigen.","pt":"Perfeito para Agentes CLI Codex que precisam de contexto de projeto consistente e sincronização de conhecimento com Claude Code.","ru":"Идеально подходит для агентов CLI Codex, которым необходим постоянный контекст проекта и синхронизация знаний с Claude Code.","ar":"مثالي لعميل كودكس CLI الذي يحتاج إلى سياق مشروع متسق وتزامن المعرفة مع كلود كود."},"recommendation":{"en":"Empowers agents to load shared project context from the .claude/ directory, ensuring consistency with Claude Code through files like coding-principles.md and dev-environment.md, and providing a unified knowledge base for tasks.","zh":"使代理能够从 .claude/ 目录加载共享的项目背景，通过 coding-principles.md 和 dev-environment.md 等文件，确保与 Claude Code 一致，并为任务提供统一的知识库。","ja":"エージェントが .claude/ ディレクトリから共有プロジェクトの背景を読み込み、coding-principles.md や dev-environment.md などのファイルを介して Claude Code と一貫性を保ち、タスクに統一された知識ベースを提供することを可能にします。","ko":"에이전트가 .claude/ 디렉토리에서 공유 프로젝트 컨텍스트를 로드하여 coding-principles.md 및 dev-environment.md 등의 파일을 통해 Claude Code 와 일관성을 유지하고, 작업을 위한 통합 지식베이스를 제공합니다.","es":"Habilita a los agentes a cargar el contexto de proyecto compartido desde el directorio .claude/, garantizando la coherencia con Claude Code a través de archivos como coding-principles.md y dev-environment.md, y proporcionando una base de conocimientos unificada para tareas.","fr":"Permet aux agents de charger le contexte de projet partagé à partir du répertoire .claude/, en garantissant la cohérence avec Claude Code via des fichiers tels que coding-principles.md et dev-environment.md, et en fournissant une base de connaissances unifiée pour les tâches.","de":"Ermächtigt die Agents, den gemeinsamen Projektkontext aus dem .claude/-Verzeichnis zu laden, die Konsistenz mit Claude Code durch Dateien wie coding-principles.md und dev-environment.md sicherzustellen und eine einheitliche Wissensbasis für Aufgaben bereitzustellen.","pt":"Habilita os agentes a carregar o contexto do projeto compartilhado a partir do diretório .claude/, garantindo a consistência com Claude Code por meio de arquivos como coding-principles.md e dev-environment.md, e fornecendo uma base de conhecimento unificada para tarefas.","ru":"Позволяет агентам загружать общий контекст проекта из директории .claude/, обеспечивая согласованность с Claude Code через файлы, такие как coding-principles.md и dev-environment.md, и предоставляя унифицированную базу знаний для задач.","ar":"تمكّن العميل من تحميل السياق المشترك للمشروع من 目录 .claude/، مما يضمن الاتساق مع كلود كود من خلال الملفات مثل coding-principles.md و dev-environment.md، وتوفير قاعدة معرفة موحدة للمهام."},"useCases":{"en":["Loading coding rules for project consistency","Ensuring dev environment requirements are met","Synchronizing knowledge with Claude Code for tasks"],"zh":["为项目一致性加载编码规则","确保满足开发环境的要求","与 Claude Code 同步知识以执行任务"],"ja":["プロジェクトの一貫性のためにコーディングルールを読み込み","開発環境の要件を満たすことを保証","タスクの実行のために Claude Code と知識を同期"],"ko":["프로젝트 일관성을 위해 코딩 규칙 로드","개발 환경 요구 사항满足 보장","작업을 위한 Claude Code 와 지식 동기화"],"es":["Cargar reglas de codificación para la coherencia del proyecto","Garantizar que se cumplan los requisitos del entorno de desarrollo","Sincronizar conocimientos con Claude Code para tareas"],"fr":["Charger les règles de codage pour la cohérence du projet","Assurer que les exigences de l''environnement de développement soient satisfaites","Synchroniser les connaissances avec Claude Code pour les tâches"],"de":["Laden von Codierregeln für die Projektkonsistenz","Sicherstellen, dass die Anforderungen der Entwicklungsumgebung erfüllt werden","Synchronisieren von Wissen mit Claude Code für Aufgaben"],"pt":["Carregar regras de codificação para consistência do projeto","Garantir que os requisitos do ambiente de desenvolvimento sejam atendidos","Sincronizar conhecimento com Claude Code para tarefas"],"ru":["Загрузка правил кодирования для согласованности проекта","Обеспечение выполнения требований к среде разработки","Синхронизация знаний с Claude Code для задач"],"ar":["تحميل قواعد الترميز لاتساق المشروع","ضمان выполнение متطلبات بيئة التطوير","مزامنة المعرفة مع كلود كود للمهام"]},"limitations":{"en":["Requires access to the .claude/ directory","Must run at the beginning of every task","Specific to Codex CLI and Claude Code integration"],"zh":[".claude/ 目录的访问权限","必须在每个任务开始时运行","特定于 Codex CLI 和 Claude Code 集成"],"ja":[".claude/ ディレクトリへのアクセス権","各タスクの開始時に実行する必要","Codex CLI と Claude Code の統合に特化"],"ko":[".claude/ 디렉토리에 대한 접근 권한","모든 작업의 시작 시 실행해야 함","Codex CLI 및 Claude Code 통합에 특정"],"es":["Requiere acceso al directorio .claude/","Debe ejecutarse al principio de cada tarea","Específico para la integración de Codex CLI y Claude Code"],"fr":["Nécessite l''accès au répertoire .claude/","Doit s''exécuter au début de chaque tâche","Spécifique à l''intégration de Codex CLI et Claude Code"],"de":["Erfordert den Zugriff auf das .claude/-Verzeichnis","Muss am Anfang jeder Aufgabe ausgeführt werden","Spezifisch für die Integration von Codex CLI und Claude Code"],"pt":["Requer acesso ao diretório .claude/","Deve ser executado no início de cada tarefa","Específico para integração do Codex CLI e Claude Code"],"ru":["Требует доступа к директории .claude/","Должно быть выполнено в начале каждой задачи","Специфично для интеграции Codex CLI и Claude Code"],"ar":["يتطلب الوصول إلى الدليل .claude/","يجب تشغيله في بداية كل مهمة","محدد للتكامل بين كودكس CLI و كلود كود"]},"version":4},"contentHash":"fc5702cb289f89bd6241b217c2ea37004e146944a5ac9814b815a79b78a174b4","qualityScore":51}');
