INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gyumaruya/minions/context-loader', 'context-loader', 'gyumaruya', 'minions', 'community', 'context-loader gyumaruya minions community The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI has the same knowledge as Claude Code. This skill benefits developers by providing a consistent project context. Context Loader 负责加载 `.claude/` 目录中的共享项目上下文，确保 Codex CLI 与 Claude Code 具有相同的知识 Context Loader は `.claude/` ディレクトリ内の共有プロジェクトコンテキストをロードし、Codex CLI と Claude Code の同期を実現します Context Loader는 `.claude/` 디렉토리의 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code가 동일한 지식을 갖도록 합니다 Context Loader carga el contexto del proyecto desde el directorio `.claude/` para asegurarse de que Codex CLI tenga el mismo conocimiento que Claude Code Context Loader charge le contexte du projet depuis le répertoire `.claude/` pour s''assurer que Codex CLI ait les mêmes connaissances que Claude Code Context Loader lädt den Projekt-Kontext aus dem Verzeichnis `.claude/`, um sicherzustellen, dass Codex CLI das gleiche Wissen wie Claude Code hat O Context Loader é uma habilidade que carrega o contexto do projeto a partir do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code. Context Loader - это навык, который загружает контекст проекта из директории `.claude/`, чтобы обеспечить совместимость Codex CLI и Claude Code. مرشح السياق هو مهارة تقوم بتحميل سياق المشروع من الدليل `.claude/` لضمان توافق Codex CLI مع Claude Code. how to use context-loader context-loader setup guide what is context-loader context-loader alternative context-loader vs Claude Code context-loader install loading project context with context-loader Context Loader AI 工具 共享项目上下文 Codex CLI Claude Code 加载编码规则 Markdown 支持 Loads coding rules from .claude/rules/ directory Reads files such as coding-principles.md and dev-environment.md Ensures Codex CLI has the same knowledge as Claude Code Activates at the beginning of every task to load project context Supports files in markdown format, such as .md context-loader is a skill that loads shared project context from the .claude/ directory to ensure consistency between Codex CLI and Claude Code');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Hypogenic-AI/news-from-future-ai-aed4-claude/paper-finder', 'community', 'Hypogenic-AI', 'news-from-future-ai-aed4-claude', 'Hypogenic-AI/news-from-future-ai-aed4-claude', 'paper-finder', 0, 0, 51, '2026-03-08T01:57:15.396Z', '2026-03-08T02:06:21.542Z', '2c652be8b402a40b7ede85116e20c60323e3ea98ca2f10393d3b94e0fa3fd59b', '{"id":"Hypogenic-AI/news-from-future-ai-aed4-claude/paper-finder","name":"paper-finder","description":{"en":"paper-finder facilitates systematic paper discovery and prioritization for research projects, aiding in literature reviews and methodology references. It benefits researchers and academics.","zh":"Paper Finder 是一个系统化的文献发现和优先级排序工具，帮助研究人员找到相关论文和基线论文","ja":"Paper Finder は文献の発見と優先順位付けをシステム化したツールで、研究者が関連する論文や基線論文を探すのに役立ちます","ko":"Paper Finder는 시스템화된 논문 발견 및 우선순위 지정 도구로 연구자가 관련 논문 및 기준 논문을 찾는 데 도움을 줍니다","es":"Paper-finder es un sistema de descubrimiento y priorización de papers de investigación de IA. Utiliza Python y CLI para encontrar papers relevantes","fr":"Paper-finder est un système de découverte et de priorisation d''articles de recherche en intelligence artificielle. Il utilise Python et CLI pour trouver des articles pertinents","de":"Paper-finder ist ein System zur Entdeckung und Priorisierung von Forschungspapieren zur KI-Forschung. Es verwendet Python und CLI, um relevante Papiere zu finden","pt":"O Paper Finder é uma ferramenta de pesquisa que ajuda a descobrir e priorizar artigos de pesquisa de forma sistemática","ru":"Paper Finder - это инструмент для поиска научных статей, который помогает систематически обнаруживать и приоритизировать статьи","ar":"أداة البحث عن الأوراق البحثية Paper Finder تساعد في اكتشاف وتحديد الأولويات البحثية بشكل منهجي"},"seo":{"title":{"en":"paper-finder: Systematic Paper Discovery Setup Guide | AI...","zh":"Paper Finder 使用指南：AI 辅助文献检索","ja":"Paper Finder の設定方法：AI エージェントを利用した文献検索","ko":"Paper Finder 설정 가이드: AI 에이전트를 활용한 논문 검색","es":"Guía de configuración de paper-finder para investigación ...","fr":"Guide de démarrage de paper-finder pour la recherche en i...","de":"Einrichtungsleitfaden für paper-finder in der KI-Forschung","pt":"Guia de Configuração do Paper Finder para Desenvolvedores","ru":"Настройка Paper Finder: Инструмент для поиска научных статей","ar":"إعداد أداة البحث عن الأوراق البحثية Paper Finder"},"description":{"en":"Unlock efficient research with paper-finder. Discover how to use the find_papers.py script to prioritize papers and boost your literature review","zh":"Paper Finder 是一个 AI 驱动的文献检索工具，帮助研究人员快速找到相关论文和基线论文","ja":"Paper Finder は AI エージェントを利用した文献検索ツールで、研究者が関連する論文や基線論文を迅速に検索できる","ko":"Paper Finder는 AI 에이전트를 활용한 논문 검색 도구로 연구자가 관련 논문과 기준 논문을 신속하게 검색할 수 있습니다","es":"Descubre cómo utilizar paper-finder para encontrar y priorizar papers de investigación de IA de manera sistemática","fr":"Découvrez comment utiliser paper-finder pour découvrir et prioriser les articles de recherche en intelligence artificielle de manière systématique","de":"Erfahren Sie, wie Sie paper-finder verwenden können, um Forschungspapiere zur KI-Forschung systematisch zu finden und zu priorisieren","pt":"Aprenda a usar o Paper Finder para descobrir e priorizar artigos de pesquisa de forma sistemática","ru":"Используйте Paper Finder для системного поиска и приоритизации научных статей","ar":"استخدم أداة البحث عن الأوراق البحثية Paper Finder لاكتشاف وتحديد الأولويات البحثية بشكل منهجي"},"definition":{"en":"paper-finder is a systematic paper discovery and prioritization tool for research projects, utilizing a helper script for efficient literature reviews","zh":"Paper Finder 是一个利用 Python 脚本的 AI 驱动文献检索工具","ja":"Paper Finder は Python スクリプトを利用した AI エージェントの文献検索ツール","ko":"Paper Finder는 Python 스크립트를 활용한 AI 에이전트의 논문 검색 도구입니다","es":"Paper-finder es una herramienta de IA que ayuda a los investigadores a encontrar y priorizar papers de investigación de manera sistemática","fr":"Paper-finder est un outil d''IA qui aide les chercheurs à découvrir et à prioriser les articles de recherche de manière systématique","de":"Paper-finder ist ein KI-Tool, das Forschern hilft, Forschungspapiere systematisch zu finden und zu priorisieren","pt":"Paper Finder é uma ferramenta de inteligência artificial para pesquisa que realiza busca sistemática de artigos","ru":"Paper Finder - это инструмент ИИ для поиска научных статей, который выполняет системный поиск статей","ar":"أداة البحث عن الأوراق البحثية Paper Finder هي أداة ذكاء اصطناعي للبحث التي تقوم بالبحث المنهجي عن المقالات"},"features":{"en":["Utilizes the find_papers.py script for paper discovery","Supports quick search mode with the --mode fast option","Runs from the workspace using a Python script","Facilitates building a citation list for research papers","Aids in finding baseline papers for experiments"],"zh":["系统化的文献发现和优先级排序","快速搜索相关论文和基线论文","支持 Python 脚本","提供命令行界面（CLI）","可以使用 ''--mode fast'' 选项进行快速搜索"],"ja":["文献の発見と優先順位付けをシステム化","関連する論文や基線論文を迅速に検索","Python スクリプトをサポート","コマンドラインインターフェース（CLI）を提供","''--mode fast'' オプションを使用して高速検索"],"ko":["시스템화된 논문 발견 및 우선순위 지정","관련 논문 및 기준 논문을 신속하게 검색","Python 스크립트 지원","명령줄 인터페이스（CLI） 제공","''--mode fast'' 옵션을 사용하여 빠른 검색"],"es":["Búsqueda rápida de papers de investigación de IA con la opción --mode fast","Uso de Python y CLI para encontrar papers relevantes","Priorización de papers de investigación para proyectos de investigación","Búsqueda de papers de referencia para experimentos","Creación de listas de citas para papers de investigación"],"fr":["Recherche rapide d''articles de recherche en intelligence artificielle avec l''option --mode fast","Utilisation de Python et CLI pour trouver des articles pertinents","Priorisation d''articles de recherche pour les projets de recherche","Recherche d''articles de référence pour les expériences","Création de listes de citations pour les articles de recherche"],"de":["Schnelle Suche nach Forschungspapieren zur KI-Forschung mit der Option --mode fast","Verwendung von Python und CLI, um relevante Papiere zu finden","Priorisierung von Forschungspapieren für Forschungsprojekte","Suche nach Referenzpapieren für Experimente","Erstellung von Zitationslisten für Forschungspapiere"],"pt":["Busca sistemática de artigos de pesquisa","Priorização de artigos com base na relevância","Suporte à pesquisa de literatura","Opção de modo rápido para busca rápida","Uso de scripts em Python para busca de artigos"],"ru":["Системный поиск научных статей","Приоритизация статей на основе релевантности","Поддержка поиска литературы","Вариант быстрого режима для быстрого поиска","Использование скриптов на Python для поиска статей"],"ar":["البحث المنهجي عن المقالات البحثية","تحديد الأولويات للمقالات بناءً على الأهمية","دعم البحث في الأدبيات","خيار الوضع السريع للبحث السريع","استخدام البرامج النصية بايتون للبحث عن المقالات"]},"keywords":{"en":["how to use paper-finder","paper-finder setup guide","paper-finder alternative","systematic paper discovery","literature review tool","paper-finder install","what is paper-finder","paper-finder vs other research tools"],"zh":["AI 辅助文献检索","Paper Finder","Python 脚本","命令行界面","文献发现","优先级排序","快速搜索","基线论文","相关论文"],"ja":["AI エージェントの文献検索","Paper Finder","Python スクリプト","コマンドラインインターフェース","文献の発見","優先順位付け","高速検索","基線論文","関連する論文"],"ko":["AI 에이전트의 논문 검색","Paper Finder","Python 스크립트","명령줄 인터페이스","논문 발견","우선순위 지정","빠른 검색","기준 논문","관련 논문"],"es":["paper-finder","herramientas de IA","investigación de IA","bibliografía de investigación","priorización de papers","búsqueda de papers","Python","CLI","IA para investigación"],"fr":["paper-finder","outils d''IA","recherche en intelligence artificielle","bibliographie de recherche","priorisation d''articles","recherche d''articles","Python","CLI","IA pour la recherche"],"de":["paper-finder","KI-Tools","KI-Forschung","Forschungsbibliographie","Priorisierung von Forschungspapieren","Suche nach Forschungspapieren","Python","CLI","KI für die Forschung"],"pt":["Paper Finder","ferramenta de pesquisa","inteligência artificial","busca de artigos","priorização de artigos","pesquisa de literatura","Python","script de busca"],"ru":["Paper Finder","инструмент поиска","ИИ","поиск статей","приоритизация статей","поиск литературы","Python","скрипт поиска"],"ar":["أداة البحث عن الأوراق البحثية","أداة البحث","الذكاء الاصطناعي","بحث المقالات","تحديد الأولويات للمقالات","بحث الأدبيات","Python","برنامج نصي للبحث"]}},"owner":"Hypogenic-AI","repo":"news-from-future-ai-aed4-claude","repoPath":"Hypogenic-AI/news-from-future-ai-aed4-claude","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.396Z","topics":[],"category":"community","skillMd":{"name":"paper-finder","description":"Find and search for academic papers using the paper-finder service. Use when conducting literature review, searching for related work, finding baseline papers, or looking for methodology references.","bodyPreview":"# Paper Finder\n\nSystematic paper discovery and prioritization for research projects.\n\n## When to Use\n\n- Starting a literature review\n- Looking for related work on a topic\n- Finding baseline papers for experiments\n- Searching for methodology references\n- Building a citation list for a research paper\n\n## How to Use\n\nRun the helper script from your workspace:\n\n```bash\npython .claude/skills/paper-finder/scripts/find_papers.py \"your research topic\"\n```\n\nOptions:\n- `--mode fast` (default): Quick searc","body":"# Paper Finder\n\nSystematic paper discovery and prioritization for research projects.\n\n## When to Use\n\n- Starting a literature review\n- Looking for related work on a topic\n- Finding baseline papers for experiments\n- Searching for methodology references\n- Building a citation list for a research paper\n\n## How to Use\n\nRun the helper script from your workspace:\n\n```bash\npython .claude/skills/paper-finder/scripts/find_papers.py \"your research topic\"\n```\n\nOptions:\n- `--mode fast` (default): Quick search\n- `--mode diligent`: Thorough search (recommended for comprehensive review)\n- `--format json`: Output as JSON instead of text\n\nExample:\n```bash\npython .claude/skills/paper-finder/scripts/find_papers.py \"hypothesis generation with large language models\" --mode fast\n```\n\n## Search Strategy\n\n### Query Formulation\n\nUse structured queries for better results:\n\n1. **Core concept + Method**: \"transformer attention mechanism\"\n2. **Problem + Domain**: \"few-shot learning natural language processing\"\n3. **Technique + Application**: \"graph neural networks drug discovery\"\n\n### Multi-Stage Search\n\n1. **Broad scan**: Start with general topic terms\n2. **Focused dive**: Use specific method/technique names from initial results\n3. **Citation chase**: Search for highly-cited papers referenced in relevant work\n\n## Citation Prioritization\n\n### Relevance Tiers\n\n| Relevance Score | Priority | Action |\n|-----------------|----------|--------|\n| 3 (High) | Must read | Download PDF, read fully, cite |\n| 2 (Medium) | Should read | Read abstract + intro, cite if relevant |\n| 1 (Low) | Optional | Skim abstract, cite only if needed |\n| 0 (Not relevant) | Skip | Do not include |\n\n### Citation Count Thresholds\n\n| Category | Citation Count | Interpretation |\n|----------|----------------|----------------|\n| Seminal | 1000+ | Foundational work, must cite |\n| Well-established | 100-999 | Widely accepted, cite if relevant |\n| Recent/Emerging | 10-99 | Current research, cite for novelty |\n| New | <10 | Very recent, check publication venue |\n\n### Venue Tiers (ML/AI Focus)\n\n**Tier 1** (Top venues, high credibility):\n- NeurIPS, ICML, ICLR, ACL, EMNLP, CVPR, ICCV\n\n**Tier 2** (Strong venues):\n- AAAI, IJCAI, NAACL, COLING, ECCV, WACV\n\n**Tier 3** (Good venues):\n- *ACL workshops, COLM, EACL, CoNLL\n\n**Preprints** (arXiv):\n- Check for peer-reviewed version first\n- Cite arXiv only if no published version exists\n\n## Screening Workflow\n\n### Phase 1: Title Screening\n- Review titles from search results\n- Mark papers as \"include\", \"exclude\", or \"maybe\"\n- Goal: ~50% reduction\n\n### Phase 2: Abstract Screening\n- Read abstracts for included/maybe papers\n- Evaluate: relevance, methodology, findings\n- Goal: Identify key papers for deeper reading\n\n### Phase 3: Full-Text Review\n- Download and read full PDFs for key papers\n- Extract: methods, results, limitations, citations\n- Use the PDF chunker for detailed reading (see below)\n\n## Output Structure\n\nReturns relevance-ranked papers with:\n- Title, authors, year\n- Abstract (already extracted)\n- URL for download\n- Relevance score (0-3, focus on papers with score >= 2)\n- Citation count\n\n## After Finding Papers\n\n1. Download PDFs for papers with relevance >= 2\n2. Read abstracts first (already provided in output)\n3. Only read full PDFs for most relevant papers\n4. Write notes to literature_review.md immediately\n5. Track citations for references.bib\n\n## Reading Large PDFs\n\nUse the PDF chunker to split papers into smaller PDF files that can be read directly.\nThis preserves all formatting perfectly (unlike text extraction which loses formatting).\n\n**Dependencies:**\n```bash\n# Using uv (recommended):\nuv add pypdf\n\n# Or with pip:\npip install pypdf\n```\n\n**How to run:**\n\n```bash\npython .claude/skills/paper-finder/scripts/pdf_chunker.py <pdf_path>\n```\n\nOptions:\n- `--pages-per-chunk N`: Number of pages per chunk (default: 1)\n- `--output-dir DIR`: Output directory (default: `<pdf_dir>/pages`)\n\n**Output:**\n- Creates PDF chunk files: `<pdf_name>_chunk_001.pdf`, `<pdf_name>_chunk_002.pdf`, etc.\n- Creates a manifest: `<pdf_name>_manifest.txt` listing all chunks with page ranges\n\n**Integration with screening workflow:**\n1. Run the chunker on papers before detailed reading\n2. For abstract skimming: read only chunk 1 (page 1 or pages 1-3)\n3. For deep reading: read ALL chunk PDFs sequentially, writing notes after each\n4. Check the manifest to see how many chunks exist\n5. IMPORTANT: Do not skip chunks - methodology and results are in later chunks\n\n## If Paper-Finder Service Not Running\n\nThe script will show a fallback message. Use manual search instead:\n- arXiv: https://arxiv.org\n- Semantic Scholar: https://www.semanticscholar.org\n- Papers with Code: https://paperswithcode.com\n- Google Scholar: https://scholar.google.com\n\nManual search works well - paper-finder is just a convenience for faster, more targeted results.\n\n## References\n\nSee `references/` folder for:\n- `search_strategies.md`: Detailed search query formulation\n- `prioritization_guide.md`: Extended prioritization criteria\n"},"lastSynced":"2026-03-08T02:06:21.542Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring systematic paper discovery and prioritization for literature reviews and methodology references.","zh":"适合需要系统化论文发现和优先级排序的研究代理，用于文献综述和方法论参考。","ja":"研究エージェントが文献レビューと方法論の参考文献のための体系的な論文の発見と優先順位付けを必要とする場合に最適です。","ko":"연구 에이전트가 문헌 검토와 방법론 참조를 위한 체계적인 논문 발견과 우선 순위를 지정해야 하는 경우에 적합합니다.","es":"Ideal para Agentes de Investigación que requieren descubrimiento y priorización sistemáticos de artículos para revisiones de literatura y referencias de metodología.","fr":"Idéal pour les Agents de Recherche nécessitant une découverte et une priorisation systématiques d''articles pour les revues de littérature et les références méthodologiques.","de":"Ideal für Forschungsagenten, die ein systematisches Auffinden und Priorisieren von Artikeln für Literaturübersichten und Methodenreferenzen erfordern.","pt":"Ideal para Agentes de Pesquisa que exigem descoberta e priorização sistemáticas de artigos para revisões de literatura e referências de metodologia.","ru":"Идеально подходит для агентов-исследователей, требующих системного открытия и приоритизации статей для обзоров литературы и ссылок на методологию.","ar":"مثالي لعميل البحث الذي требует اكتشاف وترتيب منهجي للوثائق من أجل مراجعة الأدبيات والإشارات إلى المنهجية."},"recommendation":{"en":"Empowers agents to facilitate comprehensive content analysis using Python scripts, enabling efficient literature reviews and citation list building through systematic paper discovery and prioritization, leveraging command-line interfaces like `python .claude/skills/paper-finder/scripts/find_papers.py` for topic-specific research.","zh":"赋予代理使用Python脚本进行全面内容分析的能力，通过系统化论文发现和优先级排序，实现高效的文献检索和引文列表构建，利用命令行接口如`python .claude/skills/paper-finder/scripts/find_papers.py`进行主题特定研究。","ja":"Pythonスクリプトを使用して包括的なコンテンツ分析を実行するエージェントを可能にし、体系的な論文の発見と優先順位付けを通じて効率的な文献レビューと引用リストの構築を実現し、`python .claude/skills/paper-finder/scripts/find_papers.py`などのコマンドラインインターフェイスを使用してトピック固有のリサーチを実行します。","ko":"에이전트가 Python 스크립트를 사용하여 포괄적인 콘텐츠 분석을 수행할 수 있도록 하여 체계적인 논문 발견과 우선 순위를 통한 효율적인 문헌 검토와 인용 목록 구성을 가능하게 하며, `python .claude/skills/paper-finder/scripts/find_papers.py`와 같은 명령行 인터페이스를 사용하여 주제별 연구를 수행할 수 있습니다.","es":"Habilita a los agentes a facilitar un análisis de contenido integral utilizando scripts de Python, permitiendo revisiones de literatura eficientes y la construcción de listas de citas a través del descubrimiento y la priorización sistemáticos de artículos, aprovechando interfaces de línea de comandos como `python .claude/skills/paper-finder/scripts/find_papers.py` para investigaciones temáticas.","fr":"Permet aux agents de faciliter une analyse de contenu complète en utilisant des scripts Python, permettant des revues de littérature efficaces et la construction de listes de citations grâce à la découverte et à la priorisation systématiques d''articles, en exploitant des interfaces de ligne de commande comme `python .claude/skills/paper-finder/scripts/find_papers.py` pour des recherches thématiques.","de":"Ermächtigt Agenten, eine umfassende Inhaltsanalyse mithilfe von Python-Skripten zu ermöglichen, wodurch effiziente Literaturübersichten und Aufbau von Zitationslisten durch systematisches Auffinden und Priorisieren von Artikeln ermöglicht werden, indem Befehlszeilenoberflächen wie `python .claude/skills/paper-finder/scripts/find_papers.py` für themenspezifische Recherchen genutzt werden.","pt":"Habilita os agentes a facilitar uma análise abrangente de conteúdo usando scripts Python, permitindo revisões de literatura eficientes e construção de listas de citações por meio da descoberta e priorização sistemáticas de artigos, utilizando interfaces de linha de comando como `python .claude/skills/paper-finder/scripts/find_papers.py` para pesquisas específicas de tópico.","ru":"Наделяет агентов возможностью проводить всесторонний анализ контента с помощью скриптов Python, обеспечивая эффективные обзоры литературы и построение списков цитат посредством системного открытия и приоритизации статей, используя интерфейсы командной строки, такие как `python .claude/skills/paper-finder/scripts/find_papers.py`, для тематических исследований.","ar":"يمنح الوكلاء القدرة على تسهيل تحليل محتوى شاملة باستخدام نصوص Python، مما يسمح بمراجعة الأدبيات بكفاءة وبناء قائمة الاستشهادات من خلال اكتشاف وترتيب منهجي للوثائق، باستخدام واجهات سطر الأوامر مثل `python .claude/skills/paper-finder/scripts/find_papers.py` لأبحاث مواضيعية محددة."},"useCases":{"en":["Automating literature reviews for research projects","Finding baseline papers for experiments using `--mode fast` option","Building citation lists for research papers through systematic paper discovery"],"zh":["自动化研究项目的文献综述","使用`--mode fast`选项找到实验的基线论文","通过系统化论文发现构建研究论文的引文列表"],"ja":["研究プロジェクトの文献レビューを自動化する","`--mode fast`オプションを使用して実験のベースライン論文を見つける","体系的な論文の発見を通じて研究論文の引用リストを構築する"],"ko":["연구 프로젝트를 위한 문헌 검토 자동화","`--mode fast` 옵션을 사용하여 실험을 위한 기준 논문을 찾는 것","체계적인 논문 발견을 통해 연구 논문의 인용 목록을 구축하는 것"],"es":["Automatizar revisiones de literatura para proyectos de investigación","Encontrar artículos básicos para experimentos utilizando la opción `--mode fast`","Construir listas de citas para artículos de investigación a través del descubrimiento sistemático de artículos"],"fr":